window.__LEX={"G2900":"<h1>krataios</h1>\n<p>Strong n° 2900 <i>Prononciation [krat-ah-yos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>puissant, fort\n<ol type=\"a\">\n<li>du pouvoir puissant de Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κραταιός, ά, όν</b> <span>[ᾰ]</span> fort, robuste, puissant, <i>p. opp. à</i> μαλακός, LUC. <i>Anach. 28 ; en parl. de pers</i>. OD. <i>15, 242 ; 18, 382 ;</i> PD. <i>N. 4, 40 ; d’un lion,</i> IL. <i>11, 119 ; des membres du corps :</i> κρ. χεῖρες, SOPH. <i>Ph. 1011 ;</i> χεὶρ κρ. EUR. <i>H.f. 964 ;</i> κρ. βραχίων, POÈT. (PLUT. <i>M. 967</i> c) ; <i>d’armes :</i> κρ. ἔγχος, PD. <i>P. 6, 34,</i> forte javeline, <i>etc. ; de choses abstraites,</i> ESCHL. <i>Pr. 429 ; t. d’astrol</i>. οἱ κραταιοί, JAMBL. les constellations qui règlent la destinée des hommes.<br><span>•<i> Cp</i>. -ότερος, ANTH. <i>11, 324</i>.<br><span><b>Étym</b>. κράτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κραταιος - κραταιός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2901":"<h1>krataioo</h1>\n<p>Strong n° 2901 <i>Prononciation [krat-ah-yo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fortifier, rendre fort</li>\n<li>être rendu fort, augmenter en force, se fortifier</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κραταιόω-ῶ</b> <span>[ᾰ]</span> fortifier, affermir, NT. <i>Luc. 1, 80 ; Eph. 3, 16 ; 1Cor. 16, 13</i>.<br><span><b>Étym</b>. κραταιός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κραταιοω - κραταιόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2902":"<h1>krateo</h1>\n<p>Strong n° 2902 <i>Prononciation [krat-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir le pouvoir, être puissant, être fort\n<ol type=\"a\">\n<li>être un chef, être le maître, gouverner</li>\n</ol>\n</li>\n<li>prendre possession de\n<ol type=\"a\">\n<li>devenir le maître de, obtenir</li>\n<li>se saisir de</li>\n<li>saisir, prendre, retenir</li>\n<ol>\n<li>mettre la main sur quelqu'un pour le remettre à une autorité</li>\n</ol>\n</ol>\n</li>\n<li>tenir\n<ol type=\"a\">\n<li>tenir à la main</li>\n<li>tenir fermement, ne pas lâcher, ne pas laisser partir\n<ol>\n<li>garder avec soin et fidèlement</li>\n</ol>\n</li>\n<li>continuer à tenir, retenir\n<ol>\n<li>de la mort continuant à retenir quelqu'un</li>\n<li>tenir sous contrôle, contenir</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρατέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἐκράτησα, <i>pf</i>. κεκράτηκα)</span> <span>[ᾰ]</span><br><b>   I</b> être fort, puissant, IL. <i>16, 172, etc. ;</i><br><b>   II</b> <i>p. suite,</i> être le maître, <i>d’où :</i><br><b>      1</b> dominer, régner : Ἤλιδα ὅθι κρατέουσιν Ἐπειοί, OD. <i>13, 275,</i> l’Élide où dominent les Épéies ; ἅπας τραχὺς ὅστις ἂν νέον κρατῇ, ESCHL. <i>Pr. 35,</i> tout maître est rude, qui exerce le pouvoir depuis peu ; ὁ κρατῶν, SOPH. <i>Ant. 738,</i> le maître ; οἱ κρατοῦντες, ESCHL. <i>Ch. 265 ;</i> SOPH. <i>El. 340,</i> les maîtres, les puissants ; ἡ κρατοῦσα, ESCHL. <i>Ch. 734,</i> la maîtresse de la maison ; τὸ κρατοῦν, EUR. <i>Andr. 133 ;</i> PLAT. <i>Leg. 714</i> c, <i>etc</i>. la puissance souveraine, la domination ; <i>avec le gén</i>. κρ. Ἀργείων, IL. <i>1, 79 ;</i> πάντων, IL. <i>1, 288,</i> régner sur les Argiens, sur tous ; <i>avec le dat</i>. κρ. ἀνδράσι καὶ θεοῖσι, OD. <i>16, 265,</i> régner sur les hommes et sur les dieux ; κρ. νεκύεσσιν, OD. <i>11, 485,</i> régner sur les morts ; <i>avec une prép</i>. κρ. ἐν Ἰδαίᾳ χθονί, EUR. <i>El. 4,</i> régner sur la terre de l’Ida ;<br><b>      2</b> être le maître <i>ou</i> le possesseur de, <i>gén</i>. SOPH. <i>Aj. 1337 ;</i> κρατῶ τοῦδε, je suis maître de cela, cela m’appartient, j’y ai droit, SOPH. <i>O.R. 409 ;</i><br><b>      3</b> <i>abs</i>. commander, ordonner, ESCHL. <i>Ag. 10 ;</i> EUR. <i>Hec. 282 ; t. techn. avec un rég. de chose :</i> κρ. στελεοῦ, PHIL. BYZ. peser sur le manche d’un outil, le faire basculer ; <i>au pass</i>. κρατεῖσθαι, être commandé <i>ou</i> actionné, <i>en parl. d’une pièce mise en mouvement par une autre,</i> PHIL. BYZ. ;<br><b>      4</b> contraindre, forcer, DH. <i>9, 52 ;</i><br><b>   III</b> devenir le maître, <i>d’où :</i><br><b>      1</b> se rendre maître de, s’emparer de, <i>avec le gén. :</i> τῆς ἀρχῆς, HDT. <i>1, 92,</i> du pouvoir ; τῆς θαλάττης, PLAT. <i>Menex. 239</i> e, de la mer ; <i>avec l’acc. :</i> κρ. πᾶσαν αἶαν, ESCHL. <i>Suppl. 255,</i> de toute la terre, <i>etc. ; p. suite,</i> saisir, tenir fortement : τινα, BATR. <i>63, 236,</i> qqn ; τινα τῆς χειρός, NT. <i>Marc. 1, 31, etc</i>. qqn par la main ; retenir, conserver en son pouvoir : κέρατα τοῦ ὄρους, XÉN. <i>An. 5, 6, 7,</i> les crêtes de la montagne ; <i>fig</i>. conserver dans son souvenir, ATH. <i>275</i> b ; soutenir, empêcher de tomber, DH. <i>4, 88 ;</i> contenir, maîtriser : κρ. ἑαυτοῦ, LUC. <i>Nec. 17,</i> se maîtriser ; κρ. ἡδονῶν καὶ ἐπιθυμιῶν, PLAT. <i>Conv. 196</i> c, régler ses plaisirs et ses désirs ; <i>au pass</i>. τροφὴ κρατηθεῖσα, PLUT. <i>M. 654</i> b, nourriture qu’on s’est assimilée, qu’on a digérée ; <i>cf</i>. MNÉSITH. (ATH. <i>54</i> b, <i>etc</i>.) ;<br><b>      2</b> être le plus fort, l’emporter sur, HDT. <i>5, 77 ;</i> THC. <i>3, 62 ; avec un dat. de moyen ou d’instrument :</i> κρ. τῇ μάχῃ, EUR. <i>H.f. 612,</i> l’emporter dans le combat ; κρ. πάλᾳ, ἱπποδρομίᾳ, PD. <i>O. 8, 28 ; I. 3, 21,</i> l’emporter dans la palestre, dans la course de chars ; κρ. γνώμῃ, HDT. <i>9, 42,</i> faire prévaloir un avis ; <i>avec l’acc</i>. κρ. τὴν μάχην, DS. <i>18, 30,</i> l’emporter dans le combat ; τὸν ἀγῶνα, DÉM. <i>520 fin,</i> dans la lutte ; <i>avec une conj</i>. κρ. ὥστε μὴ τὰς πύλας ἀνοίγεσθαι, THC. <i>4, 104,</i> obtenir que l’on n’ouvre pas les portes ; <i>d’où</i> vaincre, <i>avec un acc. de pers. :</i> τινα τῇ μάχῃ, THC. <i>6, 2 ;</i> τινα τῷ πολέμῳ, ESCHN. <i>32, 14,</i> qqn dans le combat, dans la guerre ; <i>rar. avec le gén. de la pers</i>. τινος τὸν ἀγῶνα, PHILSTR. <i>677,</i> qqn dans la lutte ; <i>avec un gén. de chose :</i> κρ. τῆς διαϐολῆς, LYS. <i>156, 28,</i> réfuter l’accusation ; <i>au pass</i>. κρατεῖσθαι ὕπνῳ, ESCHL. <i>Eum. 184 ;</i> ὑπὸ τοῦ ὕπνου, HDT. <i>2, 121,</i> être vaincu par le sommeil ; ὑπὸ τῶν ἡδονῶν, PLAT. <i>Leg. 633</i> e, se laisser vaincre par les plaisirs ; <i>abs</i>. ὁ κρατῶν, ATT. le vainqueur ; ὁ κρατούμενος, ATT. le vaincu ;<br><b>      3</b> prévaloir, dominer, prendre force de loi, devenir une règle <i>ou</i> une coutume, THC. <i>6, 5 ;</i> κρατεῖ φήμη, POL. <i>9, 26, 11,</i> le bruit s’accrédite ;<br><b>      4</b> avoir raison, PLAT. <i>Phædr. 272</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 2 sg. ion</i>. κρατέεις, OD. <i>11, 484 ; 3 sg</i>. κρατέει, IL. <i>1, 78 ; 3 pl</i>. κρατέουσι, OD. <i>16, 265 ; inf</i>. κρατέειν, IL. <i>1, 288 ;</i> HDT. <i>9, 42 ; part</i>. κρατέων, IL. <i>16, 172. Impf. itér</i>. κρατέεσκον, ANTH. <i>5, 294 ou</i> κράτεσκον, PD. <i>N. 3, 52. Ao. part. dor</i>. κρατήσαις, PD. <i>P. 10, 23. Moy. fut</i>. κρατήσομαι <i>au sens pass</i>. ARSTD. <i>39, 501</i>.<br><span><b>Étym</b>. κράτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρατεω - κρατέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 46 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (12)</li>\n<li>Marc (15)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (4)</li>\n<li>Colossiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G2903":"<h1>kratistos</h1>\n<p>Strong n° 2903 <i>Prononciation [krat'-is-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>très puissant, très fort, le plus illustre, le meilleur, très excellent\n<ol type=\"a\">\n<li>utilisé pour s'adresser à un homme de haut rang ou occupant une haute fonction</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κράτιστος</b> <span>[ᾰ]</span> <i>épq</i>. <b>κάρτιστος, η, ον</b>, très fort <i>ou</i> le plus fort, <i>d’où :</i><br><b>      1</b> très fort, très solide, très résistant : δεσμὸς κρ. T. LOCR. <i>99</i> a, lien très fort ; κάρτιστος καὶ ὤκιστος πετεηνῶν, IL. <i>21, 253,</i> (l’aigle) le plus fort et le plus rapide des oiseaux ; κ. μάχη, IL. <i>6, 185,</i> combat violent ;<br><b>      2</b> très puissant, <i>en parl. des dieux et des hommes,</i> IL. <i>1, 266, etc. ;</i> SOPH. <i>Ph. 3 ;</i> THC. <i>7, 67 ;</i><br><b>      3</b> excellent, le meilleur, PD. <i>I. 1, 25, etc. ;</i> SOPH. <i>O.R. 1525, etc. ;</i> τι, THC. <i>2, 40 ;</i> XÉN. <i>An. 1, 9, 2 ;</i> πρός τι, XÉN. <i>Hell. 3, 4, 16 ;</i> εἴς τι, PLAT. <i>Phil. 67</i> b, <i>etc</i>. pour qqe ch., en vue de qqe ch. ; ποιεῖν τι, THC. <i>2, 81 ;</i> XÉN. <i>Mem. 1, 4, 1 ;</i> PLAT. <i>Phædr. 267</i> d, pour faire qqe ch. ; <i>avec un part</i>. τῶν ἡλίκων κρ. ἀκοντίζων καὶ τοξεύων, XÉN. <i>Cyr. 1, 3, 15,</i> l’emporter sur ses camarades pour lancer le javelot et les flèches ; κράτιστόν (ἐστι), OD. <i>12, 120, ou</i> κράτιστά (ἐστι), EUR. <i>Med. 384, avec l’inf</i>. le mieux, le plus sage <i>ou</i> le plus avantageux est de, <i>etc. ; adv</i>. τὰ κράτιστα, THC. <i>1, 19 ;</i> κράτιστα, XÉN. <i>Hell. 3, 4, 16, etc</i>. très bien, supérieurement, le mieux possible, <i>etc. ;</i> ἀπὸ τοῦ κρατίστου, POL. <i>8, 19, 4 ;</i> κατὰ τὸ κράτιστον, DH. <i>2, 22,</i> sérieusement.<br><span><b>Étym</b>. <i>sup. de</i> κράτος ; <i>cf</i>. κάρτιστος <i>et</i> κρείσσων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρατιστος - κράτιστος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT).\n<ul>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G2904":"<h1>kratos</h1>\n<p>Strong n° 2904 <i>Prononciation [krat'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>force souveraine</li>\n<li>pouvoir, puissance : fort d'un grand pouvoir\n<ol type=\"a\">\n<li>une œuvre puissante, une réalisation du pouvoir</li>\n</ol>\n</li>\n<li>domination</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>κρατός</b>, <i>v</i>. κράς.<br><br>\n<b>κράς (ὁ) :<br>   I</b> tête, IL. <i>14, 177 ;</i> OD. <i>22, 218 ;</i> TRAG. ; <i>au pl. p. le sg</i>. ὑπὸ κράτεσφι, IL. <i>10, 156,</i> sous sa tête ;<br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> sommet de montagne, IL. <i>20, 5 ;</i><br><b>      2</b> bord, extrémité, OD. <i>9, 140 ; 13, 102</i>.<br><span><b><span class=\"arrow\"></span></b> ἡ κρ. EUR. <i>El. 140. Le nom</i>. κράς <i>pour la première fois dans</i> SIM. <i>Anecdota græca, Bkk., t. 3, p. 1182 ; 3, p. 385 Cram. ; en grec class. les autres cas seuls usités, gén</i>. κρατός <span>[ᾱ]</span> IL. <i>20, 5 ;</i> OD. <i>9, 140, etc. ; et par allong</i>. κράατος <span>[ᾱᾰ]</span> IL. <i>14, 177 ;</i> A. RH. <i>1, 222 ; dat</i>. κρατί <span>[ᾱ]</span> OD. <i>9, 490 ;</i> AR. <i>Ran. 329 ; par allong</i>. κράατι, OD. <i>22, 218 ; acc</i>. κρᾶτα, OD. <i>8, 92 ; plur. gén</i>. κράτων <span>[ᾱ]</span> OD. <i>22, 309, dat</i>. κρασίν <span>[ᾱ]</span> IL. <i>10, 152 ou</i> κράτεσφι <span>[ᾱ]</span> IL. <i>10, 156 ; acc</i>. κρᾶτας, EUR. <i>Ph. 1149, H.f. 526. On trouve également au sg</i>. τὸ κρᾶτα, <i>nomin</i>. SOPH. <i>Ph. 1457 ; acc</i>. SOPH. <i>Ph. 1001 ; O.R. 263, et au plur. le nom. neutre</i> τὰ κρᾶτα, SOPH. <i>O.C. 473, allongé en</i> κράατα, IL. <i>19, 93</i>.<br><span><b>Étym</b>. κάρα.</span></span><br><br>\n➁ <b>κράτος</b>, <i>épq</i>. <b>κάρτος, εος-ους (τὸ)</b> <span>[ᾰ]</span> force, <i>d’où :</i><br><b>   I</b> force du corps, force, vigueur, solidité, IL. <i>7, 142, etc., en parl. de métaux (fer, etc</i>.) OD. <i>9, 393 ;</i> κατὰ κράτος, de vive force, THC. <i>8, 100 ;</i> ISOCR. <i>65</i> c, <i>etc., ou</i> de toute sa force, THC. <i>1, 64 ;</i> XÉN. <i>Cyr. 4, 2, 30 ;</i> PLAT. <i>Leg. 692</i> d ; DÉM. <i>913, 15, etc. ;</i> ἀνὰ κράτος, XÉN. <i>Cyr. 1, 4, 23, etc</i>. de vive force ; de toute sa force, XÉN. <i>Cyr. 8, 3, 21 ;</i> πρὸς ἰσχύος κράτος, SOPH. <i>Ph. 594,</i> par la puissance de la force, <i>p. opp. à</i> λόγῳ ;<br><b>   II</b> domination, puissance :<br><b>      1</b> <i>en parl. des dieux et des hommes,</i> IL. <i>2, 118 ;</i> OD. <i>1, 359 ;</i> PD. <i>O. 6, 162 ;</i> ESCHL. <i>Pr. 525, etc. ;</i><br><b>      2</b> <i>particul</i>. pouvoir royal, puissance souveraine, HDT. <i>1, 129, etc. ;</i> ἀρχὴ καὶ κρ. τυραννικόν, SOPH. <i>O.C. 373,</i> commandement et pouvoir d’un roi ; <i>au pl</i>. SOPH. <i>Ant. 166, 173, etc. ;</i><br><b>      3</b> domination, <i>en gén</i>. autorité souveraine : τῶν Περσῶν, HDT. <i>3, 69,</i> sur les Perses ; τῆς στρατιῆς, HDT. <i>9, 42,</i> sur l’armée ; χθονός, sur la terre, ESCHL. <i>Suppl. 425 ;</i> τῆς θαλάσσης, THC. <i>1, 143,</i> l’empire de la mer ; κρ. ἔχειν ἑαυτοῦ, PLAT. <i>Rsp. 273</i> a, avoir la puissance sur soi-même ;<br><b>   III</b> <i>p. suite,</i> victoire, IL. <i>1, 509, etc. ;</i> OD. <i>21, 280 ; joint à</i> νίκη, ESCHL. <i>Suppl. 951 ;</i> SOPH. <i>El. 85 ;</i> PLAT. <i>Leg. 962</i> a, <i>etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *kret-s-, force ; <i>cf</i>. κρείσσων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρατος - κράτος</font>\n<br><br>peut-être un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – force, puissance, pouvoir souvent oppressif s'exerçant par des actes de violence\n<br><br> – puissance, capacité naturelle, générale et inhérente\n<br><br> – action, efficacité, pouvoir dans l'exercice, pouvoir opérant  – d'abord liberté d'action ; donc autorité - soit un pouvoir qui a été délégué, ou un pouvoir sans restriction, arbitraire\n<br><br> – force, vertu, puissance (spécialement physique), comme reçue en don\n<br><br> – puissance, force souveraine, le pouvoir manifesté ; – dans le NT il s'agit surtout de la force et du pouvoir de Dieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 9 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2905":"<h1>kraugazo</h1>\n<p>Strong n° 2905 <i>Prononciation [krow-gad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>crier, s'écrier, crier avec force, crier à quelqu'un, hurler, pousser des clameurs</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κραυγάζω</b>, crier, criailler, DÉM. <i>1258, 26 ; particul</i>. aboyer, <i>poét</i>. PLAT. <i>Rsp. 607</i> b ; croasser, ARR. <i>Epict. 3, 1, 37</i>.<br><span><b>Étym</b>. κραυγή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κραυγαζω - κραυγάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Jean (4)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2906":"<h1>krauge</h1>\n<p>Strong n° 2906 <i>Prononciation [krow-gay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pousser un cri</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κραυγή, ῆς (ἡ)</b> cri, ESCHN. <i>84, 6 ;</i> PLUT. <i>M. 29</i> d, <i>etc. ;</i> LUC. <i>Herm. 11 ; joint à</i> θόρυϐος, ESCHN. <i>70, 39 ;</i> DÉM. <i>1258, 2 ; à</i> βοή, DÉM. <i>1259, 25 ; au plur</i>. PLUT. <i>M. 130</i> d ; <i>joint à</i> θόρυϐοι, PLUT. <i>M. 866</i> e ; κραυγὴν ποιεῖν, XÉN. <i>Cyr. 3, 1, 4 ; Hell. 6, 4, 16,</i> pousser un cri ; κραυγὴν στῆσαι, EUR. <i>Or. 1529, ou</i> τιθέναι, EUR. <i>Or. 150, m. sign. ;</i> κραυγὴ Καλλιόπης, DIONYS. <i>cité dans</i> ARSTT. <i>Rhet. 3, 2, 4, comme exemple de mauv. goût,</i> le cri de Kalliopè, <i>càd</i>. l’art de la poésie.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. κραυγά, EUR. <i>Ion 893, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *krau-g-, crier ; <i>probabl. onomatopée, cf</i>. κράζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κραυγη - κραυγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2907":"<h1>kreas</h1>\n<p>Strong n° 2907 <i>Prononciation [kreh'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la chair (d'un animal sacrifié)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρέας (τὸ)</b> <i>gén</i>. <b>κρέατος</b> = <i>att</i>. <b>κρέως</b> ; <i>plur</i>. τὰ κρέατα = κρέα <span>[ᾱ]</span>, <i>gén</i>. κρεάτων = κρεῶν :<br><b>      1</b> chair, <i>particul</i>. chair à manger, <i>au sg</i>. morceau de viande, OD. <i>8, 477 ;</i> PLAT. <i>Rsp. 338</i> c, <i>etc. ;</i> AR. <i>Nub. 339, etc. ;</i> τρία κρέα ἢ καὶ πλέα, XÉN. <i>Cyr. 2, 2, 2,</i> trois portions de viande ou plus ; <i>au plur</i>. viandes, morceaux de viande, <i>en gén.,</i> HOM. (<i>v. ci-dessous) etc. ;</i><br><b>      2</b> corps, SOPH. <i>fr. 650 ; au plur</i>. AR. <i>Ran. 191</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. sg. att</i>. κρέως, SOPH. <i>fr. 650 ;</i> AR. <i>Ran. 193. Dans les inscr. att. d’ord. seul. les formes contractes ; un seul ex. du gén. sg</i>. κρέατος (<i>inscr. de 338 av. J.C.) ; v. Meisterh. p. 112, 5 ; plur</i>. κρέα, <i>seule forme dans les inscr. att</i>. CIA. <i>4, b, 35, b, 17 (440/432 av. J.C.), etc. ; v. Meisterh. p. 112, 5 ; gén. pl. épq</i>. κρειῶν, IL. <i>11, 551 ;</i> OD. <i>1, 141, etc., ou</i> κρεάων, HH. <i>Merc. 130, att</i>. κρεῶν (<i>qqf. épq. et ion</i>.) OD. <i>15, 98 ;</i> HDT. <i>1, 73 ; seule forme dans les inscr. att</i>. CIA. <i>1, 9, 7 (470/460 av. J.C.), etc. v. Meisterh. p. 112, 5 ; dat. pl</i>. κρέασι, IL. <i>8, 162, ion</i>. κρέεσσι, ORACL. (HDT. <i>1, 47). Au sg. dans Hom. on ne trouve que l’acc</i>. OD. <i>8, 477 ; 16, 443 ;</i> — κρέα <i>est élidé,</i> OD. <i>3, 65, 470 et forme synizèse,</i> OD. <i>9, 347. Ion</i>. κρεῖας, ANAN. (ATH. <i>282</i> b). <i>P. contr</i>. κρῆς, THCR. <i>Idyl. 1, 6</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *kreuh₂-, viande ; <i>cf. sscr</i>. kravíṣ-, <i>lat</i>. cruor.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρεας - κρέας</font>\n<br><br>peut-être un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2908":"<h1>kreisson</h1>\n<p>Strong n° 2908 <i>Prononciation [krice'-son]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mieux, le meilleur, le plus fort</li>\n<li>au neutre : le mieux (des deux)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>κρεισσόνως</b>, <i>att</i>. <b>κρειττόνως</b>, <i>adv</i>., mieux, ANT. <i>128, 33</i>.<br><span><b>Étym</b>. κρείσσων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρεισσων - κρεῖσσον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2909":"<h1>kreitton</h1>\n<p>Strong n° 2909 <i>Prononciation [krite'-tohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>plus utile, plus utilisable, plus avantageux</li>\n<li>plus excellent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρείττων</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρειττον - κρείττων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 18 versets de 5 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (3)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (13)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2910":"<h1>kremannumi</h1>\n<p>Strong n° 2910 <i>Prononciation [krem-an'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pendre, suspendre, accrocher</li>\n<li>être suspendu, dépendre\n<ol type=\"a\">\n<li>utilisé pour celui qui est pendu à la croix, clouer</li>\n<li>utilisé pour la Loi et les Prophètes, qui sont contenus ou dépendent de deux préceptes (<a class=\"ref\" data-r=\"MAT22.40\">Matthieu 22.40</a>)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρεμάννυμι</b> <span>[ῡ]</span> <span>(<i>f</i>. κρεμάσω, <i>att</i>. κρεμῶ ; <i>ao</i>. ἐκρέμασα, <i>pf. inus. ; pass. ao</i>. ἐκρεμάσθην)</span> suspendre : τινά, ARSTT. <i>Pol. 5, 10, 21, etc</i>. qqn ; σειρὴν ἐξ οὐρανόθεν, IL. <i>8, 19,</i> suspendre une chaîne au ciel ; τι ποτὶ ναόν, IL. <i>7, 83,</i> suspendre une offrande à un temple ; ἀπὸ κάλω κρ. ἑαυτόν, AR. <i>Ran. 121,</i> se suspendre à un câble ; <i>avec le gén. de la partie par laquelle on suspend :</i> τινά τινος, AR. <i>Pl. 312,</i> suspendre qqn par qqe ch. ; ὗς τῶν ὀπισθίων σκελῶν, ARSTT. <i>H.A. 9, 50, 7,</i> suspendre des porcs par les jambes de derrière ; <i>abs</i>. κρ. τὴν ἀσπίδα, AR. <i>Ach. 58,</i> suspendre son bouclier, <i>càd</i>. avoir fini la guerre ; <i>fig. en parl. de l’esprit, de l’attention, etc</i>. XÉN. <i>Conv. 8, 19 ;</i> ARSTT. <i>Rhet. 3, 14, etc. ;</i><br><b><i>Moy.</i></b> suspendre pour soi : πηδάλιον κρεμάσασθαι, HÉS. <i>O. 627,</i> tenir son gouvernail suspendu.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. att</i>. κρεμῶ, ᾷς, ᾷ, AR. <i>Pl. 312 ; épq</i>. κρεμόω, IL. <i>7, 83</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *kremh₂-, suspendre.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρεμαννυμι - κρεμάννυμι</font>\n<br><br>forme prolongée d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G2911":"<h1>kremnos</h1>\n<p>Strong n° 2911 <i>Prononciation [krame-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une pente très rude, un précipice, falaise escarpée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρημνός, οῦ (ὁ) :<br>      1</b> lieu escarpé, précipice, IL. <i>12, 54 ; 21, 175, etc. ;</i> PD. <i>O. 3, 39 ;</i> THC. <i>7, 45 ;</i> SOPH. <i>Aj. 721 ;</i> EUR. <i>Hipp. 124, etc. ;</i> οἱ Κρημνοί, HDT. <i>6, 20, 110,</i> les Escarpements, <i>lieu près de la mer d’Azov ;</i><br><b>      2</b> <i>p. anal. au plur</i>. orifice <i>ou</i> lèvres (d’une plaie, HPC. <i>418, 44 ;</i> d’un organe, HPC. <i>423, 27, 29, 31</i>) ;<br><b>      3</b> <i>fig</i>. mots prétentieux et emphatiques, AR. <i>Eq. 628</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Plur. hétér</i>. κρημνά, STOB. <i>Ecl. eth. p. 116, 29 Mein</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρημνος - κρημνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2912":"<h1>Kres</h1>\n<p>Strong n° 2912 <i>Prononciation [krace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un Crétois, un habitant de l'île de Crète</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κρής, ητός</b>, <i>adj. m</i>. de Crète, Crétois, ESCHL. <i>fr. 173 ;</i> SIM. (PLUT. <i>M. 748</i>) ; XÉN. <i>An. 4, 2, 28 ;</i> οἱ Κρῆτες, IL. <i>3, 230 ;</i> HDT. <i>4, 151, etc</i>. les Crétois ; πρὸς Κρῆτα <i>ou</i> πρὸς Κρῆτας κρητίζειν, POL. <i>8, 21 ;</i> PLUT. <i>Lys. 20, Æmil. 23,</i> mentir comme un Crétois avec un Crétois, <i>càd</i>. mentir à qui mieux mieux.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl</i>. Κρησί, <i>épq</i>. Κρήτεσσι, IL. <i>3, 230 ; 4, 251 ;</i> OD. <i>14, 205, 234, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κρης - Κρής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2913":"<h1>Kreskes</h1>\n<p>Strong n° 2913 <i>Prononciation [krace'-kace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Crescens = « qui croît, qui augmente »\n<ol><li>un assistant de Paul, et dont il est dit qu'il fut l'un des soixante-dix disciples</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κρησκης - Κρήσκης</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2914":"<h1>Krete</h1>\n<p>Strong n° 2914 <i>Prononciation [kray'-tay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Crète (Angl. Crete) = « charnu »\n<ol><li>l'île la plus grande et plus fertile de l'archipel Méditerranéen de la Mer Egée, la moderne Candie. Longueur 280 km, largeur entre 12 et 55 km. Le mont Ida, près du centre, s'élève à 2164 m.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κρήτη, ης (ἡ)</b> î. de Crète (<i>auj</i>. Kríti, <i>anc</i>. Candia) IL. <i>2, 649, etc. ;</i> OD. <i>3, 291, etc. ;</i> HÉS. <i>Th. 477 ;</i> HDT. <i>1, 65, etc. ;</i> THC. <i>3, 69, etc. ; au pl</i>. αἱ Κρῆται, <i>gén. épq</i>. Κρητάων, OD. <i>14, 199 ; 16, 62, m. sign</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. Κρήτα, EUR. <i>Bacch. 121, Hipp. 156, etc</i>.<br><span><b>Étym</b>. Κρής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κρητη - Κρήτη</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (4)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2915":"<h1>krithe</h1>\n<p>Strong n° 2915 <i>Prononciation [kree-thay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>orge (céréale)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κριθή, ῆς (ἡ)</b> <span>[ῑ]</span><br><b>   I</b> orge (<i>hordeum vulgare</i> L.) <i>d’ord. au pl</i>. IL. <i>11, 67 ;</i> OD. <i>9, 110 ; 19, 112 (touj. avec</i> πυροί) ; HDT. <i>2, 77 ;</i> ESCHL. <i>Suppl. 953 ;</i> THC. <i>6, 22 ;</i> PLAT. <i>Leg. 847</i> e, <i>etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> petit bouton sur la paupière, orgelet, HPC. <i>1010</i> g ;<br><b>      2</b> grain, petit poids, TH. <i>Lap. 46 ;</i><br><b>      3</b> <i>c</i>. πόσθη, AR. <i>Pax 965</i>.<br><span><b>Étym</b>. <i>cf</i>. κρῖ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κριθη - κριθή</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2916":"<h1>krithinos</h1>\n<p>Strong n° 2916 <i>Prononciation [kree'-thee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>d'orge, fabriqué avec de l'orge</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρίθινος, η, ον</b> <span>[ῑῐ]</span> fait <i>ou</i> préparé avec de l’orge, HPC. <i>401, 47 ;</i> HIPPON. (ATH. <i>304</i> b) ; POL. <i>34, 9, 35 ;</i> PLUT. <i>M. 397</i> a, <i>etc. ;</i> ATH. <i>16</i> c, <i>etc</i>.<br><span><b>Étym</b>. κριθή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κριθινος - κρίθινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2917":"<h1>krima</h1>\n<p>Strong n° 2917 <i>Prononciation [kree'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un décret, des jugements</li>\n<li>jugement\n<ol type=\"a\">\n<li>condamnation d'une faute, la décision qui est prise sur les fautes des autres (que cette décision soit sévère ou douce)</li>\n<li>dans un sens judiciaire\n<ol>\n<li>la sentence d'un juge</li>\n<li>le châtiment auquel quelqu'un est condamné</li>\n<li>sentence de condamnation, jugement pénal, sentence</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>la matière qui doit être jugée, un procès</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρίμα</b> <i>ou</i> <b>κρῖμα, ατος (τὸ) :<br>   I. 1</b> objet d’une contestation, contestation, querelle, ESCHL. <i>Suppl. 397 ;</i> NT. <i>1Cor. 6, 7 ;</i><br><b>      2</b> <i>p. suite,</i> jugement, décision judiciaire, NT. <i>Matth. 7, 2 ; d’où</i> condamnation, peine, NT. <i>Luc. 24, 20 ;</i><br><b>      3</b> <i>p. ext</i>. jugement <i>en gén.,</i> décision, CHRYSIPP. (PLUT. <i>M. 1046</i> e) ; SEXT. <i>7, 195 ; d’où</i> prescription, loi, SPT. <i>2Par. 30, 16, Ezech. 37, 24 ; joint à</i> τὰ προστάγματα, SPT. <i>Lev. 18, 4 ;</i><br><b>   II</b> action de juger, NT. <i>Joh. 9, 39 ; Ap. 24, 25, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῐ]</span> NONN. <i>Jo. 9, 176, 177</i>.<br><span><b>Étym</b>. κρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κριμα - κρίμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n28 fois dans 28 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (2)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2918":"<h1>krinon</h1>\n<p>Strong n° 2918 <i>Prononciation [kree'-non]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une fleur : le lis</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρίνον, ου (τὸ)</b> <span>[ῐ]</span><br><b>   I</b> lis, <i>en gén. (p. opp. à</i> λείριον, lis blanc) HDT. <i>2, 92 ;</i> TH. <i>H.P. 6, 6, 3 ;</i><br><b>   II</b> <i>p. anal. avec la tige nue du lis :</i><br><b>      1</b> mendiant, pauvre : <span><i>prov</i>. κρίνου γυμνότερος</span>, JUL. <i>Or. 6, 181</i> c, plus nu qu’une tige de lis ;<br><b>      2</b> mort, DIPH. (ZÉNOB. <i>4, 18</i>) ;<br><b>   III</b> danse, ATH. <i>114</i> f ;<br><b>   IV</b> sorte de pain, ATH. <i>114</i> f.<br><span><b><span class=\"arrow\"></span></b> <i>Plur. nom.-acc</i>. κρίνεα, HDT. <i>l. c. ; dat</i>. κρίνεσι, AR. <i>Nub. 911 ;</i> CHÆRÉM. (ATH. <i>608</i> f) <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρινον - κρίνον</font>\n<br><br>peut-être mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2919":"<h1>krino</h1>\n<p>Strong n° 2919 <i>Prononciation [kree'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>séparer, mettre en morceaux, démonter, choisir, sélectionner</li>\n<li>approuver, estimer, préférer</li>\n<li>être d'opinion, juger, penser</li>\n<li>déterminer, se résoudre, décréter</li>\n<li>juger\n<ol type=\"a\">\n<li>prononcer une opinion concernant le vrai et le faux\n<ol>\n<li>être jugé, soumis à une épreuve qui peut être un jugement</li>\n</ol>\n</li>\n<li>prononcer un jugement, assujettir à la censure\n<ol>\n<li>de ceux qui ont une position de juge ou d'arbitres, dans la vie courante ou jugent les faits, gestes et mots des autres</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>régenter, gouverner\n<ol type=\"a\">\n<li>présider avec le pouvoir de prendre des décisions judiciaires, car il est de la prérogative des rois et gouvernants de prononcer un jugement</li>\n</ol>\n</li>\n<li>lutter ensemble, de guerriers et combattants\n<ol type=\"a\">\n<li>disputer, se disputer</li>\n<li>dans un sens judiciaire\n<ol>\n<li>aller en justice, faire un procès</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρίνω</b> <span>[ῑ]</span> <span>(<i>f</i>. κρινῶ <span>[ῐ]</span>, <i>ao</i>. ἔκρινα <span>[ῑ]</span>, <i>pf</i>. κέκρικα <span>[ῐ]</span> ; <i>pass. ao</i>. ἐκρίθην <span>[ῐ]</span>, <i>pf</i>. κέκριμαι <span>[ῐ]</span>)</span><br><b>   I</b> séparer, <i>d’où :</i><br><b>      1</b> trier : καρπόν τε καὶ ἄχνας, IL. <i>5, 501,</i> séparer l’épi et la barbe ; ἄνδρας κατὰ φῦλα, IL. <i>2, 362,</i> séparer les guerriers par tribus ; <i>cf</i>. IL. <i>6, 118 ; cf</i>. OD. <i>4, 666, etc. ;</i><br><b>      2</b> distinguer : τούς τε ἀγαθοὺς καὶ τοὺς κακούς, XÉN. <i>Mem. 3, 1, 9, etc</i>. les bons et les méchants ; τὸ ἀληθές τε καὶ μή, PLAT. <i>Theæt. 150</i> b, ce qui est vrai et ce qui ne l’est pas ; <i>au pass</i>. ἵνα κρίνονται ἄριστοι, OD. <i>24, 507,</i> où se distinguent les plus braves ;<br><b>      3</b> choisir : τινὰ ἐκ πάντων, HDT. <i>6, 129,</i> qqn entre tous ; <i>cf</i>. ESCHL. <i>Eum. 487 ; p. suite,</i> préférer : ἄφθονον ὄλϐον, ESCHL. <i>Ag. 471,</i> un bonheur exempt d’envie ; τινὰ πρό τινος, PLAT. <i>Rsp. 399</i> e, choisir qqn de préférence à un autre ; <i>cf</i>. PLAT. <i>Phæd. 110</i> a, <i>etc. ;</i><br><b>      4</b> <i>t. de physiol</i>. sécréter : τὰ κρινόμενα κάτω, ARSTT. les matières évacuées par le bas ;<br><b>   II</b> <i>p. suite :</i><br><b>      1</b> décider, trancher : νεῖκος, OD. <i>18, 264,</i> une querelle ; δίκην, HDT. <i>2, 129 ;</i> ESCHL. <i>Eum. 433, etc. ;</i> κρίσιν, PLAT. <i>Rsp. 360</i> c, juger un procès ; κρ. περί τινος, PLAT. <i>Ap. 35</i> d, décider de qqe ch. ; <i>abs</i>. décider (une question, une contestation, <i>etc</i>.) THC. <i>1, 87 ; 3, 67 ; au pass</i>. ESCHL. <i>Eum. 677 ; impers</i>. κριθησόμενον, ARR. <i>An. 3, 9, 6,</i> une décision étant sur le point d’être prise ; <i>avec un acc. de pers. :</i> κρ. τὰς θεάς, EUR. <i>I.A. 72,</i> juger les déesses, décider leur contestation ; <i>avec une prop. inf. :</i> κρίνω σε νικᾶν, ESCHL. <i>Ch. 903,</i> je décide que c’est toi le vainqueur ; <i>au sens judic</i>. poursuivre en justice, accuser, LYC. <i>147, 43 ;</i> DÉM. <i>26, 18, etc. ;</i> κρ. τινὰ προδοσίας, LYC. <i>164, 7, ou</i> περὶ προδοσίας, ISOCR. <i>Antid. § 137,</i> poursuivre qqn pour trahison ; κρ. θανάτου, XÉN. <i>Cyr. 1, 2, 14,</i> juger une cause capitale ; <i>au pass</i>. κρίνεσθαι κρίσιν θανάτου, DÉM. <i>535, 10 ou</i> κρίνεσθαι θανάτου, THC. <i>3, 57 ; ou</i> περὶ θανάτου, DÉM. <i>53, 27,</i> être jugé pour un crime capital ; ὁ κρίνων, l’accusateur <i>ou</i> le juge, DÉM. <i>407, 22 ;</i> ὁ κρινόμενος, ESCHN. <i>49, 30,</i> l’accusé ; <i>p. suite,</i> juger, condamner (<i>c</i>. κατακρίνω) SOPH. <i>Tr. 724 ;</i> DÉM. <i>413, 16 ; au pass</i>. être condamné, DÉM. <i>52, 2 ;</i> NT. <i>Matth. 7, 1 ;</i> ὁ κεκριμένος, ESCHN. <i>49, 30,</i> le condamné ;<br><b>      2</b> décider, résoudre, expliquer, interpréter : ἐνύπνιον, HDT. <i>1, 120,</i> un songe ; <i>cf</i>. ESCHL. <i>Pr. 485, Ch. 542 ;</i> EUR. <i>Hec. 89 ;</i><br><b>      3</b> <i>p. ext</i>. juger, estimer, apprécier : κρίνειν μέγιστον ἀγαθὸν εἶναι πλοῦτον, PLAT. <i>Gorg. 452</i> c, juger que la fortune est un très grand bien ; <i>d’où, au pass</i>. être jugé, estimé (le meilleur, le plus brave, <i>etc</i>.) SOPH. <i>Ph. 1345 ; abs</i>. être jugé, <i>càd</i>. avoir fait ses preuves : ἀσπὶς πολέμῳ κεκριμένη, ANTH. <i>9, 42,</i> bouclier éprouvé dans la guerre ;<br><b>      4</b> <i>en gén</i>. adjuger, SOPH. <i>Aj. 442 ; d’où</i> décider, résoudre : ποιεῖν τι, NT. <i>1Cor. 2, 2,</i> de faire qqe ch. ; <i>au pass</i>. πράσσειν τὸ κριθέν, POL. <i>5, 52, 6,</i> faire ce qui a été décidé ;<br><b>      5</b> <i>t. de méd</i>. juger, <i>càd</i>. faire entrer dans la phase décisive <i>ou</i> critique, HPC. <i>Aph. 1253 ; au pass</i>. DS. <i>19, 24 ;</i> ἔς τ' ἂν νοῦσος κριθῇ, HPC. <i>40, 32,</i> jusqu’à ce que la maladie soit jugée, <i>càd</i>. jusqu’au moment critique ; <i>p. suite, au part. pf. pass. :</i> οὖρος κεκριμένος, IL. <i>14, 19,</i> vent déterminé, <i>càd</i>. vent qui souffle dans une direction déterminée (<i>cf</i>. εὐκρινής) ;<br><b>      6</b> mettre en jugement, <i>d’où</i> interroger, questionner, SOPH. <i>Tr. 195, 388 ; joint à</i> ἐξελέγχω, SOPH. <i>Ant. 399 ; à</i> ἐξετάζω, SOPH. <i>Aj. 586 ;</i><br><b><i>Moy</i>. κρίνομαι</b> <span>[ῑ]</span> <span>(<i>f</i>. κρινοῦμαι <span>[ῐ]</span>, <i>ao</i>. ἐκρινάμην <span>[ῑ]</span>, <i>pf</i>. κέκριμαι <span>[ῐ]</span>)</span> décider pour soi, <i>d’où :</i><br><b>      1</b> décider, trancher une contestation pour soi : Ἄρηϊ, IL. <i>2, 385,</i> décider sa querelle par un combat ; Τιτήνεσσι, HÉS. <i>Th. 882,</i> décider une querelle avec les Titans, lutter contre les Titans ; περί τινος, HDT. <i>3, 120,</i> disputer sur qqe ch. ; <i>particul. au sens judic. :</i> δίκῃ, THC. <i>4, 122,</i> décider sa querelle par un procès ;<br><b>      2</b> juger, interpréter : ὀνείρους, IL. <i>5, 150,</i> des songes.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. ao. poét</i>. κρίθην, PD. <i>P. 8, 84 ; 3 pl. épq</i>. ἔκριθεν, A. RH. <i>4, 1462, ou</i> κρίθεν, PD. <i>P. 4, 168 ; autre ao. épq. inf</i>. κρινθήμεναι, A. RH. <i>2, 148 ; part</i>. κρινθείς, IL. <i>13, 129 ;</i> OD. <i>8, 48</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *kre(h₁-)i-, séparer, trier, cribler ; <i>cf. lat</i>. cernō, crībrum.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρινω - κρίνω</font>\n<br><br>peut-être un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n115 fois dans 98 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Luc (6)</li>\n<li>Jean (20)</li>\n<li>Actes (22)</li>\n<li>Romains (18)</li>\n<li>1 Corinthiens (17)</li>\n<li>2 Corinthiens (2)</li>\n<li>Colossiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (4)</li>\n<li>Apocalypse (9)</li>\n</ul>\n</td></tr>\n</table>","G2920":"<h1>krisis</h1>\n<p>Strong n° 2920 <i>Prononciation [kree'-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une séparation\n<ol type=\"a\">\n<li>un procès, contester</li>\n</ol>\n</li>\n<li>sélection</li>\n<li>jugement\n<ol type=\"a\">\n<li>opinion ou décision donnée concernant toute chose\n<ol>\n<li>spéc. ce qui concerne justice et injustice, vrai ou faux</li>\n</ol>\n</li>\n<li>sentence de condamnation et châtiment</li>\n</ol>\n</li>\n<li>le collège de juges (tribunal de sept hommes dans plusieurs cités de Palestine; différent du Sanhédrin, dont le siège était à Jérusalem)</li>\n<li>droit, justice</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρίσις, εως (ἡ)</b> <span>[ῐσ]</span><br><b>   I</b> action <i>ou</i> faculté de distinguer, ARSTT. <i>Nic. 9, 2, 10, etc. ;</i><br><b>   II</b> <i>p. suite,</i> action de choisir, choix, élection, ARSTT. <i>Pol. 6, 7, 4 ;</i><br><b>   III</b> action de séparer, <i>d’où</i> dissentiment, contestation : περί τινος, HDT. <i>5, 5, etc</i>. sur qqe ch. ; <i>d’où</i> lutte, SOPH. <i>Tr. 266, etc. ; joint à</i> ἔρις, PLAT. <i>Rsp. 379</i> e ; <i>particul</i>. contestation en justice, procès, THC. <i>1, 34 ;</i> PLAT. <i>Leg. 856</i> c, <i>876</i> b ;<br><b>   IV</b> action de décider, <i>d’où :</i><br><b>      1</b> décision, jugement (sur une question, sur un doute, <i>etc</i>.) HDT. <i>3, 34, etc. ;</i> PLAT. <i>Soph. 242</i> c, <i>etc. ; particul</i>. jugement d’une lutte, d’un concours : ἡ τῶν ὅπλων κρ. PLAT. <i>Rsp. 620</i> b, le jugement au sujet des armes (d’Achille) ; <i>cf</i>. PD. <i>O. 2, 37, etc. ;</i> PLUT. <i>M. 153</i> f ; <i>d’où</i> concours, SOPH. <i>Ph. 1050 ;</i> décision judiciaire, jugement, condamnation, XÉN. <i>An. 1, 6, 5 ;</i><br><b>      2</b> ce qui décide de qqe ch., issue, dénouement, résultat (d’une guerre) THC. <i>1, 23 ;</i> DÉM. <i>244, 10 ;</i> POL. <i>1, 59, 11 ;</i><br><b>      3</b> phase décisive d’une maladie, crise, HPC. <i>V. med. 16, etc. ;</i> GAL. <i>8, 377, etc. ;</i><br><b>      4</b> explication, interprétation d’un songe, DS. <i>17, 116 ;</i> SPT. <i>Dan. 2, 36 ;</i> JOS. <i>A.J. 2, 5, 7 ; B.J. 6, 5, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion. gén</i>. κρίσιος, HPC. ; <i>dat</i>. κρίσι, HDT. <i>8, 69</i>.<br><span><b>Étym</b>. κρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρισις - κρίσις</font>\n<br><br>peut-être un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 46 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (12)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Jean (11)</li>\n<li>Actes (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (2)</li>\n<li>2 Pierre (4)</li>\n<li>1 Jean (1)</li>\n<li>Jude (3)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G2921":"<h1>Krispos</h1>\n<p>Strong n° 2921 <i>Prononciation [kris'-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Crispus = « frisé »\n<ol><li>chef de la synagogue de Corinthe, baptisé par Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κρίσπος, ου (ὁ)</b> = <i>lat</i>. Crispus, <i>n. d’h. rom</i>. A. PL. <i>40</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κρισπος - Κρίσπος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2922":"<h1>kriterion</h1>\n<p>Strong n° 2922 <i>Prononciation [kree-tay'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'instrument ou les moyens d'éprouver ou de juger une chose\n<ol type=\"a\">\n<li>la règle par laquelle quelqu'un est jugé</li>\n</ol>\n</li>\n<li>le lieu où le jugement est rendu\n<ol type=\"a\">\n<li>le tribunal d'un juge</li>\n<li>un banc de juges</li>\n</ol>\n</li>\n<li>la chose jugée, la chose qui doit être décidée, un procès, une cause</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κριτήριον, ου (τὸ)</b> <span>[ῐ]</span> ce qui sert à juger, <i>d’où :</i><br><b>   I</b> <i>au sens philos. :</i><br><b>      1</b> faculté de juger, PLUT. <i>M. 448</i> b ;<br><b>      2</b> règle pour discerner le vrai du faux, critérium, PLAT. <i>Theæt. 178</i> b, <i>etc. ;</i> PLUT. <i>M. 1001</i> d ;<br><b>   II</b> <i>au sens judiciaire,</i> lieu où l’on rend la justice, tribunal, PLAT. <i>Leg. 767</i> b ; POL. <i>9, 33, 12</i>.<br><span><b>Étym</b>. κρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κριτηριον - κριτήριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2923":"<h1>krites</h1>\n<p>Strong n° 2923 <i>Prononciation [kree-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui laisse passer ou s'arroge, qui a un jugement sur quelque chose\n<ol type=\"a\">\n<li>un arbitre</li>\n<li>le procurateur Romain administrant la justice</li>\n<li>Dieu prononçant son jugement sur les hommes</li>\n<li>des chefs ou responsables parmi les Israélites</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κριτής, οῦ (ὁ)</b> <span>[ῐ]</span> <i>propr</i>. qui décide, <i>d’où :</i><br><b>   I</b> juge ; <i>particul. :</i><br><b>      1</b> juge arbitre, HDT. <i>3, 160 ;</i> ESCHL. <i>Suppl. 397 ;</i> SOPH. <i>Aj. 1243 ;</i> EUR. <i>Andr. 1163, etc. ;</i> THC. <i>3, 37 ;</i> PLAT. <i>Phil. 65</i> a, <i>etc. ;</i><br><b>      2</b> juge d’un concours, d’une lutte, AR. <i>Nub. 1115, Av. 445 ;</i> PLAT. <i>Leg. 659</i> a, <i>949</i> a, <i>etc. ;</i><br><b>      3</b> <i>rar</i>. juge d’un tribunal, DÉMAD. <i>179, 1 ;</i> ESCHN. <i>87, 4 ;</i><br><b>   II</b> qui interprète, qui explique : ἐνυπνίων, ESCHL. <i>Pers. 226,</i> des songes.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. κριτή, HIPPON. <i>fr. 118</i>.<br><span><b>Étym</b>. κρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κριτης - κριτής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – est le terme le plus digne et le plus officiel\n<br><br> – donne la prééminence au procédé mental, que le juge soit un magistrat ou non</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (5)</li>\n<li>Actes (4)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (3)</li>\n</ul>\n</td></tr>\n</table>","G2924":"<h1>kritikos</h1>\n<p>Strong n° 2924 <i>Prononciation [krit-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>relatif au jugement, capable de juger, habile au jugement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κριτικός, ή, όν</b> <span>[ῐτ]</span><br><b>      1</b> capable de juger, de décider, ARSTT. <i>An. post. 2, 19, 3, etc. ;</i> τὸ κριτικόν, ARSTT. <i>An. 3, 9, 1,</i> la faculté de penser, de discerner ; ἡ κριτική (<i>s.-e</i>. τέχνη) PLAT. <i>Pol. 260</i> c ; LUC. <i>Herm. 68,</i> l’art de juger ; <i>particul. en parl. d’œuvres de l’esprit :</i> ὁ κριτικός, PLAT. <i>Ax. 366</i> e ; STR. <i>394 Kram</i>. le critique ;<br><b>      2</b> qui concerne un juge : ἀρχὴ κρ. ARSTT. <i>Pol. 3, 1, 12,</i> la fonction de juge (<i>p. opp. à</i> ἀρχὴ βουλευτική) ;<br><b>      3</b> décisif, critique, <i>en parl. d’une phase de maladie,</i> GAL. (STOB. <i>Fl. 101, 14</i>) ; PLUT. <i>M. 134</i> f.<br><span><b>Étym</b>. κρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κριτικος - κριτικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2925":"<h1>krouo</h1>\n<p>Strong n° 2925 <i>Prononciation [kroo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>frapper : à la porte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρούω</b> <span>(<i>f</i>. κρούσω, <i>aor</i>. ἔκρουσα, <i>pf</i>. κέκρουκα ; <i>pass. aor</i>. ἐκρούσθην, <i>pf</i>. κέκρουμαι)</span><br><b>      1</b> heurter, choquer : τινὰ σκέλει, HYPÉR. (<i>Bkk. p. 101, 22</i>) heurter qqn de la jambe ; τοῖς ποσὶ τὴν γῆν, ARR. <i>An. 7, 1, 7,</i> frapper la terre de ses pieds ; τὴν θύραν, AR. <i>Eccl. 317 ;</i> XÉN. <i>Conv. 1, 11 ;</i> PLAT. <i>Prot. 310</i> a, <i>etc</i>. frapper à la porte ;<br><b>      2</b> frapper l’un contre l’autre : ὅπλα πρὸς ἄλληλα, THC. <i>3, 22,</i> choquer les armes les unes contre les autres ; τὰς ἀσπίδας πρὸς τὰ δόρατα, XÉN. <i>An. 4, 5, 18,</i> les boucliers contre les lances ; χεῖρας, EUR. <i>Suppl. 720,</i> battre des mains, applaudir ;<br><b>      3</b> frapper (avec le plectre) les cordes d’un instrument, <i>d’où</i> jouer d’un instrument à cordes, PLAT. <i>Lys. 209</i> b, <i>etc. ; p. anal. en parl. d’un instrument à vent :</i> αὐλεῖν κρούων Ἰαστί, COM. (<i>Com. fr. 5, fr. 404</i>), jouer de la flûte sur le mode ionien ; <i>qqf. avec le dat</i>. κρεμϐάλοις, ATH. <i>636</i> d, jouer des cymbales ;<br><b>      4</b> heurter <i>ou</i> pousser pour mettre en mouvement : σταθμόν, PHOCYL. <i>13,</i> donner le coup de pouce au plateau d’une balance, <i>càd</i>. tromper sur le poids <i>ou</i> la mesure ; <i>cf</i>. SOPH. <i>fr. 927 ; t. de mar</i>. πρύμναν, POL. <i>16, 3, 8, ou</i> κρ. ἐπὶ πρύμναν, APP. <i>Civ. 5, 119,</i> ramener un vaisseau en arrière la poupe en avant au lieu de le retourner du côté de la proue (<i>v. le moyen</i>) ;<br><b>      5</b> heurter (un vase, <i>etc</i>.) avec le doigt pour l’éprouver et le faire résonner ; <i>d’où fig</i>. κρ. τὸ καλόν, PLAT. <i>Hipp. ma. 301</i> b, éprouver le beau ; κρ. τὸν κόλακα, PLUT. <i>M. 64</i> d, éprouver le flatteur ;<br><b>      6</b> <i>fig. en parl. de sensations physiques,</i> piquer, chatouiller : κνῖσα κρ. ῥινὸς ὑπεροχὰς ἄκρας, EPHIPP. (ATH. <i>370</i> c) l’odeur de la graisse me chatouille jusqu’au fond des narines ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. κρούσομαι, <i>ao</i>. ἐκρουσάμην)</span> <i>t. de mar. c. à l’act. :</i> κρ. πρύμναν, THC. <i>1, 51, etc. ;</i> ARR. <i>An. 5, 17, 12,</i> ramener un vaisseau en arrière la poupe en avant ; <i>p. anal</i>. κρ. τὸ πτερόν, EL. <i>N.A. 3, 13,</i> voler en arrière.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρουοω - κρούω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (4)</li>\n<li>Actes (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2926":"<h1>krupte</h1>\n<p>Strong n° 2926 <i>Prononciation [kroop-tay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>crypte, une voie couverte, voûte, cave</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρυπτή, ῆς (ἡ)</b> voûte souterraine, crypte, NT. <i>Luc. 11, 33 ;</i> JOS. <i>B.J. 5, 7, 4 ;</i> ATH. <i>205</i> a.<br><span><b>Étym</b>. <i>fém. de</i> κρυπτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρυπτη - κρύπτη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2927":"<h1>kruptos</h1>\n<p>Strong n° 2927 <i>Prononciation [kroop-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>caché, secret</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρυπτός, ή, όν :<br>      1</b> recouvert, HDT. <i>4, 201 ;</i><br><b>      2</b> caché, secret, IL. <i>14, 168 ;</i> HDT. <i>3, 146 ;</i> τὰ κρυπτά μου, EUR. <i>Or. 1140,</i> ce que je voulais tenir caché ; <i>fig</i>. SOPH. <i>El. 159 ;</i> EUR. <i>Hipp. 139 ; ou</i> obscur, inintelligible, ESCHL. <i>Ch. 773 ;</i><br><b>      3</b> dissimulé, trompeur, SOPH. <i>Ph. 1112 ; subst</i>. ὁ κρ. AR. <i>Th. 600,</i> espion.<br><span><b><span class=\"arrow\"></span></b> <i>Fém. dor</i>. κρυπτά, SOPH. <i>El. 159, etc</i>.<br><span><b>Étym</b>. <i>vb. de</i> κρύπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρυπτος - κρυπτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 16 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2928":"<h1>krupto</h1>\n<p>Strong n° 2928 <i>Prononciation [kroop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cacher, être caché</li>\n<li>métaph. cacher (ce qui ne doit pas devenir connu)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρύπτω</b> <span>(<i>f</i>. κρύψω, <i>ao</i>. ἔκρυψα, <i>pf. inus. ; pass. f</i>. κρυφθήσομαι, <i>ao</i>. ἐκρύφθην, <i>pf</i>. κέκρυμμαι)</span><br><b>A <i>tr</i>.<br>   I</b> <i>au propre,</i> couvrir, cacher ; <i>particul. :</i><br><b>      1</b> couvrir pour protéger : τινὰ σάκεϊ, IL. <i>8, 272,</i> couvrir qqn d’un bouclier ; κεφαλὰς κορύθεσσιν, IL. <i>14, 373,</i> couvrir leurs têtes de casques ; τινὰ <i>ou</i> τι ὑπό τινι, IL. <i>13, 405,</i> mettre qqn <i>ou</i> qqe ch. à l’abri sous qqe ch. ;<br><b>      2</b> cacher pour soustraire aux regards : δέμας, ESCHL. <i>Pr. 1020 ;</i> EUR. <i>Bacch. 729,</i> cacher son corps, se cacher ; ὑφ' εἵματος δεξιάν, EUR. <i>Hec. 343,</i> cacher sa main droite sous son vêtement ; ἑαυτόν, SOPH. <i>Tr. 905,</i> se cacher ; σύ μ' ἐξ ὁδοῦ πόδα κρύψον κατ' ἄλσος, SOPH. <i>O.C. 113,</i> guide mes pas hors du chemin et cache-moi dans le bois sacré ; <i>au pass</i>. se cacher, disparaître, <i>en parl. des astres,</i> HÉS. <i>O. 384 (V. Moy. intr</i>.) ;<br><b>      3</b> déposer sous : γῇ, HDT. <i>5, 4 ;</i> THC. <i>2, 34 ;</i> κατὰ γῆς, PLUT. <i>Cam. 20 ;</i> χθονί, SOPH. <i>O.C. 1546 ;</i> κατὰ χθονός, SOPH. <i>Ant. 25,</i> déposer sous terre ; τάφῳ, SOPH. <i>Ant. 196,</i> déposer dans le tombeau ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> cacher, celer, faire mystère de : τι, OD. <i>4, 350 ; 11, 443 ;</i> PD. <i>O. 6, 51, etc</i>. de qqe ch. ; τι πρός τινα, SOPH. <i>Ph. 587 ;</i> τί τινα, ESCHL. <i>Pr. 625 ;</i> SOPH. <i>El. 957 ;</i> EUR. <i>Hec. 570 ;</i> AR. <i>Pl. 26 ;</i> LYS. <i>p. 897,</i> cacher qqe ch. à qqn ; <i>au pass</i>. κρυπτόμενα πράττεσθαι, ANT. <i>119, 1,</i> agir en secret, <i>p. opp. à</i> ἐπὶ μαρτύρων ; <i>part. pf</i>. κεκρυμμένος, caché, secret, OD. <i>11, 443 ;</i> SOPH. <i>O.R. 1398 ;</i> EUR. <i>Andr. 32 ;</i><br><b>      2</b> <i>p. suite, simpl</i>. ne pas produire au dehors, garder pour soi : τί κρύψει ; SOPH. <i>Aj. 1012,</i> que ne dira-t-il pas ? (<i>litt</i>. que gardera-t-il en lui-même ?) ;<br><b>B <i>intr.</i></b> se cacher, demeurer caché, SOPH. <i>El. 826 ;</i> τινά, HH. <i>26, 7,</i> se cacher de qqn, agir à l’insu de qqn ;<br><b><i>Moy.</i></b> :<br><b>   I <i>tr</i>.<br>      1</b> cacher pour soi <i>ou</i> sur soi : κάρα, SOPH. <i>Aj. 245,</i> se cacher la tête ;<br><b>      2</b> <i>fig</i>. cacher, celer : τἀληθές, SOPH. <i>Tr. 474,</i> la vérité ;<br><b>   II <i>intr.</i></b> se cacher, disparaître : οὐρανῷ, EUR. <i>Hel. 606,</i> dans les airs, <i>en parl. d’un fantôme qui disparaît</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. itér. 3 sg</i>. κρύπτεσκε, HH. <i>Cer. 239, ou</i> κρύπτασκε, IL. <i>8, 272. Ao. poét</i>. κρύψα, OD. <i>14, 357, etc. ; opt. att. 2 sg</i>. κρύψειας, EUR. <i>I.T. 1024 ; 3 pl</i>. κρύψειαν, PLAT. <i>Rsp. 548. Ao.2 réc</i>. ἔκρυφον <span>[ῠ]</span> Q. SM. <i>1, 393 ;</i> NONN. <i>D. 23, 82 ;</i> ἔκρυϐον, CON. <i>Narr. 50. Pass. ao. poét</i>. κρύφθην, IL. <i>13, 405 ; 3 pl. poét</i>. ἔκρυφθεν, EUR. <i>Hipp. 1247. Ao.2 pass. réc</i>. ἐκρύϐην <span>[ῠ]</span> APD. <i>3, 2 ;</i> ES. <i>127 Halm ;</i> GEOP. <i>12, 39 ;</i> NT. <i>Joh. 8, 59. Pf. 3 pl. ion</i>. κεκρύφαται, HÉS. <i>Th. 730. Pl.q.pf. 3 sg. poét</i>. κέκρυπτο, PD. <i>O. 6, 54 ; f. antér</i>. κεκρύψομαι, HPC. <i>8, 86 et 98 Littré</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρυπτω - κρύπτω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 15 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2929":"<h1>krustallizo</h1>\n<p>Strong n° 2929 <i>Prononciation [kroos-tal-lid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être d'une brillance cristalline, transparent</li>\n<li>briller comme du cristal</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρυσταλλίζω</b>, être brillant <i>ou</i> transparent comme le cristal, NT. <i>Apoc. 21, 11</i>.<br><span><b>Étym</b>. κρύσταλλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρυσταλλιζω - κρυσταλλίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2930":"<h1>krustallos</h1>\n<p>Strong n° 2930 <i>Prononciation [kroos'-tal-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cristal, une sorte de pierre précieuse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρύσταλλος, ου</b> (ὁ ; <i>v. ci-dessous</i>) :<br><b>   I</b> glace :<br><b>      1</b> eau congelée, IL. <i>22, 152 ;</i> OD. <i>14, 447 ;</i> HDT. <i>4, 28 ;</i> THC. <i>3, 23 ;</i> PLAT. <i>Conv. 220</i> b ;<br><b>      2</b> froid glacial, OPP. <i>H. 3, 155 ;</i><br><b>   II</b> cristal, verre transparent, DP. <i>724, 781 ;</i> DIOSC. <i>2, 52 ;</i> STR. <i>717 ;</i> EL. <i>N.A. 15, 8 ; en ce sens qqf</i>. ἡ κρ. ANTH. <i>9, 753</i>.<br><span><b>Étym</b>. <i>pré-grec ; cf</i>. κρυσταίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρυσταλλος - κρύσταλλος</font>\n<br><br>vient d'un dérivé de 'kruos' (gelée)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2931":"<h1>kruphe</h1>\n<p>Strong n° 2931 <i>Prononciation [kroo-fay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>secrètement, en secret</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>*κρυφή, ῆς (ἡ)</b> <span>[ῠ]</span> action de cacher, <i>seul. dans la loc</i>. ἐν κρυφῇ, SPT. <i>Judith 4, 21 ; 9, 31 ; Ruth 3, 7 ; ou adv</i>. κρυφῇ, en cachette, en secret, SOPH. <i>Ant. 85, etc. ;</i> XÉN. <i>Conv. 5, 8</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. κρυφᾷ, PD. <i>O. 1, 75</i>.<br><span><b>Étym</b>. κρύπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρυφη - κρυφῇ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2932":"<h1>ktaomai</h1>\n<p>Strong n° 2932 <i>Prononciation [ktah'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>acquérir, obtenir, se procurer une chose pour soi, posséder, gagner\n<ol type=\"a\">\n<li>épouser une femme</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κτάομαι-ῶμαι</b> <span>(<i>f</i>. κτήσομαι, <i>ao</i>. ἐκτησάμην, <i>pf</i>. κέκτημαι, <i>d’où sbj</i>. κέκτωμαι, <i>opt</i>. κεκτῄμην, ῇο, ῇτο ; <i>ao. de forme et de sign. pass</i>. ἐκτήθην)</span><br><b>A</b> <i>act. :</i><br><b>   I</b> acquérir, <i>càd. :</i><br><b>      1</b> gagner pour soi, se procurer : κτήματα, IL. <i>9, 400,</i> des richesses ; φίλους, SOPH. <i>Aj. 1360,</i> des amis ; ἑταίρους, EUR. <i>Or. 802 ;</i> PLAT. <i>Gorg. 461</i> c, des compagnons ; κτήσασθαι βίον ἀπό τινος, HDT. <i>8, 106,</i> gagner sa vie au moyen de qqe métier ; χάριν ἀπό τινος, SOPH. <i>Tr. 471, ou</i> ἔκ τινος, SOPH. <i>Ph. 1370, ou</i> παρά τινος, XÉN. <i>Conv. 4, 43,</i> gagner la faveur de qqn ; <i>particul</i>. παῖδας ἐκ γυναικός, EUR. <i>I.T. 696 (cf</i>. SOPH. <i>O.R. 1499</i>) avoir des enfants d’une femme ; <i>p. opp. à</i> conserver : πολλάκις δοκεῖ τὸ φυλάξαι τἀγαθὰ τοῦ κτήσασθαι χαλεπώτερον εἶναι, DÉM. <i>16, 4,</i> souvent il semble que garder son bien soit plus difficile que de l’acquérir ; <i>en mauv. part :</i> κακά, SOPH. <i>El. 1004 ;</i> ξυμφοράς, EUR. <i>Or. 543,</i> s’attirer des maux ; αὑτῷ θάνατον, SOPH. <i>Aj. 968,</i> obtenir la mort (qu’il désirait) ; ὀργὰν θεᾶς, SOPH. <i>Aj. 777,</i> gagner le ressentiment d’une déesse ; τινα πολέμιον, XÉN. <i>An. 5, 5, 17,</i> se faire un ennemi de qqn ;<br><b>      2</b> acquérir pour autrui : τί τινι, OD. <i>20, 265,</i> qqe ch. pour qqn ; <i>cf</i>. ESCHL. <i>Pers. 755 ;</i> XÉN. <i>Œc. 15, 1 ;</i><br><b>   II</b> <i>au pf</i>. avoir acquis, <i>d’où</i> posséder, <i>acc</i>. IL. <i>9, 402 ;</i> XÉN. <i>Cyr. 8, 3, 46 ;</i> PLAT. <i>Phædr. 260</i> b, <i>etc. ; p. opp. au prés. :</i> ἃ (χρήματα) καὶ κτωμένους εὐφραίνει καὶ κεκτημένους ποιεῖ ζῆν, XÉN. <i>Mem. 1, 6, 3,</i> ces richesses procurent à ceux qui les acquièrent de la joie, à ceux qui les possèdent le moyen de vivre ; <i>joint à</i> ἔχω, SOPH. <i>Ant. 1278 ;</i> PLAT. <i>Rsp. 382</i> b ; <i>en mauv. part :</i> κεκτ. κακά, EUR. <i>Hel. 272 ;</i> φθόνον, PLAT. <i>Leg. 870</i> c, avoir gagné, <i>càd</i>. s’être attiré des maux, de l’envie ; <i>p. suite,</i> ὁ κεκτημένος, le maître (<i>litt</i>. celui qui possède) <i>avec le gén</i>. SOPH. <i>Ph. 778 ;</i> AR. <i>Pl. 4, etc. ; qqf. en parl. de l’époux,</i> le maître de la femme, EUR. <i>I.A. 715 ;</i> ἡ κεκτημένη, SOPH. <i>fr. 700 ;</i> AR. <i>Eccl. 1126,</i> la maîtresse ;<br><b>B</b> <i>pass. (seul. ao</i>. ἐκτήθην, <i>pf</i>. κέκτημαι, <i>et postér. prés</i>.) être acquis :<br><b>      1</b> être obtenu comme propriété, EUR. <i>Hec. 449 ;</i> DH. <i>10, 27, etc. ;</i><br><b>      2</b> <i>d’où</i> être possédé, THC. <i>1, 123 ; 2, 36</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ion</i>. κτέομαι, HDT. <i>3, 98. Impf. ion. 3 sg</i>. ἐκτέετο, HDT. <i>8, 112. Ao. 2 sg. dor</i>. ἔκτασα <span>[τᾱ]</span> THCR. <i>Idyl. 5, 6 ; 3 duel dor</i>. ἐκτασάσθαν, PD. <i>O. 9, 45 Bgk. Pf. ion</i>. ἔκτημαι, IL. <i>9, 402 ;</i> ESCHL. <i>Pr. 795 ;</i> AND. <i>28, 12 ; d’où 3 pl</i>. ἐκτέαται, HDT. <i>4, 23 ; 6, 52, et inf</i>. ἐκτῆσθαι, PLAT. <i>Phil. 58, etc. Pl.q.pf. poét</i>. κεκτήμην, EUR. <i>I.A. 404 ; ion</i>. ἐκτήμην, HDT. <i>2, 108. Fut. ant. 2 sg</i>. κεκτήσεαι, EMPÉD. <i>225 Stein ; rar</i>. ἐκτήσομαι, PLAT. <i>Lach. 192. L’opt</i>. κεκτῴμην <i>non att., Cobet N. L. p. 233</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *tkeh₁-, commander, acquérir ; <i>cf. sscr</i>. kṣáyati.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κταομαι - κτάομαι</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G2933":"<h1>ktema</h1>\n<p>Strong n° 2933 <i>Prononciation [ktay'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une possession\n<ol type=\"a\">\n<li>propriétés, terres, biens</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κτῆμα, ατος (τὸ) :<br>   I</b> bien, propriété (meubles <i>ou</i> immeubles) ; <i>dans Hom. touj. au plur. (excepté</i> OD. <i>15, 19</i>) IL. <i>3, 72, etc. ;</i> OD. <i>4, 127, etc. ;</i> ESCHL. <i>Sept. 790 ;</i> SOPH. <i>O.C. 1027 ;</i> XÉN. <i>Cyr. 6, 1, 25 ; Hell. 5, 2, 10 ; en parl. de pers</i>. SOPH. <i>Tr. 245, etc. ;</i> EUR. <i>Rhes. 190 ;</i> XÉN. <i>Œc. 1, 7, etc. ; particul. :</i><br><b>      1</b> esclaves, EUR. <i>Med. 49 ;</i> XÉN. <i>Vect. 4, 42 ;</i> ARSTT. <i>Pol. 1, 2, 4, etc. ;</i><br><b>      2</b> bien de campagne, domaine, XÉN. <i>Œc. 20, 23 ;</i> DÉM. <i>239, 27 ;</i> HDN <i>2, 6, 5 ; joint à</i> ἀγρούς, IS. <i>55, 24 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> chose précieuse, objet désirable, SOPH. <i>Ph. 81, etc. ;</i> XÉN. <i>Cyr. 1, 5, 12 ;</i> κτῆμα ἐς ἀεί, THC. <i>1, 22,</i> bien <i>ou</i> trésor pour toujours ; <i>en parl. d’amis,</i> XÉN. <i>Mem. 2, 4, 1 ; 3, 11, 5, etc. ;</i><br><b>      2</b> <i>en gén</i>. chose, <i>même en mauv. part,</i> PLAT. <i>Leg. 863</i> b.<br><span><b>Étym</b>. κτάομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κτημα - κτῆμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2934":"<h1>ktenos</h1>\n<p>Strong n° 2934 <i>Prononciation [ktay'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une bête\n<ol type=\"a\">\n<li>spéc. une bête de somme</li>\n<li>utilisé pour les animaux à quatre pattes par différence avec les oiseaux et poissons</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κτῆνος, εος-ους (τὸ) :<br>      1</b> <i>touj. au pl</i>. biens, richesses, ESCHL. <i>Ag. 129 ;</i><br><b>      2</b> <i>particul</i>. richesses consistant en troupeaux, <i>d’où</i> troupeaux, bestiaux, HH. <i>30, 10 ;</i> HDT. <i>2, 41 et 64 ;</i> XÉN. <i>Cyr. 8, 3, 41 ; Œc. 7, 19 ;</i> PLAT. <i>Criti. 109</i> b, <i>d’où, au sg.,</i> tête de bétail, <i>particul</i>. un bœuf <i>ou</i> un mouton, HDT. <i>1, 132 ;</i> XÉN. <i>An. 5, 2, 3 ;</i> une bête de somme, cheval, mulet, <i>etc</i>. NT. <i>Luc. 10, 34, etc</i>.<br><span><b>Étym</b>. κτάομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κτημος - κτῆνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2935":"<h1>ktetor</h1>\n<p>Strong n° 2935 <i>Prononciation [ktay'-tore]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un possesseur, un propriétaire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κτήτωρ, ορος (ὁ)</b> qui possède, maître, DS. <i>Exc. p. 599, 17 ;</i> ANTH. <i>7, 206 ;</i> NT. <i>Ap. 4, 34</i>.<br><span><b>Étym</b>. κτάομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κτητωρ - κτήτωρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2936":"<h1>ktizo</h1>\n<p>Strong n° 2936 <i>Prononciation [ktid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre habitable, peupler un lieu, une région, une île\n<ol type=\"a\">\n<li>fonder une cité, une colonie, un état</li>\n</ol>\n</li>\n<li>créer\n<ol type=\"a\">\n<li>de Dieu créant le monde</li>\n<li>former, c.à.d changer complètement ou transformer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κτίζω</b> <span>(<i>f</i>. ίσω <span>[ῐ]</span>, <i>ao</i>. ἔκτισα <span>[ῐ]</span>, <i>pf</i>. κέκτικα <span>[ῐ]</span> ; <i>pass. ao</i>. ἐκτίσθην, <i>pf</i>. ἔκτισμαι)</span><br><b>      1</b> bâtir (des maisons, des villes) <i>d’où</i> asseoir des constructions : Δαρδανίην, IL. <i>20, 216 ;</i> χώρην, HDT. <i>1, 149, etc</i>. en Dardanie, dans un pays ;<br><b>      2</b> <i>p. ext</i>. fonder, <i>en gén. :</i> κτ. πόλιν, PD. <i>P. 1, 121 ;</i> HDT. <i>1, 167, 168 ;</i> THC. <i>1, 7, etc</i>. bâtir une ville ; Θήϐης ἕδος, OD. <i>11, 263,</i> jeter les fondements de Thèbes ; ἀποικίαν, ESCHL. <i>Pr. 815,</i> fonder une colonie ; ἄλσος, PD. <i>P. 5, 89,</i> planter un bois ; βωμόν, PD. <i>O. 7, 42,</i> élever un autel ; τάφον τινί, SOPH. <i>Ant. 1101,</i> élever un tombeau à qqn ;<br><b>      3</b> <i>p. anal</i>. fonder, instituer : ἑορτάν, PD. <i>O. 6, 69,</i> une fête ; ἵπποισιν τὸν χαλινόν, SOPH. <i>O.C. 715,</i> inventer le frein pour les chevaux ; <i>avec un part. :</i> Κύρνον κτ. ἥρων ἐόντα, HDT. <i>1, 167,</i> instituer le culte de Kyrnos comme héros ;<br><b>      4</b> <i>p. ext</i>. créer, produire, ESCHL. <i>Suppl. 171 ; fig</i>. κτ. ἐλεύθερόν τινα πημάτων, ESCHL. <i>Ch. 1060,</i> délivrer qqn de ses souffrances ;<br><b>      5</b> <i>p. suite,</i> accomplir, faire, <i>en gén</i>. SOPH. <i>Tr. 898</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao. poét</i>. ἔκτισσα, PD. <i>P. 1, 62 ;</i> ESCHL. <i>Pers. 289, ou</i> κτίσσα, IL. <i>20, 216 ;</i> THCR. <i>Idyl. 28, 17. Part. pf. épq</i>. κτίμενος <span>[ῐ]</span> (<i>comme de</i> *κτίω) ESCHL. <i>Ch. 806 (cf. le composé</i> ἐϋκτίμενος <span>[ῐ]</span> IL. <i>21, 433 ;</i> OD. <i>4, 476 ;</i> HÉS. <i>Sc. 81). Moy. ao. 3 sg</i>. ἐκτίσσατο, PD. <i>O. 10, 25 ; fr. 1, 4 ;</i> CALL. <i>fr. 104</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *tḱ-ei-, établir ; <i>cf. sscr</i>. kṣéti.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κτιζω - κτίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 12 versets de 7 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (4)</li>\n<li>Colossiens (3)</li>\n<li>1 Timothée (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2937":"<h1>ktisis</h1>\n<p>Strong n° 2937 <i>Prononciation [ktis'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'action de fonder, d'établir, de construire, etc.\n<ol type=\"a\">\n<li>l'action de créer, création</li>\n<li>création c.à.d la chose créée\n<ol>\n<li>les choses individuelles, une créature, une création\n<ol type=\"a\">\n<li>toute chose créée</li>\n<li>chose à laquelle est appelée un homme converti de l'idolâtrie au Judaïsme</li>\n<li>la somme ou masse des choses créées, le monde</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>institution, ordonnance, autorité</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κτίσις, εως (ἡ)</b> <span>[ῐσ]</span><br><b>   I</b> <i>act. :</i><br><b>      1</b> fondation (de colonies, de villes) ISOCR. <i>272</i> e ; <i>au plur</i>. POL. <i>9, 1, 4, etc. ;</i> PLUT. <i>M. 435</i> d ;<br><b>      2</b> création : τοῦ κόσμου, NT. <i>Rom. 1, 20,</i> création du monde ;<br><b>      3</b> <i>fig</i>. entreprise, <i>d’où</i> action, PD. <i>O. 13, 83 ;</i><br><b>   II</b> <i>pass</i>. ce qui est créé, <i>d’où :</i><br><b>      1</b> la création, l’univers, le monde, NT. <i>Marc. 10, 6 ; 13, 19, etc. ;</i><br><b>      2</b> chose créée, créature, SPT. <i>Judith 9, 12 ; Ps. 73, 18, etc. ;</i> NT. <i>Rom. 1, 25 ; 8, 38, etc. ; Col. 1, 15 ; au pl</i>. SPT. <i>Tob. 8, 5 ;</i><br><b>      3</b> autorité instituée, NT. <i>1Petr. 2, 13</i>.<br><span><b>Étym</b>. κτίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κτισις - κτίσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 19 versets de 9 livres bibliques (NT)\n<ul>\n<li>Marc (3)</li>\n<li>Romains (7)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Colossiens (2)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2938":"<h1>ktisma</h1>\n<p>Strong n° 2938 <i>Prononciation [ktis'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chose fondée</li>\n<li>ce qui est créé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κτίσμα, ατος (τὸ) :<br>      1</b> <i>act</i>. fondation, établissement, STR. <i>315 ;</i> DH. <i>1, 113 Reiske ;</i><br><b>      2</b> <i>pass</i>. créature, SPT. <i>Sap. 9, 2 ; Sir. 36, 20 ; 38, 34 ; 3 Macc. 5, 11 ;</i> NT. <i>1Tim. 4, 4 ; Jac. 1, 18</i>.<br><span><b>Étym</b>. κτίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κτισμα - κτίσμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2939":"<h1>ktistes</h1>\n<p>Strong n° 2939 <i>Prononciation [ktis-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un fondateur</li>\n<li>un créateur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κτίστης, ου (ὁ) :<br>      1</b> fondateur, ARSTT. <i>fr. 507 ;</i> DL. <i>2, 120 ;</i> ATH. <i>345</i> d ; <i>d’où</i> le créateur, SPT. <i>2Reg. 22, 32 ; Judith 9, 12 ; Sir. 24, 8 ; 2 Macc. 1, 24, etc. ;</i><br><b>      2</b> qui rétablit, qui restaure, PLUT. <i>Cic. 22</i>.<br><span><b>Étym</b>. κτίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κτιστης - κτίστης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2940":"<h1>kubeia</h1>\n<p>Strong n° 2940 <i>Prononciation [koo-bi'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeux de dés</li>\n<li>métaph. la déception des hommes, car les joueurs de dés trichaient quelquefois et trompaient leurs partenaires</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυϐεία, ας (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> jeu de dés, PLAT. <i>Phædr. 274</i> d ;<br><b>      2</b> <i>fig</i>. risque, hasard, XÉN. <i>Mem. 1, 3, 2</i>.<br><span><b>Étym</b>. κύϐος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυβεια - κυβεία</font>\n<br><br>vient de 'kubos' (un « cube », c.à.d un dé pour jouer)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2941":"<h1>kubernesis</h1>\n<p>Strong n° 2941 <i>Prononciation [koo-ber'-nay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un gouvernant, un gouvernement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυϐέρνησις, εως (ἡ)</b> <span>[ῠ]</span> action de diriger à l’aide d’un gouvernail, PLAT. <i>Rsp. 488</i> b ; <i>fig</i>. PD. <i>P. 10, 112 (dor</i>. κυϐερνάσιες <span>[ᾱ]</span>).<br><span><b>Étym</b>. κυϐερνάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυβερνεσις - κυβέρνησις</font>\n<br><br>vient de kubernao (origine : Latin, 'gouverner')</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2942":"<h1>kubernetes</h1>\n<p>Strong n° 2942 <i>Prononciation [koo-ber-nay'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>timonier, homme de barre, maître de navigation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυϐερνήτης, ου (ὁ)</b> <span>[ῠ]</span><br><b>   I</b> <i>primit</i>. pilote, chef de timonerie, IL. <i>19, 43 ;</i> OD. <i>3, 279 ; 9, 78, etc. ;</i> ESCHL. <i>Suppl. 770 ; fig</i>. EUR. <i>Suppl. 880 ;</i> PLAT. <i>Phædr. 247</i> c ;<br><b>   II</b> <i>postér</i>. officier de marine :<br><b>      1</b> commandant en second d’un navire, <i>subordonné au triérarque,</i> PLUT. <i>M. 807</i> b ;<br><b>      2</b> <i>particul</i>. commandant de l’arrière (<i>p. opp. à</i> πρῳρεύς, commandant de l’avant) XÉN. <i>An. 5, 8, 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. ion</i>. -εω, OD. <i>12, 412 ; acc</i>. -εα, HDT. <i>8, 18</i>.<br><span><b>Étym</b>. κυϐερνάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυβερνητης - κυβερνήτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2943":"<h1>kuklothen</h1>\n<p>Strong n° 2943 <i>Prononciation [koo-kloth'-en]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>environner, de tous côtés, tout autour</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυκλόθεν</b>, <i>adv</i>., de tous les points d’alentour, tout autour, HPC. <i>Fract. 774 ;</i> LYS. <i>110, 41 ;</i> SPT. <i>3Reg. 6, 5, etc</i>.<br><span><b>Étym</b>. κύκλος, -θεν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυκλοθεν - κυκλόθεν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G2944":"<h1>kukloo</h1>\n<p>Strong n° 2944 <i>Prononciation [koo-klo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire le tour</li>\n<li>entourer, encercler, environner\n<ol type=\"a\">\n<li>de personnes se tenant autour</li>\n<li>d'assiégeants</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυκλόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἐκύκλωσα, <i>pf</i>. κεκύκλωκα)</span><br><b>   I</b> arrondir en cercle, <i>càd. :</i><br><b>      1</b> courber de manière à former un cercle, <i>acc. :</i> κ. τόξα, ANTH. <i>12, 82,</i> courber un arc ; <i>au pass</i>. se courber en cercle, EUR. <i>Bacch. 1066 ;</i><br><b>      2</b> dessiner <i>ou</i> creuser en forme de cercle, PLAT. <i>Criti. 118</i> d ;<br><b>      3</b> tourner, rouler : δαλὸν ἐν Κύκλωπος ὄψει, EUR. <i>Cycl. 462,</i> le tison dans l’œil du Cyclope ; <i>fig. :</i> δίναις κυκλούμενον κέαρ, ESCHL. <i>Ag. 997,</i> cœur où tournoient des pensées vertigineuses ;<br><b>   II</b> envelopper, cerner : Ὠκεανὸς κυκλοῖ χθόνα, EUR. <i>Or. 1379,</i> l’Océan enveloppe la terre d’un cercle ; Πέργαμον κυκλώσας Ἄρει φονίῳ, EUR. <i>I.A. 775,</i> ayant entouré Pergame d’un cercle meurtrier ;<br><b><i>Moy.</i></b> :<br><b>   I <i>intr</i>.<br>      1</b> se mouvoir en cercle, former une ronde, CALL. <i>Dian. 267 ;</i><br><b>      2</b> aller en cercle, en rond, XÉN. <i>An. 6, 4, 20 ;</i> ARAT. <i>811 ;</i><br><b>   II <i>tr.</i></b> entourer, envelopper, cerner, ESCHL. <i>Sept. 121 ;</i> HDT. <i>3, 157, etc. ;</i> THC. <i>4, 127 ; 7, 81</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. part. dor</i>. κυκλώσαις, PD. <i>O. 10, 72. Moy. fut. au sens pass</i>. κυκλώσομαι, DH. <i>3, 24 ; au sens moy</i>. CALL. <i>Dian. 170 ;</i> XÉN. <i>Cyr. 6, 3, 20</i>.<br><span><b>Étym</b>. κύκλος ; <i>cf</i>. κυκλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυκλοω - κυκλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2945":"<h1>kuklo</h1>\n<p>Strong n° 2945 <i>Prononciation [koo'-klo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dans un cercle, autour de, de tous côtés</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>κυκλόω-ῶ</b> <span>(<i>f</i>. ώσω, <i>ao</i>. ἐκύκλωσα, <i>pf</i>. κεκύκλωκα)</span><br><b>   I</b> arrondir en cercle, <i>càd. :</i><br><b>      1</b> courber de manière à former un cercle, <i>acc. :</i> κ. τόξα, ANTH. <i>12, 82,</i> courber un arc ; <i>au pass</i>. se courber en cercle, EUR. <i>Bacch. 1066 ;</i><br><b>      2</b> dessiner <i>ou</i> creuser en forme de cercle, PLAT. <i>Criti. 118</i> d ;<br><b>      3</b> tourner, rouler : δαλὸν ἐν Κύκλωπος ὄψει, EUR. <i>Cycl. 462,</i> le tison dans l’œil du Cyclope ; <i>fig. :</i> δίναις κυκλούμενον κέαρ, ESCHL. <i>Ag. 997,</i> cœur où tournoient des pensées vertigineuses ;<br><b>   II</b> envelopper, cerner : Ὠκεανὸς κυκλοῖ χθόνα, EUR. <i>Or. 1379,</i> l’Océan enveloppe la terre d’un cercle ; Πέργαμον κυκλώσας Ἄρει φονίῳ, EUR. <i>I.A. 775,</i> ayant entouré Pergame d’un cercle meurtrier ;<br><b><i>Moy.</i></b> :<br><b>   I <i>intr</i>.<br>      1</b> se mouvoir en cercle, former une ronde, CALL. <i>Dian. 267 ;</i><br><b>      2</b> aller en cercle, en rond, XÉN. <i>An. 6, 4, 20 ;</i> ARAT. <i>811 ;</i><br><b>   II <i>tr.</i></b> entourer, envelopper, cerner, ESCHL. <i>Sept. 121 ;</i> HDT. <i>3, 157, etc. ;</i> THC. <i>4, 127 ; 7, 81</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. part. dor</i>. κυκλώσαις, PD. <i>O. 10, 72. Moy. fut. au sens pass</i>. κυκλώσομαι, DH. <i>3, 24 ; au sens moy</i>. CALL. <i>Dian. 170 ;</i> XÉN. <i>Cyr. 6, 3, 20</i>.<br><span><b>Étym</b>. κύκλος ; <i>cf</i>. κυκλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυκλω - κύκλῳ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2946":"<h1>kulisma</h1>\n<p>Strong n° 2946 <i>Prononciation [koo'-lis-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>chose roulée, ce qui s'est vautré dans la boue</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυλισμός, οῦ (ὁ)</b> <span>[ῠ]</span> <i>c</i>. κύλισις, THÉODOT. <i>Prov. 2, 18 ;</i> HIPPIATR. <i>p. 204, 4</i>.<br><br>\n<b>κύλισις, εως (ἡ)</b> <span>[ῠῐσ]</span><br><b>      1</b> action de se rouler (dans la poussière) ARSTT. <i>Phys. 3, 1, 6, etc. ;</i><br><b>      2</b> révolution d’un astre, ARSTT. <i>Cæl. 2, 8, 8</i>.<br><span><b>Étym</b>. κυλίω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυλισμα - κυλισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2947":"<h1>kulioo</h1>\n<p>Strong n° 2947 <i>Prononciation [koo-lee-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se rouler, se vautrer</li>\n<li>se rouler dans la boue</li>\n<li>se vautrer dans la fange</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυλίω</b> <span>(<i>f</i>. ίσω, <i>ao</i>. ἐκύλισα, <i>pf. inus</i>.)</span> <span>[ῠ]</span><br><b>      1</b> rouler : γαστέρας, THCR. <i>Idyl. 24, 18,</i> leur ventre, <i>en parl. de serpents ;</i><br><b>      2</b> soulever en roulant, ARSTT. <i>H.A. 5, 19, 18</i> ;<br><i>Pass.-moy. :</i><br><b>      1</b> se rouler : πρὸς τοῖς γόνασί τινος, DH. <i>8, 39,</i> aux genoux de qqn ;<br><b>      2</b> tourbillonner, <i>en parl. d’abeilles,</i> ARSTT. <i>H.A. 9, 40, 29 ;</i><br><b>      3</b> tourner sans cesse, aller et venir, ARSTT. <i>Pol. 6, 4, 13</i>.<br><span><b>Étym</b>. κυλίνδω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυλιοω - κυλίω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2948":"<h1>kullos</h1>\n<p>Strong n° 2948 <i>Prononciation [kool-los']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tordu, crochu, tortueux\n<ol type=\"a\">\n<li>des membres du corps</li>\n<li>blessé, abîmé, invalide</li>\n</ol>\n</li>\n<li>estropié, mutilé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυλλός, ή, όν :<br>      1</b> courbé : κυλλὴ χείρ, AR. <i>Eq. 1083,</i> main qui forme un creux (pour mendier) ;<br><b>      2</b> <i>en mauv. part,</i> tortu, déformé, <i>en parl. d’un membre,</i> HPC. <i>Art. 819</i> b ; AR. <i>Av. 1379 ; en parl. d’une oreille paresseuse ou inerte,</i> HPC. <i>805</i> h.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *(s)kel-, courber, recroqueviller.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυλλος - κυλλός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2949":"<h1>kuma</h1>\n<p>Strong n° 2949 <i>Prononciation [koo'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une grosse vague spéc. de la mer ou d'un lac\n<ol type=\"a\">\n<li>des hommes inquiets et impulsifs, balayés ici et là par leurs passions furieuses</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κῦμα, ατος (τὸ)</b> <i>litt</i>. ce qui s’enfle, <i>d’où :</i><br><b>A</b> flot, vague :<br><b>   I</b> <i>au pr</i>. IL. <i>2, 209, etc. ;</i> ESCHL. <i>Pr. 1050 ; Sept. 192 ;</i> EUR. <i>Hipp. 735 ; p. anal</i>. trouble violent de l’air agité comme les vagues, PLUT. <i>Pomp. 25 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> <i>en parl. de pers. :</i> κ. χερσαῖον στρατοῦ, ESCHL. <i>Sept. 64,</i> le flot d’une armée de terre ;<br><b>      2</b> <i>particul. avec idée de malheur :</i> ἄτης, ESCHL. <i>Pr. 886 ;</i> συμφορᾶς, EUR. <i>Ion 927, etc</i>. flot du malheur, des calamités ; Ἀΐδα, PD. <i>N. 7, 31,</i> le flot d’Hadès, <i>càd</i>. la mort ; κελαινὸν κῦμα, ESCHL. <i>Eum. 832,</i> le flot noir, <i>càd</i>. la colère ;<br><b>      3</b> <i>p. anal. t. d’archit</i>. cimaise, renflement servant de bordure, ESCHL. <i>fr. 73 Nauck ;</i><br><b>B</b> toute production :<br><b>      1</b> fœtus, ESCHL. <i>Eum. 659 ;</i> ANTH. <i>6, 200, etc. ;</i><br><b>      2</b> fruit <i>ou</i> production de la terre, ESCHL. <i>Ch. 128 ; p. suite,</i> jeune pousse, TH. <i>H.P. 1, 6, 9 ; particul</i>. tige de chou (<i>lat</i>. cyma) GAL. <i>6, 365</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ḱuh₁-, enfler ; <i>v</i>. κυέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυμα - κῦμα</font>\n<br><br>vient de 'kuo' (gonfler, enfler, plier)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> - une vague, suggérant des successions ininterrompues\n<br><br> - une grande vague, une lame, la houle, suggérant volume et étendue. fig. : Application aux mots, à la parole.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2950":"<h1>kumbalon</h1>\n<p>Strong n° 2950 <i>Prononciation [koom'-bal-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une cymbale, c.à.d une cuvette creuse en cuivre, produisant un son musical lorsqu'elle est frappée contre une autre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κύμϐαλον, ου (τὸ)</b> <span>[ᾰ]</span> cymbale, <i>d’ord. au plur</i>. PD. <i>fr. 48 ;</i> DS. <i>2, 38, etc. ; au sg</i>. XÉN. <i>Eq. 1, 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυμβαλον - κύμβαλον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2951":"<h1>kuminon</h1>\n<p>Strong n° 2951 <i>Prononciation [koo'-min-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le cumin est une plante cultivée en Palestine avec des graines au goût amer et d'un parfum aromatique</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κύμινον, ου (τὸ)</b> <span>[ῠῑ]</span> cumin, <i>plante et graine qui servait pour assaisonnement,</i> COM. (ATH. <i>68</i> a, <i>etc</i>.).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυμινον - κύμινον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2952":"<h1>kunarion</h1>\n<p>Strong n° 2952 <i>Prononciation [koo-nar'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un petit chien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυνάριον, ου (τὸ)</b> <span>[ῠᾰ]</span> petit chien, petite chienne, XÉN. <i>Cyr. 8, 4, 20 ;</i> PLAT. <i>Euthyd. 298 d et e ; t. injur</i>. ALC. COM. <i>2, 833</i>.<br><span><b>Étym</b>. <i>dim. de</i> κύων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυναριον - κυνάριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G2953":"<h1>Kuprios</h1>\n<p>Strong n° 2953 <i>Prononciation [koo'-pree-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>un Chypriote : un natif de Chypre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κύπριος, α, ον</b>, de Chypre, ESCHL. <i>Pers. 891, Suppl. 282, etc. ;</i> οἱ Κύπριοι, PD. <i>P. 2, 28 ;</i> HDT. <i>3, 19 ;</i> XÉN. <i>Cyr. 6, 2, 10,</i> les Chypriotes ; τὰ Κύπρια, HDT. <i>2, 117 ;</i> ARSTT. <i>Poet. 23,</i> les chants de Chypre, <i>poème cyclique</i>.<br><span><b>Étym</b>. Κύπρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κυπριος - Κύπριος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G2954":"<h1>Kupros</h1>\n<p>Strong n° 2954 <i>Prononciation [koo'-pros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Chypre (Angl. Cyprus) = « amour : une fleur »\n<ol><li>île agréable et très fertile de la Méditerranée, située entre la Cilicie et la Syrie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κύπρος, ου (ἡ)</b> <span>[υ]</span> Chypre (<i>auj</i>. Kýpros, <i>turc</i> Kibris) <i>î. de la côte sud de l’Asie Mineure,</i> OD. <i>4, 83, etc. ;</i> HDT. <i>2, 182 ;</i> THC. <i>1, 94, etc</i>.<br><br>\n<b>κύπρος, ου (ἡ) :<br>      1</b> cyprus <i>ou</i> henné, <i>plante odorante qu’on recueille à Chypre, en Syrie, en Égypte, et dont la fleur ou le suc étaient employés pour une huile ou certains parfums et onguents,</i> SPT. <i>Cant. 1, 14 ;</i> DIOSC. <i>1, 124 ;</i> JOS. <i>B.J. 4, 8, 3 ; p. ext</i>. huile de cyprus, TH. <i>Od. 25 ;</i><br><b>      2</b> mesure de deux <i>modii,</i> ALC. (POLL. <i>10, 25, § 113</i>).<br><span><b>Étym</b>. Κύπρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κυπρος - Κύπρος</font>\n<ol><li>origine incertaine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G2955":"<h1>kupto</h1>\n<p>Strong n° 2955 <i>Prononciation [koop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>se pencher, plier en avant, courber la tête</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κύπτω</b> <span>(<i>f. réc</i>. κύψω, <i>ao</i>. ἔκυψα, <i>pf</i>. κέκυφα <span>[ῡ]</span>)</span><br><b>      1</b> se baisser en avant, IL. <i>4, 468, etc. ;</i> OD. <i>11, 585 ;</i> κάτω, AR. <i>Vesp. 279,</i> se pencher en bas ; ἐς τὴν γῆν, HDT. <i>3, 14 ;</i> AR. <i>fr. 349 ;</i> εἰς γῆν, PLAT. <i>Rsp. 586</i> a, se pencher à terre ; κέρεα κεκυφότα ἐς τὸ ἔμπροσθεν, HDT. <i>4, 183,</i> cornes penchées en avant, <i>en parl. de certains bœufs africains ;</i><br><b>      2</b> baisser la tête <i>ou</i> les yeux par honte, par pudeur, <i>etc</i>. AR. <i>Eq. 1354, Th. 930 ; en parl. d’une personne pensive,</i> EPICRAT. (ATH. <i>59</i> e) ;<br><b>      3</b> <i>pour marquer l’ardeur ou l’empressement :</i> κύψας ἐσθίει, AR. <i>Pax 33,</i> il mange la tête sur son assiette, <i>càd</i>. avidement ; θέει κύψας, AR. <i>Ran. 1091,</i> il court tête baissée ;<br><b>      4</b> être incliné vers la terre, <i>en parl. des animaux, p. opp. à l’homme,</i> ARSTT. <i>P.A. 2, 11</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυπτω - κύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2956":"<h1>Kurenaios</h1>\n<p>Strong n° 2956 <i>Prononciation [koo-ray-nah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un natif de Cyrène</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κυρηναῖος, α, ον</b>, de Cyrène, STR. <i>838, etc. ;</i> οἱ Κυρηναῖοι, HDT. <i>3, 13 ; 4, 152,</i> les Cyrénéens ; ἡ Κυρηναία, ARSTT. <i>H.A. 5, 30,</i> la Cyrénaïque.<br><span><b><span class=\"arrow\"></span></b> <span>[ῡ]</span> ANTH. <i>App. 25, etc. ;</i> <span>[ῠ]</span> ALEX. (ATH. <i>510</i> a) <i>etc</i>.<br><span><b>Étym</b>. Κυρήνη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κυρηναιος - Κυρηναῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G2957":"<h1>Kurene</h1>\n<p>Strong n° 2957 <i>Prononciation [koo-ray'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Cyrène (Angl. Cyrene) = « suprématie de la bride », « qui gouverne, froid »\n<ol><li>grande et florissante cité de la Cyrénaïque libyenne, une des cinq villes formant le Pentapole, dans la Tripolitaine actuelle. Située sur un plateau à plus de 600 m. d'altitude, à environ 16 km de la Méditerranée. Parmi ses habitants on comptait un grand nombre de Juifs, investis du droit de citoyens</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κυρήνη, ης (ἡ)</b> <span>[υ]</span><br><b>      1</b> Kyrènè (Cyrène, <i>auj</i>. Shahhat) <i>colonie grecque d’Afrique,</i> PD. <i>P. 4, 2 ;</i> HDT. <i>4, 164, etc. ;</i> οἱ ἀπὸ τῆς Κυρήνης, SEXT. <i>192, 24 Bkk</i>. les philosophes de l’école cyrénaïque (<i>v</i>. Κυρηναϊκός) ;<br><b>      2</b> <i>f</i>. PD. <i>P. 9, 32 ;</i> A. RH. <i>2, 500</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῠ]</span> HÉS. PD. <i>ll. cc. ;</i> <span>[ῡ]</span> AR., A. RH. <i>ll. cc. — Dor</i>. Κυράνα <span>[ᾱᾱ]</span> PD. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κυρηνη - Κυρήνη</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2958":"<h1>Kurenios</h1>\n<p>Strong n° 2958 <i>Prononciation [koo-ray'-nee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Quirinius (Angl. Cyrenius) = « guerrier »\n<ol><li>forme grecque originale: Quirinius, forme grecque latinisée: Cyrénius. Romain, légat d'Auguste, qui gouverna la Syrie, probablement à deux reprises : un peu avant la naissance de Christ, il organisa le recensement qui fit que Joseph et Marie allèrent à Bethléhem (<a class=\"ref\" data-r=\"LUK2.2\">Luc 2.2</a>). Le second recensement est mentionné en <a class=\"ref\" data-r=\"ACT5.37\">Actes 5.37</a>.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κυρηνιος - Κυρήνιος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2959":"<h1>Kuria</h1>\n<p>Strong n° 2959 <i>Prononciation [koo-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une Chrétienne à qui est adressée la seconde Epître de Jean</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυρία, ας (ἡ)</b> <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κυρια - Κυρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2960":"<h1>kuriakos</h1>\n<p>Strong n° 2960 <i>Prononciation [koo-ree-ak-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appartenant au Seigneur</li>\n<li>relatif au Seigneur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυριακός, ή, όν</b> <span>[ῡᾰ]</span> qui concerne le Seigneur, le Christ ; <i>subst</i>. ἡ κυριακή (<i>s.-e</i>. ἡμέρα) NT. <i>Apoc. 1, 10,</i> le jour du Seigneur, le Dimanche.<br><span><b>Étym</b>. κύριος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυριακος - κυριακός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2961":"<h1>kurieuo</h1>\n<p>Strong n° 2961 <i>Prononciation [ko-ree-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être seigneur de, gouverner, avoir la domination sur</li>\n<li>de choses et forces\n<ol type=\"a\">\n<li>exercer une influence sur, avoir du pouvoir sur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυριεύω</b> <span>[ῡ]</span><br><b>      1</b> être maître de, <i>gén</i>. XÉN. <i>Mem. 2, 6, 22 ; 3, 5, 10 ; abs</i>. avoir plein pouvoir, ESCHN. <i>5, 36 (loi</i>) ;<br><b>      2</b> devenir maître de, se rendre maître de, <i>gén</i>. POL. <i>1, 7, 11, etc. ;</i><br><b>      3</b> ὁ κυριεύων, ARR. <i>Epict. 2, 18, 17, etc. ;</i> DL. <i>2, 108, litt</i>. « le dominant », <i>sorte d’argument sophistique</i>.<br><span><b>Étym</b>. κύριος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυριευω - κυριεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (5)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2962":"<h1>kurios</h1>\n<p>Strong n° 2962 <i>Prononciation [koo'-ree-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui à qui une personne ou une chose appartient, sur quoi il a un pouvoir de décision : maître, seigneur\n<ol type=\"a\">\n<li>celui qui possède et dispose d'une chose\n<ol>\n<li>propriétaire ; celui qui a contrôle sur une chose, le maître</li>\n<li>dans un état : souverain, prince, chef, l'empereur Romain</li>\n</ol>\n</li>\n<li>titre d'honneur exprimant respect et révérence, par lequel des serviteurs saluent leur maître</li>\n<li>titre donné : Dieu, le Messie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κύριος, α, ον</b> <span>[ῡ]</span> qui a autorité <i>ou</i> plein pouvoir, <i>d’où :</i><br><b>A</b> <i>en parl. de pers. :</i><br><b>   I</b> qui est maître de, <i>gén</i>. PD. <i>P. 2, 106, etc. ;</i> ESCHL. <i>Ag. 878 ;</i> PLAT. <i>Leg. 700</i> d, <i>etc. ;</i> θανάτου, PLAT. <i>Criti. 120</i> d, qui a droit de vie et de mort ; <i>avec l’inf</i>. ESCHL. <i>Ag. 104 ;</i> THC. <i>4, 18 ;</i> κύριος ἀπολέσαι, σῶσαι δ' ἄκυρος, AND. <i>30, 12,</i> tout-puissant pour perdre, impuissant pour sauver ; <i>ou avec un part. :</i> κύριος ἦν πράσσων ταῦτα, THC. <i>8, 51,</i> il était maître d’agir ainsi ; πριαμένους ἢ πωλοῦντας κυρίους εἶναι, THC. <i>5, 34,</i> être maîtres d’acheter et de vendre ; <i>cf</i>. POL. <i>6, 37, 8, etc. ; abs</i>. qui est le maître, qui a plein pouvoir, PLAT. <i>Rsp. 429</i> b ; ARSTT. <i>Rhet. 2, 24, 9 ; p. suite</i> qui est le maître de, celui qu’une chose regarde, SOPH. <i>Aj. 734,</i> propre à, SOPH. <i>O.R. 1453 ;</i><br><b>   II</b> <i>subst</i>. ὁ κύριος :<br><b>      1</b> maître, souverain, ESCHL. <i>Ch. 658 ;</i> SOPH. <i>Aj. 734 ; O.R. 288, etc. en parl. des dieux ; dans les Livres saints et les écriv. ecclés</i>. le Seigneur, Dieu, SPT. <i>Esaï. 32, 2 ;</i><br><b>      2</b> <i>à Rome,</i> l’empereur, NT. <i>25, 26 ;</i><br><b>      3</b> maître de maison, chef de famille, PLUT. <i>M. 271</i> d ; <i>postér. surt. au voc. titre honorifique ou de politesse</i> « seigneur », « maître », <i>analogue à notre</i> « Monsieur », NT. <i>Joh. 12, 21, etc. ;</i> ἡ κυρία, maîtresse de maison, dame, PHILÉM. (<i>Com. fr. 4, 65</i>) ; EPICT. <i>Ench. 40 ; au voc</i>. « maîtresse, Madame », DC. <i>48, 44 ;</i><br><b>      4</b> maître d’esclaves <i>ou</i> de domestiques, AR. <i>Pl. 6 ;</i> ANT. <i>120, 1, etc. ;</i> ARSTT. <i>Pol. 2, 9, 4 ;</i> ὁ κ. τινος, EUR. <i>Andr. 558,</i> le maître de qqn ;<br><b>      5</b> tuteur, curateur, DÉM. <i>1054, 18, etc. ;</i> IS. <i>59, 26, etc. ;</i><br><b>B</b> <i>en parl. de choses,</i> qui est dominant, <i>d’où :</i><br><b>      1</b> qui a pleine autorité ; <i>subst</i>. ἡ κυρία, pouvoir, autorité, SPT. <i>Esaï. 40, 10 ;</i> POL. <i>6, 2, 5, etc. ;</i> τὸ κύριον, ARSTT. <i>Pol. 3, 10, 1,</i> le pouvoir dirigeant (dans un État) ; τὰ κύρια, DÉM. <i>424, 11,</i> les autorités ;<br><b>      2</b> qui a sa force propre : κυρία ἐκκλησία, AR. <i>Ach. 19,</i> l’assemblée par excellence, régulière, ordinaire, <i>p. opp. à</i> σύγκλητος, celle où l’on vient par convocation ; κύριος νόμος, DÉM. <i>700, 8,</i> loi en vigueur ; κύριοι δίκαι, EUR. <i>Her. 143,</i> jugements qui ont force de loi ; κύριαι συνθῆκαι, LYS. <i>150, 35,</i> conventions qui ont toute leur force, <i>càd</i>. ratifiées, confirmées ; <i>particul. en parl. du temps,</i> fixé, marqué : ἡ κ. ἡμέρη, HDT. <i>5, 50, 93,</i> le jour marqué ; κ. ἐν ἡμέρᾳ, ESCHL. <i>Suppl. 732,</i> au jour fixé ; <i>cf</i>. κύριος μήν, PD. <i>O. 6, 52,</i> le mois marqué (celui de l’accouchement) ; τὸ κύριον, ESCHL. <i>Ag. 766,</i> le moment décisif ; ἡ κυρία, DÉM. <i>511, 22,</i> le jour décisif, le terme, <i>càd</i>. le jour du jugement <i>ou</i> du paiement ;<br><b>      3</b> <i>p. suite,</i> capital, principal, le plus important, PLAT. <i>Conv. 218</i> d, <i>etc. ;</i> ARSTT. <i>H.A. 3, 2, etc. ; joint à</i> μέγιστος, PLAT. <i>Soph. 230</i> d ; PLUT. <i>Cam. 21 ; à</i> πρῶτος, TH. <i>C.P. 1, 1, 1 ;</i> τὸ κυριώτατον, ATT. le point principal, le plus important ;<br><b>C</b> <i>t. de gramm. et de rhét</i>. qui est employé en son sens propre et primitif, <i>p. opp</i>. au sens dérivé, ARSTT. <i>Rhet. 3, 2 ; p. opp. à</i> τροπικὴ φράσις, DH. <i>Lys. 3 ;</i> κύριον ὄνομα, mot employé au sens propre, ARSTT. <i>Poet. 21, 4 ; p. suite,</i> mot <i>ou</i> nom s’appliquant proprement à une personne, <i>d’où</i> nom propre, PLUT. <i>M. 747</i> e ; HDN <i>7, 5, 19</i>.<br><span>•<i> Cp</i>. -ώτερος, THC. <i>4, 18 ;</i> ESCHL. <i>Suppl. 965 ;</i> EUR. <i>I.A. 318 ;</i> PLAT. <i>Conv. 218</i> d, <i>etc. ;</i> ARSTT. <i>Nic. 6, 12, 3</i>. <i>• Sup</i>. -ώτατος, THC. <i>5, 53 ;</i> PLAT. <i>Tim. 84</i> c, <i>etc. ;</i> ARSTT. <i>H.A. 3, 2, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, EUR. <i>Her. 143 ; fém</i>. κυρία, CIA. <i>2, 230 a, 4 (pas av. 336 av. J.C.), etc. (v. Meisterh. p. 116, § 58, 2</i>).<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ḱeuh₁-, enfler, être fort ; <i>cf</i>. κυέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυριος - κύριος</font>\n<br><br>vient de 'kuros' (suprématie)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – est appliqué seulement par un esclave, et indique l'absolue propriété et un pouvoir sans contrôle\n<br><br> – a un sens plus large, s'applique aux rangs variés et aux relations de la vie et ne suggère ni propriété ni absolutisme</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n727 fois dans 668 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (82)</li>\n<li>Marc (18)</li>\n<li>Luc (106)</li>\n<li>Jean (53)</li>\n<li>Actes (113)</li>\n<li>Romains (44)</li>\n<li>1 Corinthiens (67)</li>\n<li>2 Corinthiens (29)</li>\n<li>Galates (6)</li>\n<li>Ephésiens (26)</li>\n<li>Philippiens (15)</li>\n<li>Colossiens (15)</li>\n<li>1 Thessaloniciens (24)</li>\n<li>2 Thessaloniciens (21)</li>\n<li>1 Timothée (6)</li>\n<li>2 Timothée (16)</li>\n<li>Philémon (6)</li>\n<li>Hébreux (16)</li>\n<li>Jacques (14)</li>\n<li>1 Pierre (8)</li>\n<li>2 Pierre (14)</li>\n<li>Jude (6)</li>\n<li>Apocalypse (22)</li>\n</ul>\n</td></tr>\n</table>","G2963":"<h1>kuriotes</h1>\n<p>Strong n° 2963 <i>Prononciation [koo-ree-ot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>domination, pouvoir, seigneurie, souveraineté\n<ol type=\"a\">\n<li>classe d'anges</li>\n</ol>\n</li>\n<li>dans le N.T. : celui qui possède la domination, La Souveraineté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυριότης, ητος (ἡ)</b> <span>[ῡ]</span> autorité, souveraineté, <i>au sens concret,</i> NT. <i>Eph. 1, 21 ;</i> COL. <i>1, 16</i>.<br><span><b>Étym</b>. κύριος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυριοτης - κυριότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2964":"<h1>kuroo</h1>\n<p>Strong n° 2964 <i>Prononciation [koo-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre valide, donner force de loi à</li>\n<li>confirmer publiquement, d'une façon solennelle, ratifier</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κυρόω-ῶ</b> <span>[ῡ]</span><br><b>      1</b> donner force de loi à, <i>acc. ; d’où</i> sanctionner, ratifier, <i>acc</i>. HDT. <i>6, 86 ;</i> THC. <i>8, 69 ;</i> ESCHL. <i>Eum. 602 ;</i><br><b>      2</b> faire prévaloir une décision, décider : πρὶν κεκυρῶσθαι σφαγάς, EUR. <i>El. 1069,</i> avant que le meurtre eût été décidé ; ἐκεκύρωτο συμϐάλλειν, HDT. <i>6, 110,</i> il avait été décidé qu’on en viendrait aux mains ; <i>avec une prop. inf</i>. décider que, <i>etc</i>. ARSTT. <i>fr. 551 ;</i><br><b>      3</b> <i>p. suite,</i> décider, trancher : δίκην, ESCHL. <i>Eum. 581, 639,</i> un procès ;<br><b><i>Moy.</i></b> donner de la force <i>ou</i> de l’autorité à, faire prévaloir, réaliser, accomplir, <i>acc</i>. PLAT. <i>Gorg. 451 b, c</i>.<br><span><b>Étym</b>. κῦρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυροω - κυρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G2965":"<h1>kuon</h1>\n<p>Strong n° 2965 <i>Prononciation [koo'-ohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un chien</li>\n<li>métaph. un homme à l'esprit impur, un insolent, impertinent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κύων</b> (<i>voc</i>. κύον, <i>gén</i>. κυνός, <i>dat</i>. κυνί, <i>acc</i>. κύνα ; <i>dat. pl</i>. κυσί) (ὁ, ἡ) <span>[ῠ]</span><br><b>A</b> <i>au propre :</i><br><b>   I</b> chien, chienne, IL. <i>1, 4, etc. ;</i> OD. <i>18, 86, etc. ;</i> κύνας ἐπικούρους ποιμνίων, PLAT. <i>Rsp. 416</i> a, chiens gardiens des troupeaux ; κύνες θηρευταί <i>ou</i> θηρευτῆρες, IL. <i>11, 325, etc. ;</i> κ. θηρευτικαί, AR. <i>Pl. 158 ;</i> PLAT. <i>Rsp. 459</i> a, chiens, chiennes de chasse ; κύων Ἀΐδαο, IL. <i>8, 368 ;</i> OD. <i>11, 623 ; abs</i>. ὁ κύων, XÉN. <i>An. 6, 2, 2,</i> le chien d’Hadès, <i>càd</i>. Cerbère ; νὴ <i>ou</i> μὰ τὸν κύνα, PLAT. <i>Ap. 21</i> e, <i>Gorg. 482</i> b, <i>etc</i>. par le chien, <i>serment favori de Socrate ;</i><br><b>   II</b> <i>fig. comme symbole :</i><br><b>      1</b> <i>de fidélité, en parl. du chien Argos,</i> OD. <i>17, 291, etc. ;</i><br><b>      2</b> <i>de vigilance,</i> IL. <i>10, 181 ;</i> OD. <i>16, 4, etc. ;</i> ESCHL. <i>Ag. 896 ;</i><br><b>      3</b> <i>d’audace ou d’impudence, surt. en parl. de femmes,</i> IL. <i>6, 344 ; 8, 423, etc. ;</i> OD. <i>18, 338, etc. ; d’où en parl. d’hommes,</i> κακαὶ κύνες, IL. <i>13, 623, etc</i>. mauvaises chiennes ;<br><b>      4</b> <i>de rage, de fureur,</i> IL. <i>8, 298, etc. ;</i> OD. <i>17, 248, etc. ;</i><br><b>   III</b> <i>p. ext. chez les poètes, en parl. d’animaux divers :</i> Διὸς πτηνὸς κύων, ESCHL. <i>Pr. 1022 ;</i> SOPH. <i>fr. 766,</i> le chien ailé de Zeus, <i>càd</i>. l’aigle ; ἡ ῥαψῳδὸς κ. SOPH. <i>O.R. 391,</i> la chienne rhapsode, <i>en parl. du Sphinx ;</i> Ζηνὸς κύνες, ESCHL. <i>Pr. 803,</i> les chiennes de Zeus, <i>en parl. des Harpyies ;</i> κύνες Κωκυτοῦ, AR. <i>Ran. 472,</i> les chiennes du Cocyte, <i>en parl. des Érinyes ;</i> Λέρνας κ. EUR. <i>H.f. 420,</i> la chienne de Lerne, <i>en parl. de l’hydre de Lerne ; en parl. de choses :</i> κύνες Ἡφαίστοιο, ALEX. (ATH. <i>379</i> c) les chiennes d’Hèphæstos, <i>en parl. des étincelles ;</i><br><b>   IV</b> <i>en parl. des philosophes cyniques, à Athènes,</i> ARSTT. <i>Rhet. 3, 10 ;</i> ATH. <i>216</i> b ; PLUT. <i>M. 717</i> c, <i>956</i> b, <i>etc. ;</i><br><b>B</b> <i>p. anal. :</i><br><b>      1</b> <i>constellation :</i> κύων Ὠρίωνος, IL. <i>22, 29, ou abs</i>. ὁ κύων, SOPH. <i>fr. 941 ;</i> ARSTT. <i>Rhet. 2, 24,</i> le chien d’Orion <i>ou</i> Sirius <i>ou abs</i>. le Chien ; <i>p. suite,</i> la saison de la Canicule ; ἐπὶ κυνί, DÉM. <i>927, 3 ;</i> ARSTT. <i>H.A. 8, 15 ;</i> ὑπὸ κύνα, ARSTT. <i>H.A. 6, 1, 12 ;</i> DS. <i>19, 109,</i> pendant la Canicule ; περὶ κύνα, TH. <i>C.P. 3, 3, 3,</i> aux environs de la Canicule ; μετὰ κύνα, TH. <i>H.P. 1, 9, 5,</i> après la Canicule ;<br><b>      2</b> chien de mer, OD. <i>12, 96 ;</i> EL. <i>N.A. 1, 55, etc. ;</i><br><b>      3</b> sorte de poisson, <i>vulg</i>. l’empereur, ANAXIPP. (EL. <i>N.A. 13, 4</i>) ; POL. <i>34, 2, 15 ;</i><br><b>      4</b> <i>frenum præputii</i> <span>[frein du prépuce]</span>, GAL. <i>4, 358 ;</i> P. EG. <i>6, 54 ;</i><br><b>      5</b> convulsion de la mâchoire, GAL. <i>8, 41 ;</i><br><b>      6</b> boulette de mie de pain qu’on jette aux chiens, <i>c</i>. ἀπομαγδαλία, DIOSC. (EUST. <i>p. 1857, 19</i>) ;<br><b>      7</b> κύων ξυλίνη, ORACL. (ATH. <i>70</i> c) rose de chien, <i>càd</i>. églantier.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. κύων, ARCHIPP. (<i>Bkk. p. 105, 16) ; dat. pl. poét</i>. κύνεσσι, IL. <i>1, 4, etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ḱuon-, chien ; <i>cf. sscr</i>. śvā́, <i>lat</i>. canis, <i>all</i>. Hund.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κυων - κύων</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Philippiens (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2966":"<h1>kolon</h1>\n<p>Strong n° 2966 <i>Prononciation [ko'-lon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un membre du corps, en particulier les membres les plus aux extrémités, tels les pieds</li>\n<li>un corps mort, un cadavre, une carcasse, d'autant plus si les membres du corps sont disséminés</li>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κῶλον, ου (τὸ) :<br>   I</b> membre d’homme <i>ou</i> d’animal, <i>particul</i>. jambe, ESCHL. <i>Pr. 323 ;</i> SOPH. <i>O.C. 183, etc. ; au pl</i>. les jambes, ESCHL. <i>Pr. 81, etc. ;</i> SOPH. <i>O.C. 19 ; en parl. d’animaux,</i> PLAT. <i>Tim. 91</i> e ; ARSTT. <i>H.A. 2, 1, 8, etc. ; p. ext</i>. les bras et les jambes, les extrémités, PLAT. <i>Tim. 76</i> e ;<br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> branches d’une plante, ANTH. <i>7, 315 ;</i><br><b>      2</b> bras d’une fronde, ANTH. <i>7, 172 ;</i><br><b>      3</b> l’une des deux moitiés de la carrière, ESCHL. <i>Ag. 344 ;</i><br><b>      4</b> partie d’une tige de roseau, d’un nœud à un autre, CORN. <i>30 ;</i><br><b>      5</b> <i>t. de rhét</i>. membre d’une période, ARSTT. <i>Rhet. 3, 9, 13 ;</i> D. PHAL. <i>§ 34 ;</i><br><b>      6</b> vers d’une strophe, DH. <i>Comp. 19, 22, etc. ;</i><br><b>      7</b> côté d’une construction, d’une figure de mathématiques, HDT. <i>2, 126, etc. ;</i> PLAT. <i>Leg. 947</i> e ;<br><b>      8</b> <i>t. d’anat</i>. le côlon <i>ou</i> gros intestin, DIOSC. <i>1, 176 ;</i> GAL. <i>2, 238</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κωλον - κῶλον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2967":"<h1>koluo</h1>\n<p>Strong n° 2967 <i>Prononciation [ko-loo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>empêcher, prévenir d'une défense</li>\n<li>refuser une chose provenant de quelqu'un</li>\n<li>dénier ou refuser une chose à quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κωλύω</b> <span>(<i>f</i>. ύσω, <i>ao</i>. ἐκώλυσα, <i>pf</i>. κεκώλυκα)</span> <span>[ῠ <i>prés. et impf. ;</i> ῡ <i>aux autres temps</i>]</span><br><b>   I</b> écarter, détourner :<br><b>      1</b> <i>avec double rég</i>. τινά τινος, XÉN. <i>An. 1, 6, 2, etc. ;</i> τινὰ ἀπό τινος, XÉN. <i>Cyr. 1, 3, 11, etc</i>. qqn de qqn <i>ou</i> de qqe ch. ; τινά τι, SOPH. <i>Ph. 1241,</i> qqn de qqe ch. ; ἃ δ' αὐτοὶ ὠφελούμενοι τοὺς ἐναντίους κωλύσετε (<i>s.-e</i>. ὠφελεῖσθαι) THC. <i>6, 91,</i> quant aux avantages que vous retirerez (de cette position) et à ceux dont vous priverez l’ennemi ; τινά <i>avec l’inf</i>. EUR. <i>Alc. 899, etc. ;</i> PLAT. <i>Ap. 39</i> e, <i>etc. ; avec</i> ὡς <i>ou</i> ὥστε <i>et l’inf</i>. ESCHL. <i>Suppl. 972 ;</i> THC. <i>7, 36 ; avec</i> μή <i>et l’inf</i>. EUR. <i>Ph. 1268 ;</i> XÉN. <i>Hell. 3, 2, 22 ; avec</i> μὴ οὐ <i>et l’inf</i>. DH. <i>2, 3 ; avec un part</i>. κ. τινὰ πόλεμον ἐμφύλιον εἰσάγοντα, DH. <i>7, 25,</i> empêcher qqn d’amener une guerre civile ; <i>au pass</i>. μὴ κωλύωνται περαιούμενοι, THC. <i>1, 26,</i> de peur qu’ils ne fussent empêchés (par les Corcyréens) de faire la traversée ; <i>avec une prop. relat. :</i> κωλύειν εἴ τις, <i>etc</i>. DÉM. <i>44, 14,</i> empêcher qqn de, <i>etc. ;</i><br><b>      2</b> avec un seul <i>rég. :</i> κ. τι, EUR. <i>I.A. 1390 ;</i> XÉN. <i>An. 4, 2, 24,</i> empêcher qqe ch. ; τινά, THC. <i>1, 35 ;</i> ARSTT. <i>Nic. 3, 5, 7,</i> s’opposer à qqn ;<br><b>      3</b> <i>abs</i>. τὸ κωλῦον, XÉN. <i>An. 4, 5, 20,</i> l’obstacle ; οὐδὲν κωλύει, AR. <i>Eq. 732, etc</i>. il n’y a pas d’empêchement ; τί κωλύει ; PLAT. <i>Euthyphr. 9</i> d, <i>etc</i>. quel empêchement y a-t-il ? <i>impers. avec un acc. :</i> οὐ γὰρ ἐκεῖνο κωλύει ἐν ταῖς σπονδαῖς οὔτε τόδε, THC. <i>1, 144,</i> car il n’y a pas plus d’empêchement dans le traité pour ceci que pour cela ; <i>cf</i>. AR. <i>Av. 463 ;</i><br><b>   II</b> défendre, interdire, <i>avec l’inf</i>. XÉN. <i>Conv. 7, 1 ;</i><br><b>   III</b> réprimer, contenir, <i>acc</i>. HDN <i>3, 11, 6</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῡ]</span> ; <i>dev. une voy. qqf</i>. <span>[ῠ]</span> κωλύει <span>[ῠ]</span> AR. <i>Eq. 723 ; mais</i> <span>[ῡ]</span> AR. <i>Av. 463, Lys. 607, Pax 499 ;</i> κώλυεν <span>[ῠ]</span> PD. <i>P. 4, 57</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κωλυω - κωλύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 23 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (3)</li>\n<li>Luc (6)</li>\n<li>Actes (6)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2968":"<h1>kome</h1>\n<p>Strong n° 2968 <i>Prononciation [ko'-may]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le lieu vers lequel les travailleurs des champs retournent pour dormir, un village</li>\n<li>le nom de la cité proche des villages qui l'environnent et dont elle a la gestion</li>\n<li>les habitants de villages</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κώμη, ης (ἡ) :<br>      1</b> bourg, village, HÉS. <i>Sc. 18 ;</i> THC. <i>3, 94 ;</i> PLAT. <i>Leg. 627</i> a, <i>Rsp. 475</i> d ; <i>à Sparte, équivalent du dème attique,</i> ARSTT. <i>Poet. 3, 6 ;</i><br><b>      2</b> quartier d’une ville, ISOCR. <i>149</i> a ; PLAT. <i>Leg. 746</i> d.<br><span><b>Étym</b>. <i>Orig. inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κωμη - κώμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 27 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (7)</li>\n<li>Luc (12)</li>\n<li>Jean (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2969":"<h1>komopolis</h1>\n<p>Strong n° 2969 <i>Prononciation [ko-mop'-ol-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>village dont la dimension et le nombre d'habitants est proche de celui d'une cité, une bourgade, une petite ville</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κωμό·πολις, εως (ἡ)</b> bourg-ville, <i>càd</i>. gros bourg, petite ville, STR. <i>537 ;</i> NT. <i>Marc. 1, 38</i>.<br><span><b>Étym</b>. κώμη, πόλις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κωμοπολις - κωμόπολις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2970":"<h1>komos</h1>\n<p>Strong n° 2970 <i>Prononciation [ko'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une orgie, ripaille, banquet, festin bruyant\n<ol type=\"a\">\n<li>procession nocturne et rituelle de gens à moitié ivres, à l'esprit folâtre après un souper, défilaient à travers les rues avec torches et musique en l'honneur de Bacchus ou quelque autre divinité, et chantaient et jouaient devant les maisons de leurs amis, hommes ou femmes; de là, le mot est utilisé pour les fêtes et beuveries de nuit, qui se terminaient en orgies</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κῶμος, ου (ὁ) :<br>   I</b> fête dorienne avec chants et danses en l’honneur de Dionysos, DÉM. <i>517 fin (loi</i>) ;<br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> fête avec chants et danses dans les rues, <i>en l’honneur d’un vainqueur ou de l’anniversaire d’une victoire aux quatre grands jeux helléniques,</i> PD. <i>O. 4, 15 ; P. 5, 28, etc. ;</i><br><b>      2</b> partie de plaisir où les invités parcouraient les rues, après une fête <i>ou</i> un festin, avec de la musique, des chants et des danses, AR. <i>Pl. 1040 ;</i> PLAT. <i>Theæt. 173</i> d ;<br><b>      3</b> <i>p. ext</i>. troupe impétueuse, <i>en parl. des Érinyes,</i> ESCHL. <i>Ag. 1189 ; d’une armée,</i> EUR. <i>Ph. 791, Suppl. 390 ; d’une troupe de jeunes gens,</i> EUR. <i>Tr. 1184 ; de tourterelles,</i> EUR. <i>Ion 1197 ;</i><br><b>   III</b> <i>p. ext</i>. festin, banquet, fête, HH. <i>Merc. 481 ;</i> HDT. <i>1, 121 ;</i> XÉN. <i>Conv. 2, 1</i>.<br><span><b>Étym</b>. <i>Orig. incert., p.-ê. R. indo-europ</i>. *ḱomso-, éloge <i>ou pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κωμος - κῶμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2971":"<h1>konops</h1>\n<p>Strong n° 2971 <i>Prononciation [ko'-nopes]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un moucheron de la vigne utile pour la fermentation du vin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κώνωψ, ωπος (ὁ)</b> cousin, <i>insecte,</i> ESCHL. <i>Ag. 893 ;</i> HDT. <i>2, 95 ;</i> ARSTT. <i>H.A. 4, 7 et 8, etc</i>.<br><span><b>Étym</b>. <i>probabl. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κωμωψ - κώνωψ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2972":"<h1>Kos</h1>\n<p>Strong n° 2972 <i>Prononciation [koce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Cos (Angl. Coos) = « prison publique »\n<ol><li>petite île de la Mer Egée, proche des villes de Cnide et d'Halicarnasse, entre Milet et Rhodes. Elle a 34 km de long sur 9 de large, célèbre pour sa fertilité et l'abondance de ses vins et céréales</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κῶς</b>, <i>gén</i>. <b>Κῶ</b>, <i>dat</i>. <b>Κῷ</b>, <i>acc</i>. <b>Κῶν</b> <i>ou</i> <b>Κῶ (ἡ)</b> l’î. de Kôs (<i>auj</i>. Kos, <i>anc</i>. Stanchio) HDT. <i>1, 144 ;</i> THC. <i>8, 41, 108, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Acc</i>. Κῶν, IL. <i>2, 677 ; ou</i> Κῶ, XÉN. <i>Hell. 1, 5, 1 ;</i> POL. <i>16, 15, 4, etc. Épq</i>. Κόως, HH. <i>Ap. 42</i>.<br><span><b>Étym</b>. <i>cf</i>. Κώϊος, Κῷος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κως - Κῶς</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2973":"<h1>Kosam</h1>\n<p>Strong n° 2973 <i>Prononciation [ko-sam']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Kosam (Angl. Cosam) = « celui qui devine »\n<ol><li>un ancêtre de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κωσαμ</font> &lt; קוסם - <font face=\"Georgia\">Κωσάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2974":"<h1>kophos</h1>\n<p>Strong n° 2974 <i>Prononciation [ko-fos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>émoussé, stupide, ennuyeux, obtus\n<ol type=\"a\">\n<li>émoussé ou défectueux de la langue, muet</li>\n<li>ayant des difficultés pour entendre</li>\n<li>sourd, mal entendant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κωφός, ή, όν :<br>A</b> <i>litt</i>. émoussé : βέλος κωφόν, IL. <i>11, 390,</i> trait émoussé, sans force (<i>p. opp. à</i> ὀξύ) ; γέροντες κ. AR. <i>Ach. 681,</i> vieillards dont les sens sont émoussés ; γαῖα κ. IL. <i>24, 54,</i> la terre insensible ;<br><b>B</b> <i>p. suite :</i><br><b>   I</b> silencieux, qui résonne sourdement : κύματι κωφῷ, IL. <i>14, 16,</i> vague silencieuse (avant qu’elle ne se brise) ; <i>en parl. de pers</i>. muet, ORACL. (HDT. <i>1, 47) ; en parl. de</i> personnages muets (sur la scène) PLUT. <i>M. 337</i> e, <i>791</i> e ; <i>particul</i>. muet de stupeur, LUC. <i>Demon. 1 ; fig. en parl. de sentiments :</i> κ. λήθη, SOPH. <i>fr. 595,</i> l’oubli silencieux ;<br><b>   II</b> sourd, <i>en parl. de pers</i>. HH. <i>Merc. 92 ;</i> ESCHL. <i>Sept. 202 ;</i> PLAT. <i>Leg. 932</i> a, <i>etc. ; en parl. de l’ouïe elle-même,</i> ANTIPH. (ATH. <i>450</i> f) ; <i>avec un gén</i>. κ. τῶν λεγομένων, HPC. <i>121, 30,</i> qui entend mal <i>ou</i> n’entend pas ce qu’on dit ;<br><b>   III</b> <i>p.-ê</i>. sourd et muet, HDT. <i>1, 34 (en parl. d’un des fils de Crésus qualifié</i> κωφός, <i>1, 34,</i> ἄφωνος, <i>1, 85 et</i> διεφθαρμένος τὴν ἀκοήν, <i>1, 38</i>) ;<br><b>   IV</b> qui a la vue faible, ARSTT. <i>Physiogn. 3, 4 ;</i><br><b>   V</b> faible d’esprit, inintelligent, sot, stupide ; PLAT. <i>Tim. 75</i> e ; ὁ πάντα κ., ὁ πάντ' ἄϊδρις, SOPH. <i>Aj. 911,</i> qui ne comprend rien, qui ne connaît rien ;<br><b>   VI</b> <i>en parl. de ch.,</i> sans valeur, <i>càd. :</i><br><b>      1</b> sans fondement, SOPH. <i>O.R. 290 ;</i><br><b>      2</b> sans consistance ni durée, DC. <i>38, 27 ;</i><br><b>      3</b> qui n’a pas de sens : κ. σκῶμμα, PLUT. <i>M. 712</i> a, raillerie insignifiante ;<br><b>      4</b> difficile à comprendre, inintelligible, obscur, POL. <i>3, 36, 4 ;</i> PLUT. <i>M. 712</i> a.<br><span>•<i> Cp</i>. -ότερος, PARŒM. ; <i>sup</i>. -ότατος, PLUT. <i>M. 721</i> e.<br><span><b>Étym</b>. <i>Orig. incert., indo-europ. ou pré-grec ; cf</i>. κηφήν, κεκαφηώς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κωφος - κωφός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 12 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (3)</li>\n<li>Luc (4)</li>\n</ul>\n</td></tr>\n</table>","G2975":"<h1>lagchano</h1>\n<p>Strong n° 2975 <i>Prononciation [lang-khan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>obtenir par tirage au sort\n<ol type=\"a\">\n<li>recevoir par un partage divin, obtenir</li>\n</ol>\n</li>\n<li>tirer au sort, déterminer par tirage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαγχάνω</b> <span>(<i>f</i>. λήξομαι, <i>ao</i>. ἔλαχον <span>[ᾰ]</span>, <i>pf</i>. εἴληχα ; <i>pass. ao</i>. ἐλήχθην, <i>pf</i>. εἴληγμαι)</span><br><b>A <i>tr</i>.<br>   I</b> obtenir par le sort <i>ou</i> par la volonté des dieux (<i>p. opp. à</i> ἐξαιρεῖσθαι, OD. <i>14, 233</i>) ; τι, HOM. ATT. ; <i>d’où en gén</i>. obtenir en partage, <i>et, p. suite, à l’ao. et au pf.,</i> avoir en partage : γέρας, IL. <i>4, 49,</i> un honneur ; <i>à l’ao. et au pf. en parl. d’une divinité à laquelle est échue la tutelle d’une personne ou d’un pays :</i> ἐμὲ Κὴρ ἥ περ λάχε γεινόμενον, IL. <i>23, 79,</i> le destin qui me reçut à ma naissance ; <i>cf</i>. THCR. <i>Idyl. 4, 40 ;</i> POÈT. (ALCIPHR. <i>3, 49</i>) ; (Πὰν) πάντα λόφον λέλογχε, HH. <i>18, 6,</i> à Pan est échue toute colline ; Ἀθηνᾶ ἣ τὴν ὑμετέραν πόλιν ἔλαχε, PLAT. <i>Tim. 23</i> d, Athèna à qui échut la protection de votre ville ; <i>avec un dat. déterminat</i>. κλήρῳ λαχεῖν, IL. <i>24, 400, ou</i> πάλῳ λαχεῖν, HDT. <i>4, 94 ;</i> ESCHL. <i>Sept. 55, etc</i>. avoir obtenu par le sort, avoir en partage ;<br><b>   II</b> <i>particul</i>. obtenir par le sort un poste, une charge, <i>etc.,</i> être désigné par le sort pour qqe ch. :<br><b>      1</b> pour occuper un poste : πρὸς Θύμϐρης ἔλαχον Λύκιοι, IL. <i>10, 430,</i> les Lyciens ont leur poste assigné du côté de Thymbrè ; ἐπὶ, ἐν, πρὸς πύλαις λαχεῖν, ESCHL. <i>Sept. 423, 451, etc</i>. avoir son poste aux portes (de la ville) ; <i>abs</i>. λαχεῖν, HDT. <i>3, 128, etc</i>. avoir un poste assigné ; <i>avec un inf</i>. κλήρῳ λάχον ἐνθάδ' ἕπεσθαι, IL. <i>24, 400,</i> j’ai été désigné par le sort pour venir ici à sa suite ; ἔλαχον πολιὴν ἅλα ναιέμεν, IL. <i>15, 190,</i> j’ai eu pour ma part la blanche mer pour l’habiter ; <i>cf</i>. ESCHL. <i>Eum. 931 ;</i> EUR. <i>Tr. 278 ;</i><br><b>      2</b> <i>à Athènes, en parl. des magistrats désignés par le sort :</i> ἀρχὴν λαχεῖν, AR. <i>Av. 1111,</i> être désigné par le sort pour une charge (<i>p. opp. à</i> χειροτονηθῆναι) ; οὐδεμίαν λαχὼν οὐδὲ χειροτονηθείς, ESCHN. <i>15, 11,</i> n’ayant exercé ni par désignation au sort ni par élection aucune charge ; ὁ κυάμῳ λαχών, AR. <i>Av. 1022,</i> le magistrat désigné par la fève (<i>v</i>. κύαμος) ; <i>avec l’inf</i>. ὁ λαχὼν πολεμαρχέειν, HDT. <i>6, 109,</i> celui qui fut désigné par le sort comme polémarque ; λαχόντος βουλεύειν, DÉM. <i>551, 2,</i> quand je devins par la désignation au sort membre du sénat ; <i>abs</i>. οἱ λαχόντες βουλευταί, LYS. <i>103, 30,</i> les sénateurs désignés par le sort ; ὁ λαχὼν βασιλεύς, DÉM. <i>1369, 16,</i> l’archonte-roi désigné par le sort, <i>etc. ;</i><br><b>      3</b> <i>t. de droit att</i>. λαγχάνειν δίκην, obtenir le droit d’intenter des poursuites (parce que les causes étaient entendues selon l’ordre assigné par un tirage au sort) : τινί, PLAT. <i>Euthyphr. 5</i> b, <i>Leg. 938</i> b ; πρός τινα, LYS. <i>149, 3,</i> contre qqn ; <i>avec le gén. du grief :</i> τοῦ κλήρου τὴν δίκην λ. IS. <i>68, 44,</i> intenter un procès pour un héritage ; <i>ou sans</i> δίκην : λ. τινὶ φόνου, DÉM. <i>554, 5,</i> intenter un procès à qqn pour meurtre ; <i>le n. de la juridiction avec</i> εἰς <i>ou</i> πρός <i>et l’acc. :</i> λ. δίκην τινὶ εἰς τοὺς Ἀμφικτύονας χιλίων ταλάντων ὑπέρ τινος, DÉM. <i>1378, 11,</i> poursuivre qqn devant les Amphictions en paiement d’une amende de mille talents ; λαγχάνειν πρὸς τὸν ἄρχοντα, IS. <i>87, 18,</i> intenter des poursuites devant l’archonte ; <i>au pass</i>. πρὸ τοῦ τὴν δίκην ληχθῆναι, DÉM. <i>1265, 23,</i> avant que l’affaire eût été introduite ; <i>cf</i>. LYS. <i>149, 2 ;</i><br><b>      4</b> <i>avec le gén. :</i> obtenir une part de, obtenir, recevoir : ὥς κεν Ἀχιλλεὺς δώρων ἐκ Πριάμοιο λάχῃ, IL. <i>24, 76,</i> afin qu’Achille reçoive des présents de Priam ; τῆς εὐπρεπεστάτης τελευτῆς λαχεῖν, THC. <i>2, 44,</i> obtenir la fin la plus glorieuse ; <i>cf</i>. OD. <i>5, 311 ;</i> HDT. <i>3, 130 ;</i> XÉN. <i>An. 3, 1, 11, etc. ;</i> LUC. <i>Cyn. 9 ;</i><br><b>   III</b> tirer au sort, ISOCR. <i>144</i> b ; περί τινος, NT. <i>Joh. 19, 24,</i> au sujet de qqe ch. ;<br><b>   IV</b> (<i>à l’ao.2 épq</i>. λέλαχον <span>[ᾰ]</span>) faire obtenir, accorder ; πυρὸς θανόντα, IL. <i>7, 80 ; 22, 343, etc</i>. faire obtenir, <i>càd</i>. accorder, rendre à un mort les honneurs du bûcher ; <i>cf. cet ao. intr</i>. ANTH. <i>7, 341 ;</i><br><b>B <i>intr.</i></b> tomber au sort, tomber en partage à qqn : ἐς ἑκάστην (νῆα) ἐννέα λάγχανον αἶγες, OD. <i>9, 160,</i> un lot de neuf chèvres était assigné à chaque navire ; τὸ λαχὸν μέρος, PLAT. <i>Leg. 745</i> e, la part échue ; <i>avec le dat. :</i> Θετταλίαν λαχεῖν Δευκαλίωνι, STR. <i>443,</i> la Thessalie échut à Deucalion.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. poét</i>. λάγχανον, OD. <i>9, 160. Fut. ion</i>. λάξομαι, HDT. <i>7, 144. Ao.2 poét</i>. ἔλλαχον, HH. <i>5, 87 ;</i> THCR. <i>Idyl. 25, 271 ; épq</i>. λάχον, IL. <i>23, 862 ; 24, 400, etc. ; sbj. 3 sg</i>. λάχῃσιν, IL. <i>7, 171 ; part. fém. dor</i>. λαχοῖσα, PD. <i>O. 14, 1. — Ao.2 subj. et opt. avec redoubl. 2 pl</i>. λελάχητε, IL. <i>23, 76 ; 3 pl</i>. λελάχωσι, IL. <i>15, 350 ; 22, 343 ; opt. 3 sg</i>. λελάχοι, ANTH. <i>7, 341. — Pf. poét</i>. λέλογχα, OD. <i>11, 304 ;</i> HÉS. <i>Th. 203 ;</i> PD. <i>N. 1, 24 ;</i> EUR. <i>Tr. 282 ;</i> HDT. <i>7, 53, etc., d’où pl.q.pf</i>. ἐλελόγχειν, LUC. <i>Am. 18 ; poét</i>. λελόγχειν, THCR. <i>Idyl. 4, 40. — Autre pf</i>. λέλαχα <span>[λᾰ]</span> <i>d’où 3 pl</i>. λελάχασι <span>[χᾱ]</span> EMPÉD. <i>373 Stein. — Pass. pf. 3 pl</i>. λελάχαται, PÉRICT. (STOB. <i>85, 19</i>).<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *leng<sup>h</sup>-, obtenir <i>par le sort</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαγχανω - λαγχάνω</font>\n<br><br>forme d'un verbe primaire utilisé seulement en variante à certains temps</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>2 Pierre (1)</li>\n</li>\n</ul>\n</td></tr>\n</table>","G2976":"<h1>Lazaros</h1>\n<p>Strong n° 2976 <i>Prononciation [lad'-zar-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lazare (Angl. Lazarus) = « Dieu a secouru » (forme du nom Hébreu El'azar)\n<ol>\n<li>un habitant de Béthanie, aimé du Christ et ressuscité de la mort</li>\n<li>un personnage très pauvre à qui Jésus se réfère dans <a class=\"ref\" data-r=\"LUK16.20-25\">Luc 16.20-25</a></li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λαζαρος</font> &lt; לעזר - <font face=\"Georgia\">Λάζαρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (4)</li>\n<li>Jean (11)</li>\n</ul>\n</td></tr>\n</table>","G2977":"<h1>lathra</h1>\n<p>Strong n° 2977 <i>Prononciation [lath'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>secrètement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λάθρᾳ</b>, <i>ion</i>. <b>λάθρῃ</b> <span>[αᾱ]</span> <i>en prose att. mieux que</i> λάθρα, λάθρη, <i>adv. et prép. :</i><br><b>      1</b> secrètement, en cachette, IL. <i>2, 515 ;</i> OD. <i>15, 430 ;</i> SOPH. <i>O.R. 618 ;</i> XÉN. <i>Hell. 2, 4, 35 ;</i> τινός, IL. <i>5, 269 ;</i> HDT. <i>8, 112 ;</i> SOPH. <i>O.R. 787 ;</i> EUR. <i>Andr. 310 ;</i> XÉN. <i>An. 1, 3, 8,</i> à l’insu de qqn ;<br><b>      2</b> par surprise, traîtreusement, OD. <i>17, 80 ;</i><br><b>      3</b> <i>p. suite,</i> insensiblement, peu à peu, IL. <i>19, 165</i>.<br><span><b><span class=\"arrow\"></span></b> λάθρα <span>[ρᾰ]</span> HH. <i>Cer. 241</i>.<br><span><b>Étym</b>. λαθεῖν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαθρα - λάθρᾳ</font></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2978":"<h1>lailaps</h1>\n<p>Strong n° 2978 <i>Prononciation [lah'-ee-laps]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un tourbillon de vent, un vent de tempête</li>\n<li>une violente poussée de vent, une rafale\n<ol type=\"a\">\n<li>jamais une simple rafale ni même un vent soutenu, et cependant violent, mais une tempête qui brise tout, avec de gros nuages noirs d'orage, des flots de pluie, un vent qui renverse tout, ouragan</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαῖλαψ, απος (ἡ)</b> <span>[ᾰπ]</span> tourbillon de vent avec pluie, ouragan, tempête (<i>sel</i>. ARSTT. <i>Mund. 4, 16,</i> trombe de bas en haut) IL. <i>11, 306, 747 ; 12, 375, etc. ;</i> OD. <i>12, 408 ;</i> ESCHL. <i>Suppl. 34, etc. ; en prose,</i> POL. <i>30, 14, 6 ;</i> SPT. <i>Job 21, 18 ;</i> NT. <i>Marc. 4, 37 ; Luc. 8, 23 ;</i> PLUT. <i>Tim. 28, etc. ; fig</i>. ANTH. <i>7, 147</i>.<br><span><b>Étym</b>. <i>probabl. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαιλαψ - λαῖλαψ</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2979":"<h1>laktizo</h1>\n<p>Strong n° 2979 <i>Prononciation [lak-tid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>donner un coup de pied, frapper avec le talon, faire une ruade, se rebeller</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λακτίζω</b> <span>(<i>f</i>. ίσω, <i>att</i>. ιῶ, <i>ao</i>. ἐλάκτισα, <i>pf</i>. λελάκτικα)</span><br><b>      1</b> frapper du talon <i>ou</i> du pied, ruer : ποτὶ κέντρον, PD. <i>P. 2, 95 ;</i> πρὸς κέντρα, ESCHL. <i>Ag. 1624 ;</i> EUR. <i>Bacch. 794,</i> ruer contre l’aiguillon ; <i>fig</i>. πρὸς κῦμα, EUR. <i>I.T. 1396,</i> lutter contre le flot ;<br><b>      2</b> frapper du pied : λ. ποσὶ γαῖαν, OD. <i>18, 99,</i> frapper du pied la terre ; <i>en parl. de chevaux,</i> piaffer, XÉN. <i>Hipp. 1, 4 ;</i> ὑπὸ ἵππου λακτισθείς, XÉN. <i>An. 3, 2, 18,</i> frappé d’un coup de pied de cheval ; λ. θύραν, AR. <i>Nub. 136,</i> donner des coups de pied dans la porte ; <i>fig</i>. φλὸξ αἰθέρα λακτίζοισα καπνῷ, PD. <i>I. 3, 84,</i> flamme qui lance de la fumée vers le ciel ; κραδία φόϐῳ φρένα λακτίζει, ESCHL. <i>Pr. 881,</i> mon cœur bat de frayeur contre l’enveloppe qui l’enserre ; <i>avec idée de mépris :</i> τὰ πεσόντα λακτίσαι, ESCHL. <i>Ag. 885,</i> fouler aux pieds celui qui est renversé ; Δίκας βωμὸν εἰς ἀφάνειαν, ESCHL. <i>Ag. 383,</i> fouler aux pieds l’autel de la Justice ; ἀτίμως λακτιζόμενος, LUC. <i>Tim. 17,</i> foulé aux pieds avec ignominie.<br><span><b>Étym</b>. λάξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λακτιζω - λακτίζω</font>\n<br><br>vient de l'adverbe 'lax' (talon)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2980":"<h1>laleo</h1>\n<p>Strong n° 2980 <i>Prononciation [lal-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire entendre une voix, émettre un son</li>\n<li>parler\n<ol type=\"a\">\n<li>utiliser la langue ou la faculté de parole</li>\n<li>émettre des sons articulés</li>\n</ol>\n</li>\n<li>discourir</li>\n<li>prononcer, dire</li>\n<li>utiliser des mots pour décrire et découvrir ses pensées\n<ol type=\"a\">\n<li>parler, raconter</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαλέω-ῶ</b> <span>[ᾰ]</span><br><b>   I</b> <i>propr</i>. prononcer des sons inarticulés :<br><b>      1</b> <i>en parl. d’animaux, des singes et des chiens, p. opp. à</i> φράζειν (λαλοῦσι μέν, φράζουσι δὲ οὔ, PLUT. <i>M. 909</i> a) ; <i>des cigales,</i> THCR. <i>Idyl. 5, 34 ; des oiseaux,</i> MOSCH. <i>3, 47 ;</i><br><b>      2</b> <i>en parl. de sons :</i> ἐν αὐλῷ λ. THCR. <i>Idyl. 20, 29 ;</i> δι' αὐλοῦ ἢ σάλπιγγος λ. ARSTT. <i>Aud. 19 ;</i> μαγάδι (<i>var</i>. -ιν) λ. ANAXANDR. (ATH. <i>182</i> d) faire entendre des sons avec la flûte, la flûte ou la trompette, la harpe ;<br><b>      3</b> <i>en parl. de bruits ou de paroles répercutés,</i> DC. <i>74, 21 ;</i><br><b>   II</b> <i>p. suite,</i> babiller, bavarder, <i>p. opp. à</i> λέγειν, EUP. (PLUT. <i>Alc. 13</i>) ; λαλεῖς ἀμελήσας ἀποκρίνεσθαι, PLAT. <i>Euthyd. 287</i> d, tu parles beaucoup et tu négliges de répondre ;<br><b>   III</b> <i>p. ext</i>. parler :<br><b>      1</b> <i>en gén. c</i>. λέγειν, <i>en parl. de l’homme, p. opp. aux animaux,</i> ARSTT. <i>Probl. 11, 1 ; abs</i>. ἐλάλησεν ὁ κωφός, NT. <i>Matth. 9, 33,</i> le muet parla ; λ. τι, SOPH. <i>Ph. 110 ;</i> AR. <i>Ran. 761, etc. ;</i> PLAT. <i>Ax. 366</i> d ; LUC. <i>V. auct. 3,</i> dire qqe ch. ; λ. πρός τινα, SPT. <i>Ex. 4, 30,</i> parler à qqn ; τινι, AR. <i>Eq. 348,</i> converser avec qqn ; περί τινος, AR. <i>Lys. 627 ;</i> PHÉRÉCR. (<i>Com. fr. 2, 253</i>) ; ὑπέρ τινος, POSIDIPP. <i>4, 521 Mein</i>. sur qqe ch. ; <i>avec double rég</i>. τί τινι, AR. <i>Lys. 138,</i> dire qqe ch. à qqn ; <i>fig</i>. ζωγραφία λαλοῦσα, SIM. (PLUT. <i>M. 346</i> f) peinture parlante, <i>en parl. de la poésie, p. opp. à</i> ποίησις σιωπῶσα, <i>càd</i>. la peinture ;<br><b>      2</b> chanter, MOSCH. <i>3, 113</i>.<br><span><b>Étym</b>. λάλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαλεω - λαλέω</font>\n<br><br>forme prolongée d'un verbe par ailleurs désuet</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n294 fois dans 269 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (26)</li>\n<li>Marc (19)</li>\n<li>Luc (30)</li>\n<li>Jean (59)</li>\n<li>Actes (60)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (33)</li>\n<li>2 Corinthiens (10)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (4)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (2)</li>\n<li>Hébreux (17)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (1)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (12)</li>\n</ul>\n</td></tr>\n</table>","G2981":"<h1>lalia</h1>\n<p>Strong n° 2981 <i>Prononciation [lal-ee-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>discours, c.à.d une histoire</li>\n<li>dialecte, mode de langage, prononciation\n<ol type=\"a\">\n<li>paroles qui font découvrir la contrée natale de celui qui parle</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαλιά, ᾶς (ἡ)</b> <span>[λᾰ]</span><br><b>   I</b> babil, bavardage, AR. <i>Nub. 931, etc. ;</i> ESCHN. <i>34, 29 ; d’où :</i><br><b>      1</b> habitude de bavarder, loquacité, PLAT. <i>Def. 416 ;</i> TH. <i>Char. 7 ;</i> SPT. <i>Sir. 19, 5 ;</i> PLUT. <i>M. 715</i> a, <i>etc. ;</i><br><b>      2</b> bruit, rumeur, POL. <i>3, 20, 5, etc. ; d’où</i> réputation, renommée, SPT. <i>2Macc. 8, 5 ;</i><br><b>   II</b> <i>p. ext</i>. parole, <i>d’où :</i><br><b>      1</b> entretien, conversation, ARÉT. <i>p. 73 ;</i> PLUT. <i>Pyrrh. 5 ;</i><br><b>      2</b> discussion littéraire, POL. <i>32, 9, 4 ;</i><br><b>      3</b> façon de parler, dialecte, NT. <i>Matth. 26, 73 ;</i><br><b>      4</b> prononciation, DL. <i>4, 33</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ιή, HERMÉSIAN. (ATH. <i>598</i> f).<br><span><b>Étym</b>. λάλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαλια - λαλιά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2982":"<h1>lama</h1>\n<p>Strong n° 2982 <i>Prononciation [lam-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pourquoi ? pour quelle raison ?</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαμα</font> &lt; למה - <font face=\"Georgia\">λεμά</font>\n<br><br>mot repris de l'Araméen</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2983":"<h1>lambano</h1>\n<p>Strong n° 2983 <i>Prononciation [lam-ban'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre\n<ol type=\"a\">\n<li>prendre avec la main, saisir, une personne ou une chose pour l'emmener\n<ol>\n<li>prendre une chose pour la transporter</li>\n<li>prendre sur soi-même</li>\n</ol>\n</li>\n<li>prendre sans notion de violence, déplacer, emporter</li>\n<li>prendre ce qui est à soi, s'approprier\n<ol>\n<li>réclamer, se procurer, prétendre à\n<ol type=\"a\">\n<li>s'associer un compagnon, un serviteur</li>\n</ol>\n</li>\n<li>de ce qui est pris et non laissé, saisir, appréhender</li>\n<li>prendre avec habileté (pêche, chasse, ...), circonvenir par la fraude</li>\n<li>lutter pour obtenir</li>\n<li>prendre un dû, collecter, percevoir (un tribut)</li>\n</ol>\n</li>\n<li>admettre, recevoir\n<ol>\n<li>recevoir ce qui est offert</li>\n<li>ne pas rejeter ou refuser</li>\n<li>recevoir une personne, lui permettre une rencontre\n<ol type=\"a\">\n<li>considérer le pouvoir, le rang, les circonstances extérieures, et par là commettre une injustice ou une négligence</li>\n</ol>\n</li>\n</ol>\n<li>choisir, sélectionner</li>\n<li>prouver quelque chose, faire un contrôle, expérimenter</li>\n</li>\n</ol>\n</li>\n<li>recevoir (ce qui est donné), gagner, obtenir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαμϐάνω</b> <span>(<i>f</i>. λήψομαι, <i>ao.2</i> ἔλαϐον, <i>pf</i>. εἴληφα ; <i>pass. f</i>. ληφθήσομαι, <i>ao</i>. ἐλήφθην, <i>pf</i>. εἴλημμαι)</span><br><b>   I</b> prendre :<br><b>      1</b> prendre dans ses mains, saisir : λ. μάστιγα καὶ ἡνία, OD. <i>6, 81,</i> prendre son fouet et les rênes ; χειρὶ λ. IL. <i>21, 286,</i> prendre avec la main ; ἐν χείρεσσι λ. IL. <i>8, 116,</i> prendre dans ses mains <i>ou</i> dans ses bras ; <i>en parl. de suppliants :</i> λ. γούνατα, IL. <i>24, 465,</i> prendre les genoux (de qqn) ; <i>le nom de la partie par laquelle on saisit qqn se met au gén. :</i> τινὰ ποδῶν λ. IL. <i>4, 463,</i> saisir qqn par les pieds ; τὴν πτέρυγος λάϐεν, IL. <i>2, 316,</i> il le saisit (le passereau) par l’aile ; ἔλαϐον τῆς ζώνης τὸν Ὀρόνταν, XÉN. <i>An. 1, 6, 10,</i> ils saisirent Orontas par la ceinture ; <i>en ce sens, au part. joint à un verbe :</i> λαϐὼν κύσε χεῖρα, OD. <i>24, 398,</i> il lui prit la main et la baisa ; <i>avec idée de violence,</i> s’emparer de (d’un butin, de chevaux, IL. <i>5, 273 ; 10, 545 ;</i> de troupeaux, OD. <i>11, 4 ;</i> de personnes et de choses, OD. <i>9, 41, etc. ;</i> HDT. <i>4, 130, etc. ;</i> SOPH. <i>Ph. 68, etc.) ; en parl. d’animaux qui saisissent leur proie (lions,</i> IL. <i>11, 114 ; 17, 63 ; aigle,</i> IL. <i>17, 678 ; dauphin,</i> IL. <i>21, 24) ; en parl. de prise de guerre,</i> IL. <i>5, 159 ; 11, 126, etc. ;</i> ζῶντες ἐλάμφθησαν, HDT. <i>9, 119,</i> ils furent pris vivants ; λ. πόλιν, THC. <i>4, 69, etc. ;</i> Σικελίαν, THC. <i>6, 15,</i> s’emparer d’une ville, de la Sicile ; λ. αἰχμαλώτους, THC. <i>3, 32,</i> faire des prisonniers ; <i>fig</i>. λ. τινὰ πίστι καὶ ὁρκίοισι, HDT. <i>3, 74,</i> lier qqn par une promesse et des serments ; ἀραῖον λ. τινά, SOPH. <i>O.R. 276,</i> contraindre qqn par des imprécations ; <i>avec un suj. de chose et un rég. de pers</i>. Ἀτρεΐωνα χόλος λάϐε, IL. <i>1, 387,</i> la colère s’empara du fils d’Atrée ; <i>de même en parl. de la douleur, de la confiance, de la crainte, etc</i>. OD. <i>4, 704, etc. ;</i> THC. <i>2, 29, etc. ;</i> XÉN. <i>Cyr. 5, 5, 6, etc. ; en parl. de maladie,</i> THC. <i>2, 49 ;</i> AR. <i>Eccl. 417 ;</i> HPC. <i>453 fin ; d’où au pass</i>. λαμϐάνεσθαι νόσῳ, SOPH. <i>Tr. 446 ;</i> ὑπὸ νόσου, HDT. <i>1, 138,</i> être pris par la maladie ; <i>en parl. de la passion :</i> λαμϐάνεσθαι ἔρωτι, XÉN. <i>Cyr. 6, 1, 31,</i> être pris par l’amour ; <i>avec un suj. de chose et un rég. de chose :</i> τρόμος ἔλλαϐε γυῖα, IL. <i>8, 452,</i> un tremblement avait saisi vos membres ; μένος ἔλλαϐε θυμόν, IL. <i>23, 468,</i> la fureur s’est emparée de leur cœur ; κνέφας λαμϐάνει τέμενος αἰθέρος, ESCHL. <i>Pers. 365,</i> l’obscurité envahit la voûte du ciel ; <i>cf</i>. IL. <i>4, 230 ; 24, 170, etc. ;</i><br><b>      2</b> prendre, découvrir : τὸν αὐτόχειρα τοῦ φόνου, SOPH. <i>O.R. 266,</i> l’auteur du meurtre ; <i>avec un part</i>. prendre à l’improviste, surprendre : λ. τινὰ ψευδόμενον, PLAT. <i>Rsp. 389</i> c, prendre qqn. à mentir ; κλέπτοντά τινα λ. AR. <i>Vesp. 759,</i> prendre qqn en flagrant délit de vol ; <i>au pass</i>. δρῶσ' ἐλήφθης, SOPH. <i>Tr. 808,</i> on t’a prise sur le fait ; ἐπ' αὐτοφώρῳ δεινὰ δρῶν εἰλημμένος, AR. <i>Pl. 455,</i> pris sur le fait à faire de vilaines choses ; <i>avec un adj</i>. μοιχὸς ἐλήφθη, LYS. <i>136, 3,</i> on l’a pris en flagrant délit d’adultère ;<br><b>      3</b> <i>p. suite,</i> saisir fortuitement, <i>càd</i>. trouver, rencontrer : λ. τινά, HDT. <i>1, 116 ;</i> SOPH. <i>O.R. 1031 ;</i> EUR. <i>Ion 1339,</i> qqn ;<br><b>      4</b> prendre sur soi : Ἑλληνίδα ἐσθῆτα, HDT. <i>4, 78,</i> prendre le costume grec ;<br><b>      5</b> prendre avec soi, amener <i>ou</i> emmener : ξυμπαραστάτην λ. τινά, SOPH. <i>Ph. 675,</i> prendre qqn comme assistant, comme secours ; <i>en ce sens au part. :</i> ἑτάρους τε λαϐὼν καὶ νῆα ἦλθον, OD. <i>15, 269,</i> j’ai pris avec moi des compagnons et un vaisseau et je suis parti ; ἔταξε Γλοῦν καὶ Πίγρητα λαϐόντας τοῦ βαρϐαρικοῦ στρατοῦ συνεκϐιϐάζειν τὰς ἁμάξας, XÉN. <i>An. 1, 5, 7,</i> il donna ordre à Glous et à Pigrès de prendre avec eux un détachement de barbares et d’aider à dégager les chariots ;<br><b>      6</b> prendre en échange : λ. δίκην <i>ou</i> ποινάς, LYS. <i>94, 27, etc. ;</i> EUR. <i>Tr. 360, etc. ;</i> λ. ζημίαν <i>ou</i> τιμωρίαν, DÉM. <i>155, 12 ; 319, 12, litt</i>. prendre le châtiment (en échange de la faute), <i>càd</i>. châtier, punir ; <i>rar. au sens de</i> δοῦναι δίκην (<i>v. ci-dessous</i> II, 3) ;<br><b>      7</b> prendre possession de, occuper : <i>en parl. de la divinité,</i> s’emparer de, posséder, <i>avec un rég. de pers</i>. λ. τινά, HDT. <i>4, 79,</i> posséder qqn ; <i>au pass</i>. être possédé d’un dieu, d’une déesse, LUC. <i>Nigr. 37 ;</i><br><b>      8</b> <i>fig</i>. atteindre par les sens <i>ou</i> par l’intelligence : λ. θέαν ὄμμασιν, SOPH. <i>Ph. 537 ;</i> voir un spectacle de ses yeux ; <i>en gén</i>. saisir par les sens, PLAT. <i>Rsp. 524</i> d ; λ. νόῳ, HDT. <i>3, 51 ;</i> τῇ διανοίᾳ, PLAT. <i>Parm. 143</i> a ; <i>ou avec une prép</i>. λ. ἐν τῇ γνώμῃ, XÉN. <i>Cyr. 3, 3, 51 ;</i> ἐν νῷ, POL. <i>2, 35, 5,</i> atteindre par l’intelligence, saisir dans son esprit, <i>d’où</i> juger, apprécier : τὴν ξυμμέτρησιν τῶν κλιμάκων, THC. <i>3, 20,</i> prendre la mesure correspondante des échelles ; τὸ μέγεθος τῶν ἁμαρτημάτων, LYCURG. <i>156, 15,</i> apprécier la grandeur des fautes ; <i>avec un attribut :</i> τὴν τιμωρίαν ποθεινοτέραν λ. THC. <i>2, 42,</i> juger plus désirable la vengeance ; τὸν ἄνθρωπον ἢ θνητὸν ἢ ἀθάνατον δεῖ λ. ARSTT. <i>An. pr. 1, 31, 3,</i> il faut admettre que l’homme est mortel ou immortel ; <i>p. suite,</i> prendre en tel ou tel sens, comprendre de telle ou telle façon : ταύτῃ ταῦτα ἐλάμϐανον, HDT. <i>7, 142,</i> c’est ainsi qu’ils expliquaient ces événements ; λ. τοὺς λόγους μὴ πολεμίως, THC. <i>4, 17,</i> accueillir les paroles non en ennemi ; <i>avec une prép</i>. λ. περί τινος τί ἐστιν, ARSTT. <i>Nic. 6, 9, 1,</i> se rendre compte de ce qu’est une chose ; <i>ou avec une prop. inf</i>. λ. τι εἶναί τι, ARSTT. <i>Meteor. 4, 11, 2, m. sign. ; avec une conj</i>. λ. ὅτι, ARSTT. <i>Metaph. 9, 1, 18,</i> comprendre que, <i>etc. ; avec une prép</i>. πρὸς δέος λ. τι, PLUT. <i>Flam. 7,</i> prendre qqe ch. en crainte, <i>càd</i>. s’effrayer de qqe ch. ; λ. πρὸς ἀτιμίαν, PLUT. <i>Cic. 13,</i> prendre qqe ch. comme une injure (<i>litt</i>. comme une cause de déshonneur) ;<br><b>      9</b> <i>abs</i>. parvenir à, atteindre : τὴν ἡλικίαν, ISOCR. <i>215</i> e, l’âge de qqe ch. ; κλέος, OD. <i>1, 298 ;</i> SOPH. <i>Ph. 1347,</i> gagner de la gloire ; κέρδος, AR. <i>Ach. 906,</i> obtenir un gain ; <i>en mauv. part :</i> λ. αἰτίαν, THC. <i>2, 18, etc</i>. encourir une accusation ; λ. θάνατον, EUR. <i>Hel. 201,</i> gagner la mort :<br><b>      10</b> prendre en soi, contenir, POL. <i>3, 107, 10 ; en parl. d’une femme enceinte,</i> concevoir, HPC. <i>Prorrh. 107, 10 ;</i><br><b>   II</b> recevoir :<br><b>      1</b> <i>propr</i>. prendre des mains de qqn : λ. τι παρά τινος, HDT. <i>8, 10, etc. ;</i> τι πρός τινος, SOPH. <i>El. 12 ;</i> τι ἀπό τινος, XÉN. <i>Mem. 2, 9, 4,</i> recevoir qqe ch. de qqn ; <i>fig</i>. λ. ὄνομα, PLAT. <i>Soph. 267</i> d, recevoir un nom ; <i>avec un suj. de chose :</i> οἰκίαι ἐπάλξεις λαμϐάνουσαι, THC. <i>4, 69,</i> maisons qui reçoivent des créneaux ; <i>fig</i>. recevoir une impression, <i>d’où</i> éprouver un sentiment, une passion, <i>etc. :</i> λ. θυμόν, OD. <i>10, 461,</i> prendre courage ; λ. ὀργήν, EUR. <i>Suppl. 1050</i> = ὀργίζεσθαι, s’irriter ; λ. φόϐον = φοϐεῖσθαι, SOPH. <i>O.C. 729,</i> s’effrayer ; λ. εὔνοιαν, THC. <i>1, 77,</i> concevoir de la bienveillance ; <i>cf</i>. THC. <i>2, 88 ; 4, 34, etc. ;</i><br><b>      2</b> recueillir, retirer : οἶνον ἐκ τοῦ χωρίου, AR. <i>Nub. 1123,</i> du vin du terrain ; μισθὸν ἐκ τῆς ἀρχῆς, PLAT. <i>Rsp. 347</i> b, un salaire d’une charge ;<br><b>      3</b> recevoir en échange : λ. τι δραχμῆς, ὀϐολοῦ, AR. <i>Pax 1263 ; Ran. 1236,</i> acheter qqe ch. une drachme, une obole ; <i>fig</i>. λ. δίκην, HDT. <i>1, 115,</i> être puni (<i>v. ci-dessus</i> I, 6) ; τὴν ἀξίην λ. HDT. <i>7, 39,</i> recevoir le juste châtiment (d’une faute) ;<br><b><i>Moy.</i></b> prendre pour soi, sur soi <i>ou</i> avec soi :<br><b>      1</b> <i>sans idée de violence :</i> λ. σχεδίης, OD. <i>5, 325,</i> saisir un radeau ; τοῦ βωμοῦ, AND. <i>16, 34,</i> mettre la main sur l’autel ; καί μου λαϐόμενος τῆς χειρός, PLAT. <i>Charm. 153</i> b, et m’ayant pris la main ; <i>avec idée d’effort, mais sans violence :</i> λ. ἑαυτοῦ, HLD. <i>2, 24,</i> reprendre ses sens ;<br><b>      2</b> <i>avec idée de violence :</i> λ. τινα, OD. <i>4, 388,</i> se saisir de qqn ; <i>avec un gén</i>. λ. ἀρχῆς, SOPH. <i>O.C. 373,</i> s’emparer du pouvoir ; <i>fig</i>. reprendre, blâmer, <i>gén</i>. PLAT. <i>Leg. 637</i> b ;<br><b>      3</b> prendre possession de, <i>d’où</i> s’engager dans : τῶν ὀρῶν, THC. <i>3, 24,</i> dans les montagnes ; <i>p. suite,</i> parvenir à : Δήλου, THC. <i>8, 80,</i> parvenir à Dèlos, <i>en parl. de navires ; fig</i>. λ. τῆς ἀληθείας, PLAT. <i>Phil. 65</i> b, parvenir à la vérité.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 3 pl. dor</i>. λαμϐάνοντι, EPICH. <i>fr. 25 Ahrens. Impf. 3 pl. réc</i>. ἐλαμϐάνοσαν, SPT. <i>Ezech. 22, 12. Fut. réc. 2 pl</i>. λήψετε, SPT. <i>1Macc. 4, 18 ; autre fut. réc</i>. λήμψομαι, NT. <i>Ap. 1, 8 ; fut. ion</i>. λάμψομαι, HDT. <i>1, 199 ; 9, 108 ; dor</i>. λαψοῦμαι, EPICH. <i>fr. 18 Ahrens ;</i> THCR. <i>Idyl. 1, 4 ; et</i> λαμψοῦμαι, STOB. <i>Ecl. 1, 20. Ao.2 épq</i>. ἔλλαϐον, IL. <i>11, 402 ;</i> OD. <i>18, 88 ;</i> HÉS. <i>Th. 179, etc. ; sbj. 3 sg. poét</i>. λάϐῃσι, IL. <i>21, 24 ; opt. 1 sg</i>. λάϐοιν, EUR. <i>fr. 362, 6 ; part. fém. dor</i>. λαϐοῖσα, CALL. <i>L. Pall. 93. Ao. itér</i>. λάϐεσκον, HÉS. <i>fr. 96 Göttling ;</i> HDT. <i>4, 78 et 130. Dans les inscr. att. pf</i>. εἵληφα, <i>avec esprit rude (v. Meisterh. p. 148, § 68, 1 ; cf. p. 80, § 38, 4). Pf. ion. et dor</i>. λελάϐηκα, HDT. <i>4, 79 ; 8, 122 ;</i> COM. (<i>Com. fr. 2, 570). Pass. ao. dor</i>. ἐλάφθην, ARCHIM. <i>Aren. p. 516, etc. ; ion</i>. ἐλάμφθην, HDT. <i>6, 92 ; 9, 119. Pf. poét</i>. λέλημμαι, ESCHL. <i>Ag. 876 ;</i> SOPH. <i>fr. 794, etc. ; impér. dor. 3 sg</i>. λελάφθω, ARCHIM. <i>Con. et sph. 4, p. 264. Moy. ao.2 inf. avec redoubl</i>. λελαϐέσθαι, OD. <i>4, 388</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *sleh₂g<sup>w</sup>-, prendre, saisir ; <i>cf</i>. λαϐή, λάζομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαμβανω - λαμβάνω</font>\n<br><br>forme prolongée d'un verbe primaire, utilisé seulement comme une variante à certains temps</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n260 fois dans 243 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (56)</li>\n<li>Marc (19)</li>\n<li>Luc (20)</li>\n<li>Jean (46)</li>\n<li>Actes (29)</li>\n<li>Romains (10)</li>\n<li>1 Corinthiens (11)</li>\n<li>2 Corinthiens (6)</li>\n<li>Galates (3)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (17)</li>\n<li>Jacques (6)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (3)</li>\n<li>2 Jean (2)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (23)</li>\n</ul>\n</td></tr>\n</table>","G2984":"<h1>Lamech</h1>\n<p>Strong n° 2984 <i>Prononciation [lam'-ekh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lamech (A.T : Lémec) = « puissant »\n<ol><li>le père de Noé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λαμεχ</font> &lt; למך - <font face=\"Georgia\">Λάμεχ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2985":"<h1>lampas</h1>\n<p>Strong n° 2985 <i>Prononciation [lam-pas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une torche</li>\n<li>une lampe, dont la flamme est maintenue avec de l'huile</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>λαμπάς, άδος (ἡ)</b> <span>[ᾰδ]</span><br><b>   I</b> flambeau, <i>particul</i>. flambeau que les coureurs se passaient l’un à l’autre, <i>d’où</i> course aux flambeaux, HDT. <i>6, 105 ;</i> XÉN. <i>Vect. 4, 52 ;</i> PLAT. <i>Leg. 776</i> b ; λαμπάδα δραμεῖν, AR. <i>Vesp. 1203 ;</i> TH. <i>Char. 27,</i> courir la course aux flambeaux ; λαμπάδι νικᾶν, AND. <i>34, 29,</i> être vainqueur à la course aux flambeaux ; <i>fig</i>. λαμπάδα ζωᾶς δραμεῖν, ANTH. <i>App. 148,</i> courir la course aux flambeaux de la vie, <i>en parl. d’une vie courte, p. opp. à une vie</i> δόλιχος ;<br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> fagot allumé, POL. <i>3, 93, 4 ;</i><br><b>      2</b> flambeau de cire, PLUT. <i>M. 263</i> f ;<br><b>      3</b> lampe, NT. <i>Matth. 25, 1 ;</i><br><b>   III</b> <i>p. anal. :</i><br><b>      1</b> flambeau du soleil, SOPH. <i>Ant. 879 ;</i> EUR. <i>Suppl. 991 ; au plur</i>. rayons du soleil, ESCHL. <i>Ch. 290 ;</i><br><b>      2</b> lumière du jour, EUR. <i>Med. 352 ;</i><br><b>      3</b> <i>au pl</i>. lueurs des éclairs, EUR. <i>Suppl. 1011 ;</i><br><b>      4</b> météore igné, ARSTT. <i>Mund. 4, 24 ;</i> DS. <i>16, 66 ;</i><br><b>      5</b> <i>autre n. de la plante</i> λυχνὶς ἀγρία, DIOSC. <i>Noth. 3, 105</i>.<br><span><b>Étym</b>. λάμπω.</span><br><br>\n➁ <b>λαμπάς, άδος</b> <span>[ᾰδ]</span> <i>adj. f</i>. éclairée, brillante de la lueur des flambeaux, SOPH. <i>O.C. 1049</i>.<br><span><b>Étym</b>. <i>v</i>. λαμπάς¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαμπας - λαμπάς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2986":"<h1>lampros</h1>\n<p>Strong n° 2986 <i>Prononciation [lam-pros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>brillant, d'un blanc éclatant\n<ol type=\"a\">\n<li>limpide</li>\n<li>clair, transparent</li>\n</ol>\n</li>\n<li>splendide, magnifique\n<ol type=\"a\">\n<li>choses splendides : luxe ou élégance de l'habillement ou du style</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαμπρός, ά, όν :<br>   I</b> brillant :<br><b>      1</b> <i>en parl. du soleil,</i> IL. <i>1, 605 ; de la lune,</i> HÉS. <i>Th. 18, 371 ; des astres,</i> IL. <i>22, 30 ; du jour,</i> DH. <i>3, 27 ; de l’éclat des yeux,</i> SOPH. <i>O.R. 1483 ; d’un corps métallique (casque, etc</i>.), IL. <i>13, 132 ; 17, 269 ; particul</i>. brillant de blancheur, <i>en parl. de la peau,</i> HDT. <i>4, 64 ; d’un vêtement,</i> OD. <i>19, 234 ; de la</i> toga candida <i>romaine,</i> POL. <i>10, 5, 1 ;</i><br><b>      2</b> <i>p. anal</i>. brillant de beauté, PLAT. <i>Phædr. 250</i> b ; de jeunesse, THC. <i>6, 54 ;</i> de joie, SOPH. <i>Tr. 379, O.R. 81 ;</i> de vêtements, XÉN. <i>Cyr. 2, 4, 5 ; fig. en parl. du style,</i> AR. <i>Av. 1388 ;</i> ARSTT. <i>Poet. 24, 23 ;</i><br><b>      3</b> <i>p. suite,</i> splendide, magnifique : λ. γάμοι, EVANG. (ATH. <i>644</i> e) noces splendides ; <i>en parl. de pers</i>. qui vit <i>ou</i> agit magnifiquement, ISOCR. <i>38</i> d ; <i>joint à</i> πλούσιος, DÉM. <i>571, 2 ; en parl. d’animaux, particul</i>. d’un cheval qui relève la tête, XÉN. <i>Eq. 11, 1 ;</i><br><b>      4</b> illustre, <i>en parl. de pers</i>. HDT. <i>6, 125 ;</i> THC. <i>1, 138 ;</i> XÉN. <i>Cyn. 1, 13 ;</i> SOPH. <i>Tr. 379 ;</i> EUR. <i>El. 37, etc. ; p. opp. à</i> ἄδοξος, ISOCR. <i>100</i> b ; <i>en parl. de choses (action,</i> HDT. <i>3, 72 ; vie,</i> SOPH. <i>O.C. 1144, etc</i>.) ;<br><b>   II</b> clair, limpide :<br><b>      1</b> <i>en parl. de l’eau,</i> HPC. <i>Aër. 282 ;</i> ESCHL. <i>Eum. 695 ;</i> XÉN. <i>Hell. 5, 3, 19 ; de l’air,</i> HPC. <i>290, 16 ; du ciel,</i> EUR. <i>Med. 829 ; p. anal. en parl. de la voix, du son,</i> clair, sonore, PLAT. <i>Phil. 51</i> d ; DÉM. <i>403, 16 ;</i> λαμπρὰ κηρύσσειν, EUR. <i>Her. 864,</i> publier à haute et intelligible voix ; λαμπρὸν ἀνολολύζειν, PLUT. <i>M. 258</i> b, <i>768</i> d, éclater en cris de douleur ;<br><b>      2</b> <i>fig</i>. clair, évident, manifeste ; <i>au propre en parl. de traces de pas,</i> XÉN. <i>Cyn. 5, 5 ; fig. en parl. de témoignage,</i> ESCHL. <i>Eum. 797 ; d’une victoire devenue certaine,</i> THC. <i>7, 55 ;</i><br><b>   III</b> <i>p. ext</i>. fort, véhément, <i>en parl. du vent,</i> ESCHL. <i>Ag. 1181 ;</i> HDT. <i>2, 96 ;</i> POL. <i>1, 44, 3, etc</i>. vent fort <i>ou</i> frais, <i>de Cléon comparé à un ouragan,</i> AR. <i>Eq. 430 ;</i> λ. μάχη, POL. <i>10, 12, 5,</i> combat fortement disputé ; λ. κίνδυνος, POL. <i>1, 45, 9,</i> danger grave.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>Cyr. 1, 4, 17, etc</i>. ARSTT. <i>H.A. 5, 14, 7, etc.</i> <i>• Sup</i>. -ότατος, IL. <i>22, 30, etc. ;</i> THC. <i>1, 138 ;</i> XÉN. <i>Eq. 11, 6 ;</i> PLAT. <i>Hipp. mi. 368</i> d ; DÉM. <i>564, 11</i>.<br><span><b>Étym</b>. λάμπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαμπρος - λαμπρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G2987":"<h1>lamprotes</h1>\n<p>Strong n° 2987 <i>Prononciation [lam-prot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>éclat, brillance, vive lumière</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαμπρότης, ητος (ἡ) :<br>   I</b> éclat, splendeur, PLUT. <i>M. 626</i> d ; <i>en parl. d’armes,</i> POL. <i>11, 9, 1 ; p. anal. en parl. de la voix,</i> éclat, force, PLUT. <i>Phil. 11 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> aspect brillant, belle apparence, d’une armée, XÉN. <i>An. 1, 2, 18 ;</i> d’un cheval, XÉN. <i>Eq. 11, 9 ; en parl. du style,</i> PLUT. <i>M. 25</i> b ; <i>au pl</i>. λαμπρότητες τοῦ λόγου, PHILSTR. <i>527,</i> mots brillants ;<br><b>      2</b> éclat, distinction, gloire, honneur, HDT. <i>2, 101 ;</i> THC. <i>6, 17, etc. ;</i> ISOCR. <i>211</i> b, etc. ; DS. <i>16, 66, etc. ; au pl</i>. THC. <i>4, 62 ;</i><br><b>      3</b> magnificence, générosité : λ. ψυχῆς, POL. <i>32, 23, 1,</i> grandeur d’âme ; <i>particul</i>. munificence, libéralité, DÉM. <i>565, 22</i>.<br><span><b>Étym</b>. λαμπρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαμπροτης - λαμπρότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2988":"<h1>lampros</h1>\n<p>Strong n° 2988 <i>Prononciation [lam-proce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>d'une façon splendide, magnifiquement\n<ol type=\"a\">\n<li>d'une vie somptueuse</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαμπρῶς</b>, <i>adv. :</i><br><b>   I</b> avec éclat, <i>d’où :</i><br><b>      1</b> <i>au propre,</i> avec splendeur <i>ou</i> magnificence, XÉN. <i>Cyr. 2, 4, 1 ;</i> ARSTT. <i>Nic. 4, 2, 11 ;</i><br><b>      2</b> <i>fig</i>. avec gloire, DH. <i>9, 24 ;</i><br><b>      3</b> avec force, avec véhémence, THC. <i>7, 71 ;</i><br><b>   II</b> clairement :<br><b>      1</b> en termes clairs (dire) THC. <i>8, 67 ; joint à</i> κοὐδὲν αἰνικτηρίως, ESCHL. <i>Pr. 833 ;</i><br><b>      2</b> <i>p. suite,</i> ouvertement, THC. <i>1, 49 ; 2, 7, etc. ;</i><br><b>      3</b> <i>p. ext</i>. d’une façon décisive : λ. νικᾶν, ARR. <i>An. 2, 4, 10,</i> remporter une victoire décisive.<br><span>•<i> Cp</i>. -ότερον, EUR. <i>Epist. 5 ;</i> <i>• Sup</i>. -ότατα, XÉN. <i>Cyr. 2, 4, 1</i>.<br><span><b>Étym</b>. λαμπρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαμπρως - λαμπρῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2989":"<h1>lampo</h1>\n<p>Strong n° 2989 <i>Prononciation [lam'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>briller</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λάμπω</b> <span>(<i>f</i>. λάμψω, <i>ao</i>. ἔλαμψα, <i>pf</i>. λέλαμπα, <i>au sens du prés</i>.)</span><br><b>   I <i>intr. :</i><br>      1</b> briller, resplendir, <i>en parl. de l’éclat des armes,</i> IL. <i>10, 154 ; 11, 66 ; du soleil,</i> EUR. <i>Ion 83 ; du jour,</i> EMPÉD. <i>84, 4 Diels, du feu,</i> SOPH. <i>Ant. 1007 ; de l’éclat des yeux,</i> IL. <i>13, 474 ; en parl. d’une pers. :</i> λάμπε δὲ χαλκῷ, IL. <i>12, 463</i> (Hector) brillait de l’éclat de ses armes d’airain ;<br><b>      2</b> <i>p. anal</i>. briller de l’éclat de la jeunesse, EUR. <i>Ion 476 ;</i> de la beauté, PLAT. <i>Phædr. 250</i> d ; <i>fig</i>. λάμπει κλέος, PD. <i>O. 1, 23 ;</i> ἀρετά, PD. <i>I. 1, 22 ;</i> EUR. <i>Andr. 777 ;</i> δίκα, ESCHL. <i>Ag. 774,</i> la gloire, la vertu, la justice resplendit ;<br><b>      3</b> devenir <i>ou</i> être illustre, AR. <i>Vesp. 62 ;</i><br><b>      4</b> <i>en parl. de la voix,</i> éclater, résonner avec force : παιὰν λάμπει, SOPH. <i>O.R. 186,</i> le péan retentit ;<br><b>   II <i>tr.</i></b> faire briller, faire resplendir, EUR. <i>Hel. 1131, Ph. 226 ;</i> ANTH. <i>6, 249 ;</i><br><b><i>Moy.</i></b> briller, resplendir : λαμπομένης κόρυθος, IL. <i>16, 71,</i> casque brillant ; τεύχεσι λαμπόμενος, IL. <i>20, 46,</i> resplendissant de l’éclat des armes.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. itér. 3 sg</i>. λάμπεσκε, EMPÉD. <i>321 Stein</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *leh₂p-, briller.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαμπω - λάμπω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2990":"<h1>lanthano</h1>\n<p>Strong n° 2990 <i>Prononciation [lan-than'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être caché, secrètement, à l'insu de, sans savoir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λανθάνω</b> <span>(<i>f</i>. λήσω, <i>ao.2</i> ἔλαθον <span>[ᾰ]</span> <i>pf</i>. λέληθα)</span><br><b>   I <i>intr.</i></b> être caché, demeurer caché :<br><b>      1</b> <i>abs. au part. ao.2</i> λαθών : ἆλτο λαθών, IL. <i>12, 390,</i> il sauta sans être aperçu ; <i>cf</i>. SOPH. <i>Ant. 532 ;</i><br><b>      2</b> <i>avec un acc. de pers. :</i> λανθάνειν τινά, demeurer caché à qqn, ignoré de qqn (<i>cf. lat</i>. latere aliquem) : οὐ λῆθε Διὸς νόον, IL. <i>15, 461,</i> cela n’échappa point à l’esprit de Zeus ; τουτί μ' ἐλελήθει, AR. <i>Nub. 380,</i> cela m’était demeuré caché, <i>càd</i>. m’était inconnu ; <i>qqf. impers. avec l’acc. :</i> περὶ τούτου λέληθε τὸ πλῆθος, XÉN. <i>Hier. 2, 5,</i> cela est demeuré ignoré de la foule ; σὲ δὲ λέληθε περὶ τοῦτο, PLAT. <i>Leg. 903</i> c, là-dessus tu es resté dans l’ignorance ;<br><b>      3</b> <i>très souv. accompagné d’un part. et d’un acc. de pers. :</i> πάντας ἐλάνθανε δάκρυα λείϐων, OD. <i>8, 93,</i> il versait des larmes à l’insu de tous, <i>litt</i>. il était caché à tous versant des larmes ; ἔλαθον ἡμᾶς ἀποδράντες, XÉN. <i>Cyr. 4, 2, 5,</i> ils s’enfuirent à notre insu ; ὅπως μὴ λήσουσιν αὐτοὺς αἱ νῆες ἀφορμηθεῖσαι, THC. <i>8, 10,</i> pour que les navires ne pussent s’éloigner à leur insu ; <i>cf</i>. IL. <i>13, 273 ;</i> OD. <i>12, 17, etc. ;</i> HDT. <i>8, 25, etc. ; ou sans acc. et, dans ce cas, l’action marquée par le part. doit être comprise d’ord. comme ignorée du sujet lui-même, et peut se traduire</i> « à mon insu, à ton insu », <i>etc. :</i> ὁ Κροῖσος φονέα ἐλάνθανε (<i>s.-e</i>. ἑωυτόν) βόσκων, HDT. <i>1, 44,</i> Crésus nourrissait à son insu le meurtrier ; δουλεύων λέληθας, AR. <i>Vesp. 517,</i> tu ne t’aperçois pas que tu es esclave (tu es esclave à ton insu) ; μὴ δι' ἄγνοιαν λάθω τι παρανομήσας, XÉN. <i>Mem. 1, 2, 34,</i> pour que par ignorance je n’aille pas violer la loi sans m’en douter ; <i>qqf. au contraire l’action doit être comprise comme ignorée d’une pers. autre que le sujet :</i> μὴ λάθῃ (ἡμᾶς) φύγδα βάς, ESCHL. <i>Eum. 256,</i> de peur qu’il ne s’enfuie à notre insu (<i>cf</i>. IL. <i>13, 721 ;</i> HDT. <i>8, 5, etc</i>.) ;<br><b>      4</b> <i>avec une conj. :</i> οὐ λανθάνεις με ὅτι, XÉN. <i>Mem. 3, 5, 24,</i> il ne m’échappe pas que tu, <i>etc. ; de même avec</i> ὡς, εἰ, PLAT. <i>Theæt. 174</i> b, <i>etc. ; ou avec un relat. :</i> οὔκουν με οἷα πράττει λανθάνει, AR. <i>Eq. 465,</i> je n’ignore pas ce qu’il fait ;<br><b>      5</b> <i>avec un inf. :</i> ἔλαθεν ἐμπεσεῖν, ES. <i>340 Halm,</i> il tomba sans s’en apercevoir ;<br><b>      6</b> <i>avec une prop. inf. :</i> λέληθε Θεόδωρον εἶναι (<i>p</i>. ὄντα) PAUS. <i>9, 41, 1,</i> on n’avait pas remarqué que c’était Théodôros ;<br><b>   II</b> <i>tr. (seul. à l’ao.2 épq</i>. λέλαθον) faire oublier : τινά τινος, IL. <i>15, 60 ;</i> POÈT. (STOB. <i>Ecl. 1, 174</i>) qqe ch. à qqn ; <i>mais postér</i>. λέλαθον, <i>au sens intr. c</i>. ἔλαθον, A. RH. <i>2, 226 ; 3, 779 ;</i> ORPH. <i>Arg. 879 ;</i><br><b>   III</b> <i>au sens du moy</i>. oublier : τινός, ANTH. <i>7, 25,</i> qqe ch. ; ἔλαθεν αὐτὸν δοῦναι, <i>etc</i>. PLUT. <i>Arist. 17,</i> il oublia de donner, <i>etc. ;</i><br><b>   IV</b> <i>part. fut</i>. λησόμενος, <i>au sens pass</i>. devant être oublié (<i>lat</i>. obliviscendus) SOPH. <i>El. 1249 ;</i><br><b><i>Moy</i>. λανθάνομαι</b> <span>(<i>f</i>. λήσομαι, <i>ao.2</i> ἐλαθόμην, <i>pf</i>. λέλησμαι)</span><br><b>   I</b> oublier, <i>abs</i>. IL. <i>9, 537 ; 11, 790 ; avec un gén. de pers. ou de chose,</i> IL. <i>5, 834, etc. ;</i> OD. <i>1, 65, 308, etc. ;</i> ESCHL. <i>Suppl. 731 ;</i> SOPH. <i>El. 1287, etc. ;</i> PLAT. <i>Phædr. 252</i> a, <i>etc. ; ou avec un relat. :</i> λελασμένος ὅσσ' ἐπεπόνθει, OD. <i>13, 92,</i> ayant oublié tout ce qu’il avait souffert ;<br><b>   II</b> passer sous silence, omettre, ESCHL. <i>Ag. 39 ; p. suite,</i> oublier, négliger, IL. <i>9, 537 ;</i><br><b>   III</b> échapper à, être inconnu à, être ignoré de, ne pas être remarqué par :<br><b>      1</b> <i>avec un rég. à l’acc</i>. ARSTT. <i>An. pr. 2, 19 ;</i> A. RH. <i>3, 737 ;</i> LUC. <i>Sacr. 14 ;</i><br><b>      2</b> <i>avec un part. en apposit. :</i> ὅπως λελάθοιτο τεκοῦσα, HÉS. <i>Th. 471,</i> afin que son enfantement fût ignoré.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. dor</i>. λασῶ <span>[ᾱ]</span> THCR. <i>Idyl. 14, 9. Ao.1 poét</i>. ἔλησα, <i>2 sg. dor</i>. ἔλασας <span>[λᾱ]</span> ALC. <i>95 ; opt. 3 sg</i>. λήσειεν, NIC. <i>Al. 280. Ao.2 sbj. 3 sg</i>. λάθῃσι, IL. <i>22, 191, etc. ; inf. dor</i>. λαθέμεν, PD. <i>O. 1, 64. Ao.2 avec redoubl</i>. λέλαθον, IL. <i>15, 60 ;</i> A. RH. <i>3, 779 ;</i> ORPH. <i>Arg. 879. Pf. inf. dor</i>. λελαθέμεν <span>[ᾱ]</span> PD. <i>O. 1, 64. Pl.q.pf. 2 sg. att</i>. ἐλελήθης, AR. <i>Eq. 822, 1044 ; 3 sg</i>. ἐλελήθη, AR. <i>Nub. 380 ; ion</i>. ἐλελήθεε, HDT. <i>6, 79 ; 9, 22. — Pass. ao. inf. dor</i>. λασθῆμεν (<i>p</i>. λασθῆναι) THCR. <i>Idyl. 2, 46. Fut. ant</i>. λελήσομαι, EUR. <i>Alc. 198. — Moy. fut</i>. λήσομαι, <i>au sens pass</i>. SOPH. <i>El. 1249 ; fut. dor</i>. λασεῦμαι <span>[ᾱ]</span> THCR. <i>Idyl. 4, 39. Ao.1, 2 sg</i>. ἐλήσαο, NONN. <i>D. 33, 149 ; part. fém. dor</i>. λασαμένα <span>[λᾱνᾱ]</span> MOSCH. <i>3, 61. Ao.2 opt. dor</i>. λαθοίμαν, SOPH. <i>El. 1287 ;</i> EUR. <i>Suppl. 86 ; 3 pl</i>. λαθοίατο, OD. <i>10, 236. Ao.2 avec redoubl</i>. λελαθόμην, IL. <i>4, 127, etc. ;</i> HÉS. <i>Th. 471. Pf. pass</i>. SOPH. <i>El. 342 ;</i> EUR. <i>Ph. 850 ;</i> PLAT. <i>Phædr. 252 ; épq. et dor</i>. λέλασμαι, IL. <i>5, 834 ; 11, 313 ;</i> OD. <i>24, 40 ;</i> THCR. <i>Idyl. 2, 158</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *leh₂-, passer inaperçu <i>ou</i> caché ; <i>cf. lat</i>. lateō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λανθανω - λανθάνω</font>\n<br><br>forme prolongée d'un verbe primaire, utilisé en variante à certains temps</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G2991":"<h1>laxeutos</h1>\n<p>Strong n° 2991 <i>Prononciation [lax-yoo-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>taillage d'une pierre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λαξευτός, ή, όν</b>, taillé dans la pierre <i>ou</i> fait en pierres de taille, SPT. <i>Deut. 4, 44 ;</i> NT. <i>Luc. 23, 53</i>.<br><span><b>Étym</b>. λαξεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαξευτος - λαξευτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2992":"<h1>laos</h1>\n<p>Strong n° 2992 <i>Prononciation [lah-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un peuple, une tribu, une nation, tous ceux qui ont un même langage</li>\n<li>les populations rassemblées ensemble n'importe où</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>λαός, οῦ (ὁ)</b> <span>[ᾱ]</span><br><b>A</b> peuple, <i>en tant que réunion d’hommes,</i> foule, masse, <i>p. opp. à</i> δῆμος, agglomération politique, <i>ou à</i> ὅμαδος, foule confuse, <i>avec un sens légèrement péjoratif,</i> IL. <i>7, 306, p. suite :</i><br><b>   I</b> foule des guerriers, armée (chefs et soldats) IL. <i>2, 115 ; 7, 434, etc. ;</i> ESCHL. <i>Pers. 91 ;</i> λαὸν ἀγείρειν, IL. <i>16, 129,</i> rassembler l’armée ; <i>au pl</i>. IL. <i>2, 578 ; 4, 91 ; périphr</i>. στρατὸς λαῶν, IL. <i>4, 76 ;</i> ἔθνος λαῶν, IL. <i>13, 495 ; particul. :</i><br><b>      1</b> les soldats, <i>p. opp. aux chefs,</i> IL. <i>2, 365 ; 13, 108 ;</i><br><b>      2</b> les combattants à pied, <i>p. opp. aux chars ou aux chevaux,</i> IL. <i>7, 342 ;</i><br><b>      3</b> l’armée de terre, <i>p. opp. à la flotte,</i> IL. <i>4, 76 ; 9, 424 ; 10, 14 ;</i><br><b>   II</b> foule du peuple, <i>p. opp. aux guerriers,</i> IL. <i>17, 226 ; 24, 611 ;</i> OD. <i>3, 214, 304, etc. ; particul</i>. paysans, λαοὶ ἀγροιῶται, IL. <i>11, 676 (cf</i>. γεωργικὸς λεώς, AR. <i>Pax 920</i>) ; artisans, IL. <i>17, 390 (cf</i>. χειρῶναξ λεώς, SOPH. <i>fr. 724</i>) ; marins, OD. <i>14, 248 (cf</i>. ναυτικὸς λεώς, ESCHL. <i>Pers. 383) ; d’où en gén</i>. λαοὶ ἐγχώριοι, ESCHL. <i>Suppl. 517,</i> les nationaux, les habitants du pays, μέροπες λ. ESCHL. <i>Suppl. 85,</i> les mortels ;<br><b>   III</b> foule, <i>en gén., particul</i>. foule au théâtre, AR. <i>Ran. 676 ;</i> dans l’ἐκκλησία sur la place publique, AR. <i>Eq. 163 ; d’où la formule</i> ἀκούετε, λεῴ, AR. <i>Pax 551, Av. 448,</i> écoutez, vous tous ; δεῦρ' ἴτε, πάντες λεῴ, ARSTT. <i>fr. 346,</i> venez ici, vous tous ; ὁ πολὺς λεώς, PLAT. <i>Rsp. 458</i> d, la foule, la multitude ;<br><b>   IV</b> <i>postér. dans les</i> SPT. <i>et le</i> NT. la foule des hommes, <i>p. opp. aux femmes, ou</i> le peuple, <i>p. opp. aux prêtres et aux lévites ; dans le</i> NT. les Juifs, <i>et, postér</i>. les Chrétiens, <i>p. opp. aux païens ; dans les écrivains ecclésiast</i>. le peuple (les laïques) <i>p. opp. au clergé ;</i><br><b>B</b> peuple, <i>en tant que nation :</i> Δωριεὺς λαός, PD. <i>O. 8, 30 ;</i> Λυδῶν τε λ. καὶ Φρυγῶν, ESCHL. <i>Pers. 770 ;</i> Ἀχαιῶν λ. IL. <i>6, 223 ; 16, 156 ;</i> SOPH. <i>Ph. 1243,</i> le peuple dorien, lydien, phrygien, achéen, <i>càd</i>. grec.<br><span><b><span class=\"arrow\"></span></b> <i>Ion. et att</i>. λεώς, HDT. <i>1, 22 ; 8, 136 ; chez les Épq. et les Lyr. seul</i>. λαός ; <i>chez les Trag</i>. λαός <i>et</i> λεώς, <i>ce dernier surt. au nom. et à l’acc. sg. ; rare en prose, sauf dans certaines locutions (v. ci-dessus</i>). — <i>Sel. une légende de</i> PD. <i>O. 9, 66, apparenté à</i> λᾶας, pierre ; <i>cf</i>. IL. <i>24, 611</i>.<br><span><b>Étym</b>. <i>p.-ê. indo-europ</i>. *leh₂-uo-, bande de gens, <i>autrement pré-grec</i>.</span></span><br><br>\n➁ <b>λᾶος</b>, <i>v</i>. λᾶας.<br><br>\n<b>λᾶας</b>, <i>p. contr</i>. <b>λᾶς</b>, <i>gén</i>. λάαος-λᾶος, <i>dat</i>. λᾶϊ, <i>acc</i>. λᾶαν-λᾶν ; <i>plur</i>. λᾶες, λάων, λάεσι, λᾶας ; <i>duel</i> λᾶε (ὁ, ἡ) pierre, <i>particul. :</i><br><b>      1</b> pierre, <i>en gén</i>. IL. <i>2, 319, etc. ; comme projectile,</i> EUR. <i>Ph. 1157 ;</i><br><b>      2</b> pierre pour bâtir, ANTH. <i>9, 688 ;</i><br><b>      3</b> rocher, NIC. <i>Th. 45 ;</i> quartier de roc, <i>en parl. de la pierre que roule Sisyphe,</i> OD. <i>11, 593, 595</i>.<br><span><b><span class=\"arrow\"></span></b> ἡ λᾶας, NIC. <i>Th. 45 ; Décl. non contracte : nom</i>. λᾶας, IL. <i>4, 521 ;</i> OD. <i>11, 597 ; acc</i>. λᾶαν, IL. <i>2, 319 ;</i> OD. <i>11, 593. — Décl. contracte : Gén</i>. λᾶος, IL. <i>12, 462 ; ou</i> λάου, SOPH. <i>O.C. 197. Dat</i>. λᾶϊ, A. RH. <i>4, 1489 ;</i> NIC. <i>Th. 18, etc. Acc</i>. λᾶα, A. PL. <i>4, 279 ;</i> ANTH. <i>9, 708 ;</i> CALL. <i>fr. 104. Plur. nom</i>. λᾶες, CALL. <i>Del. 25, etc. ; gén</i>. λάων, IL. <i>12, 29 ; dat</i>. λάεσι, ANTH. <i>9, 670, etc. ;</i> λάεσιν, ANTH. <i>9, 152 ; ou</i> λάεσσι, ANTH. <i>9, 688 ;</i> MAN. <i>6, 612 ; acc</i>. λᾶας, MAN. <i>6, 417. Duel nom</i>. λᾶε, IL. <i>23, 329, etc</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαος - λαός</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td>Dans le Grec classique\n<br><br> - indique le peuple organisé dans un corps politique\n<br><br> - un peuple inorganisé dispersé dans le Grec Biblique\n<br><br> - le peuple choisi de Dieu\n<br><br> - le peuple d'une cité païenne</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n143 fois dans 139 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Marc (3)</li>\n<li>Luc (36)</li>\n<li>Jean (3)</li>\n<li>Actes (48)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (13)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (9)</li>\n</ul>\n</td></tr>\n</table>","G2993":"<h1>Laodikeia</h1>\n<p>Strong n° 2993 <i>Prononciation [lah-od-ik'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Laodicée (Angl. Laodicea) = « justice du peuple »\n<ol><li>cité de Phrygie, située sur le fleuve Lycus non loin de Colosses. Détruite par un tremblement de terre en 66 après J.C. et reconstruite. Elle était le siège d'une église chrétienne.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λαοδικεια - Λαοδίκεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Colossiens (4)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2994":"<h1>Laodikeus</h1>\n<p>Strong n° 2994 <i>Prononciation [lah-od-ik-yooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un Laodicéen, un habitant de Laodicée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λαοδικευς - Λαοδικεύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Colossiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2995":"<h1>larugx</h1>\n<p>Strong n° 2995 <i>Prononciation [lar'-oongks]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la gorge\n<ol type=\"a\">\n<li>l'instrument ou l'organe de la parole</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λάρυγξ, υγγος (ὁ)</b> <span>[ᾰ]</span><br><b>      1</b> larynx, <i>partie supérieure de la trachée-artère,</i> ARSTT. <i>H.A. 1, 12, 1 ; 4, 9, 2 ; confondue par les poètes avec le</i> φάρυγξ (ARSTT. <i>H.A. 4, 9, 1</i>) ;<br><b>      2</b> <i>p. suite,</i> gorge, gosier, EUR. <i>Cycl. 158 ;</i> AR. <i>Eq. 1363, Ran. 575 ;</i> EUB. (ATH. <i>113</i> f).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαρυγξ - λάρυγξ</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2996":"<h1>Lasaia</h1>\n<p>Strong n° 2996 <i>Prononciation [las-ah'-yah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lasée (Angl. Lasea) = « poilu, hirsute »\n<ol><li>cité en Crète sur la côte sud, non loin de Beaux-Ports</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λασαια - Λασαία</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2997":"<h1>lascho</h1>\n<p>Strong n° 2997 <i>Prononciation [las'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>casser, crépiter, tomber avec fracas</li>\n<li>éclater en morceaux avec un craquement, éclater</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λάσκω</b> <span>(<i>f</i>. λακήσομαι, <i>ao.1</i> ἐλάκησα, <i>ao.2</i> ἔλακον, <i>d’où inf</i>. λακεῖν <span>[ᾰ]</span> <i>pf</i>. λέλακα <span>[λᾱ]</span> <i>au sens d’un prés</i>.)</span><br><b>   I</b> <i>seul. à l’ao.2,</i> craquer : λάκε χαλκός, IL. <i>14, 25 ;</i> ἀσπίς, IL. <i>20, 277,</i> l’armure d’airain, le bouclier craqua ; λάκε ὀστέα, IL. <i>13, 616,</i> les os craquèrent ; ἐλάκησε μέσος, NT. <i>Ap. 1, 18,</i> il creva par le milieu ;<br><b>   II</b> <i>p. ext</i>. résonner, retentir avec force, <i>d’où :</i><br><b>      1</b> crier, pousser un cri retentissant, <i>en parl. d’animaux, en parl. du faucon,</i> IL. <i>22, 141 ; du rossignol dans les serres du faucon,</i> HÉS. <i>O. 205 ; des aboiements de Scylla,</i> OD. <i>12, 85 ; rar. en prose, en parl. de l’aigle,</i> ARSTT. <i>H.A. 9, 32, 3 ; en parl. de pers</i>. AR. <i>Pax 381, 384 ; avec un acc</i>. λ. ὀλολυγμόν, ESCHL. <i>Ag. 596 ;</i> βοάν, EUR. <i>El. 1214,</i> pousser des hurlements, un cri ; <i>en mauv. part, avec double acc</i>. ξένης δ' ὕπερ τοιαῦτα λάσκεις τοὺς ἀναγκαίους φίλους, EUR. <i>Andr. 671,</i> c’est pour une étrangère que tu outrages ainsi tes meilleurs amis ;<br><b>      2</b> faire entendre un chant : πρὸς αὐλόν, EUR. <i>Alc. 346,</i> en se faisant accompagner de la flûte ;<br><b>      3</b> dire à haute voix, annoncer, proclamer : ἀγγελίας, EUR. <i>I.T. 461,</i> des nouvelles ; <i>cf</i>. ESCHL. <i>Ag. 1426 ; particul. en parl. d’oracles,</i> SOPH. <i>Tr. 824 ;</i> AR. <i>Pl. 39 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. λασκήσομαι, <i>ao.2</i> ἐλακόμην, <i>ao.2 épq. avec redoubl</i>. λελακόμην <span>[ᾰ]</span>)</span> retentir avec force, <i>particul</i>. hurler, aboyer, HH. <i>Merc. 145</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 avec redoubl. 3 sg</i>. λέλακε <span>[ᾰ]</span> OPP. <i>C. 2, 141. Pf. épq</i>. λέληκα, HÉS. <i>O. 207 ;</i> SIM. AM. <i>fr. 7, 15 ; en prose seul</i>. ARSTT. <i>H.A. 9, 32, 3 ; part</i>. λεληκώς, IL. <i>22, 141, mais fém</i>. λελακυῖα <span>[λᾰ]</span> OD. <i>12, 85. — Moy. ao.2 épq. avec redoubl. 3 pl</i>. λελάκοντο, HH. <i>Merc. 145</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λασχω - λακάω</font>\n<br><br>forme renforcée d'un verbe primaire qui n'apparaît pour ses variantes qu'à certains temps</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2998":"<h1>latomeo</h1>\n<p>Strong n° 2998 <i>Prononciation [lat-om-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tailler ou découper des pierres</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λατομέω-ῶ</b> <span>[ᾱ]</span><br><b>      1</b> tailler des pierres, DS. <i>3, 12 ; avec l’acc. :</i> πέτρας, DS. <i>5, 39, m. sign. ;</i><br><b>      2</b> tailler dans la pierre, SPT. <i>Ex. 21, 33</i>.<br><span><b>Étym</b>. λατόμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λατομεω - λατομέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2999":"<h1>latreia</h1>\n<p>Strong n° 2999 <i>Prononciation [lat-ri'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>service ou culte rendu pour louer\n<ol type=\"a\">\n<li>tout service ou ministère : le service de Dieu</li>\n</ol>\n</li>\n<li>le service et l'adoration de Dieu selon les exigences de la loi Lévitique</li>\n<li>procéder à un service sacré</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λατρεία, ας (ἡ) :<br>   I</b> service, <i>particul. :</i><br><b>      1</b> service de gens à gages, service de mercenaire, ESCHL. <i>Pr. 996 ;</i> SOPH. <i>Tr. 830 ; au pl</i>. SOPH. <i>Aj. 503 ;</i> EUR. <i>Ph. 225, etc. ;</i><br><b>      2</b> <i>p. ext</i>. λ. τοῦ θεοῦ, PLAT. <i>Ap. 23</i> c ; θεῶν, PLAT. <i>Phædr. 244</i> e, service d’un dieu <i>ou</i> des dieux, culte, adoration ; <i>abs</i>. SPT. <i>Ex. 12, 25 ; 1 Macc. 1, 43, etc. ;</i><br><b>      3</b> soins à donner au corps <i>ou</i> à l’âme, PLUT. <i>M. 107</i> c ;<br><b>   II</b> être <i>ou</i> pays en servitude, PD. <i>N. 4, 54</i>.<br><span><b>Étym</b>. λατρεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λατρεια - λατρεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Romains (2)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>"};
